var Q22 = [
{n:1, q:'La actividad de policía que ejercen los poderes públicos se caracteriza por:', o:{a:'Asegurar a todos los ciudadanos una calidad de vida estandarizada.',b:'Garantizar la seguridad ciudadana.',c:'Incidir en la esfera jurídica de los ciudadanos para condicionarla o limitarla.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'La actividad de policía administrativa consiste en intervenir en la esfera jurídica de los ciudadanos para condicionar o limitar su actividad en aras del interés general.'}},
{n:2, q:'Entre las medidas de policía utilizadas por los poderes públicos se halla/n:', o:{a:'Los actos de constatación como son los registros y los inventarios.',b:'La protección de personas y bienes.',c:'La atención de necesidades relacionadas con los bienes que prestan las empresas privadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Las medidas de policía administrativa incluyen los actos de constatación (registros, inventarios) así como las órdenes, prohibiciones, autorizaciones y sanciones.'}},
{n:3, q:'Entre las medidas de policía utilizadas por los poderes públicos se halla/n:', o:{a:'Los actos de comprobación como los controles y las inspecciones.',b:'Los actos administrativos habilitantes como las licencias o autorizaciones.',c:'Los reglamentos y normas generales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Las medidas de policía administrativa abarcan los actos de comprobación (controles, inspecciones), los actos habilitantes (licencias, autorizaciones) y los reglamentos y normas generales.'}},
{n:4, q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, asigna a las Policías Locales las funciones de Policía Administrativa, en su artículo...', o:{a:'51.3.',b:'53.1.',c:'53.3.',d:'51.1.'}, correct:'b', why:{b:'El art. 53.1 de la LO 2/1986 de Fuerzas y Cuerpos de Seguridad asigna a las Policías Locales las funciones de Policía Administrativa.'}},
{n:5, q:'La Constitución Española de 1978 se refiere al medio ambiente en su artículo:', o:{a:'45.',b:'42.',c:'40.',d:'39.'}, correct:'a', why:{a:'El art. 45 de la Constitución Española de 1978 recoge el derecho al medio ambiente y el deber de conservarlo.'}},
{n:6, q:'Con respecto al medio ambiente, el art.45 de la Constitución Española de 1978 dispone que:', o:{a:'Todos tienen el derecho a disfrutarlo.',b:'Todos tienen el deber de conservarlo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 45 CE establece tanto el derecho de todos a disfrutar de un medio ambiente adecuado como el deber de conservarlo.'}},
{n:7, q:'Según el art.45 de la Constitución Española de 1978, los poderes públicos velarán por la utilización racional de todos los recursos naturales, con el fin de:', o:{a:'Proteger y mejorar la calidad de vida apoyándose en la indispensable solidaridad colectiva.',b:'Defender y restaurar el medio ambiente, apoyándose en la indispensable solidaridad colectiva.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 45.2 CE establece que los poderes públicos velarán por la utilización racional de los recursos naturales para proteger y mejorar la calidad de vida y defender y restaurar el medio ambiente.'}},
{n:8, q:'Para quienes violen lo dispuesto en el art.45 de la Constitución Española de 1978, en materia de medio ambiente, en los términos que la ley fije, se establecerán sanciones:', o:{a:'Penales, civiles y administrativas.',b:'Administrativas, en todo caso.',c:'Penales o, en su caso administrativas.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art. 45.3 CE establece que para quienes violen el medio ambiente se establecerán sanciones penales o, en su caso, administrativas, así como la obligación de reparar el daño causado.'}},
{n:9, q:'En lo que respecta al medio ambiente, y según la Ley 7/1985 de Régimen Local, los municipios, en los términos de la legislación del Estado y de las CCAA, tienen competencias propias en...', o:{a:'Medio ambiente urbano.',b:'Zonas forestales propias o cedidas por la Comunidad Autónoma.',c:'Protección del medio ambiente acuático.',d:'Protección de la naturaleza urbana.'}, correct:'a', why:{a:'El art. 25 de la LRBRL establece que los municipios tienen competencias propias en materia de medio ambiente urbano.'}},
{n:10, q:'En lo que respecta al medio ambiente, y según la Ley 7/1985 de Régimen Local, los municipios, en los términos de la legislación del Estado y de las CCAA, tienen competencias propias en...', o:{a:'Parques y jardines en suelos públicos y privados.',b:'Abastecimiento de agua potable a domicilio, y gestión de la sequía.',c:'Gestión de los residuos sólidos urbanos.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art. 25 LRBRL establece que los municipios tienen competencias propias en gestión de los residuos sólidos urbanos.'}},
{n:11, q:'En lo que respecta al medio ambiente, y según la Ley 7/1985 de Régimen Local, los municipios, en los términos de la legislación del Estado y de las CCAA, tienen competencias propias en...', o:{a:'Evacuación y tratamiento de aguas residuales.',b:'Protección contra la contaminación lumínica en zonas urbanas.',c:'Protección de la salubridad pública.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 25 LRBRL establece competencias municipales propias en evacuación y tratamiento de aguas residuales, protección contra la contaminación lumínica en zonas urbanas y protección de la salubridad pública.'}},
{n:12, q:'En el ámbito estatal, el control ambiental de actividades se encuentra regulado en...', o:{a:'La Ley 21/2013.',b:'El Real Decreto 550/2013.',c:'El Real Decreto Legislativo 2/2015.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 21/2013, de 9 de diciembre, de evaluación ambiental, regula en el ámbito estatal el control ambiental de actividades.'}},
{n:13, q:'En el ámbito estatal, el control ambiental de actividades se encuentra regulado en...', o:{a:'La Ley 6/2014.',b:'El Real Decreto 551/2017.',c:'El Real Decreto Legislativo 1/2016.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El Real Decreto Legislativo 1/2016, por el que se aprueba el texto refundido de la Ley de prevención y control integrados de la contaminación, regula también en el ámbito estatal el control ambiental.'}},
{n:14, q:'En el ámbito de la Comunitat Valenciana, el control ambiental de actividades se encuentra regulado en...', o:{a:'El Decreto 815/2013.',b:'La Ley 6/2014.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'En el ámbito de la Comunitat Valenciana, el control ambiental de actividades se regula en el Decreto 815/2013 y en la Ley 6/2014.'}},
{n:15, q:'Por razones de interés general, aquellas actividades que tienen una significativa incidencia medioambiental:', o:{a:'Son sometidas por la ley a un sistema de autorización previa.',b:'Deben adaptarse a lo establecido en el art.42 de la Constitución Española.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Las actividades con significativa incidencia medioambiental son sometidas por la ley a un sistema de autorización previa para garantizar la protección del medio ambiente.'}},
{n:16, q:'Son actividades con incidencia ambiental las que son susceptibles de:', o:{a:'Producir molestias.',b:'Alterar las condiciones de salubridad del medio ambiente.',c:'Ocasionar riesgos o daños a las personas o al medio ambiente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 6/2014 CV establece que son actividades con incidencia ambiental las susceptibles de producir molestias, alterar las condiciones de salubridad del medio ambiente u ocasionar riesgos o daños.'}},
{n:17, q:'En lo que respecta a las competencias municipales en el control ambiental de actividades, indique la respuesta que no es correcta:', o:{a:'Corresponde a los respectivos ayuntamientos la inscripción, gestión y mantenimiento de los datos relativos a los instrumentos de competencia municipal en las correspondientes secciones del Registro Ambiental de Instalaciones de la Comunitat Valenciana.',b:'En caso de que la actividad proyectada vaya a ubicarse en suelo no urbanizable el ayuntamiento debe emitir, en su caso, la declaración de interés comunitario.',c:'El órgano competente para la tramitación y resolución del procedimiento de autorización ambiental integrada, es el Ayuntamiento.',d:'Corresponde a los ayuntamientos, en el ámbito de sus respectivas competencias, la vigilancia y el control del cumplimiento de las condiciones establecidas en el respectivo instrumento de intervención ambiental.'}, correct:'c', why:{c:'La opción c) es incorrecta: la tramitación y resolución del procedimiento de autorización ambiental integrada corresponde a la Dirección General competente de la Conselleria de Medio Ambiente, no al Ayuntamiento.'}},
{n:18, q:'En lo que respecta a las competencias municipales en el control ambiental de actividades, indique la respuesta que no es correcta:', o:{a:'El Ayuntamiento es órgano sustantivo ambiental para la tramitación y resolución del procedimiento de licencia ambiental.',b:'El Ayuntamiento es órgano sustantivo ambiental para la recepción de la comunicación de puesta en funcionamiento de la actividad objeto de la licencia otorgada.',c:'El Ayuntamiento es órgano sustantivo ambiental para la recepción de la declaración responsable ambiental.',d:'El Ayuntamiento es órgano sustantivo ambiental para la tramitación y resolución del procedimiento de autorización ambiental integrada.'}, correct:'d', why:{d:'La opción d) es incorrecta: el Ayuntamiento no es órgano sustantivo ambiental para la tramitación y resolución del procedimiento de autorización ambiental integrada; esa competencia corresponde a la administración autonómica.'}},
{n:19, q:'En lo que respecta a las competencias municipales en el control ambiental de actividades, indique la respuesta que no es correcta:', o:{a:'Corresponde a los ayuntamientos, en el ámbito de sus respectivas competencias, la vigilancia y el control del cumplimiento de las condiciones establecidas en el respectivo instrumento de intervención ambiental.',b:'La inspección de actividades corresponde al ayuntamiento respectivo en todo caso.',c:'El Ayuntamiento es órgano sustantivo ambiental para la recepción de la comunicación de actividades inocuas.',d:'Corresponde a los ayuntamientos el ejercicio de la potestad sancionadora en los términos contemplados en el título VI de la Ley 6/2014, sin perjuicio de las facultades que correspondan a otros órganos administrativos por razón de la materia.'}, correct:'b', why:{b:'La opción b) es incorrecta: la inspección de actividades no corresponde siempre al ayuntamiento; puede corresponder también a la administración autonómica en determinadas actividades.'}},
{n:20, q:'En lo que respecta a las competencias municipales en el control ambiental de actividades, indique la respuesta que no es correcta:', o:{a:'Los ayuntamientos deben emitir informe urbanístico municipal, acompañado de certificado suscrito por el secretario/a de la corporación con el visto bueno del/de la alcalde/sa del ayuntamiento, en el cual se contendrá pronunciamiento expreso sobre la compatibilidad o incompatibilidad urbanística del proyecto con el planeamiento urbanístico.',b:'En los expedientes de comunicación de actividades inocuas, declaración responsable o licencia ambiental en los que el ciudadano opte por un certificado OCA los ayuntamientos no están obligados a emitir informe urbanístico.',c:'Los ayuntamientos pueden elaborar ordenanzas donde se prevea la posibilidad de obtener la certificación de verificación documental, con carácter previo a la presentación de la solicitud de licencia ambiental.',d:'La competencia para incoar, instruir y resolver los expedientes sancionadores que se originen corresponde a los ayuntamientos, en todo caso.'}, correct:'d', why:{d:'La opción d) es incorrecta: la competencia para incoar, instruir y resolver expedientes sancionadores no siempre corresponde a los ayuntamientos; en algunos casos corresponde a la administración autonómica.'}},
{n:21, q:'En lo que respecta a las competencias municipales en el control ambiental de actividades, indique la respuesta que no es correcta:', o:{a:'El plazo de que disponen los ayuntamientos para la tramitación y resolución del procedimiento de autorización ambiental integrada es de seis meses.',b:'Los ayuntamientos pueden adherirse a los convenios suscritos entre la conselleria y los colegios profesionales u otras corporaciones de derecho público, o suscribir los suyos propios.',c:'En el caso de instalaciones sometidas a autorización ambiental integrada, corresponde al ayuntamiento en cuyo territorio vaya a ubicarse la instalación o actividad, la emisión de un informe sobre las materias de su competencia, el cual deberá emitirse en el plazo de treinta días desde la recepción de la petición.',d:'Corresponde a los ayuntamientos emitir el dictamen ambiental exigido para la obtención de la licencia ambiental.'}, correct:'a', why:{a:'La opción a) es incorrecta: el plazo de tramitación y resolución del procedimiento de autorización ambiental integrada no corresponde a los ayuntamientos sino a la administración autonómica.'}},
{n:22, q:'En lo que respecta a las competencias municipales en el control ambiental de actividades, indique la respuesta incorrecta:', o:{a:'En los municipios con población de derecho igual o superior a 50.000 habitantes, el dictamen ambiental será elaborado por la ponencia de carácter técnico del ayuntamiento.',b:'En los municipios con población de derecho inferior a 10.000 habitantes el dictamen ambiental será emitido con carácter preceptivo por la Comisión Territorial de Análisis Ambiental Integrado, previo informe del ayuntamiento en que vaya a ubicarse la instalación o actividad.',c:'El ayuntamiento deberá notificar la resolución de licencia ambiental al Ministerio de Medio Ambiente, en el plazo máximo de 30 días.',d:'El ayuntamiento deberá notificar la resolución de licencia ambiental a los interesados.'}, correct:'c', why:{c:'La opción c) es incorrecta: el ayuntamiento no está obligado a notificar la resolución de licencia ambiental al Ministerio de Medio Ambiente en el plazo de 30 días; la notificación se realiza a los interesados y, en su caso, a la Conselleria competente.'}},
{n:23, q:'En lo que respecta a las competencias municipales en el control ambiental de actividades, indique la respuesta correcta:', o:{a:'El ayuntamiento deberá notificar la resolución de licencia ambiental a la Comisión Territorial de Análisis Ambiental Integrado cuando ésta haya emitido o intervenido en la emisión del dictamen ambiental.',b:'Una vez emitida la licencia ambiental, el ayuntamiento, en el plazo de 20 días, desde la presentación de la comunicación, debe verificar la documentación presentada y girar visita de comprobación de la adecuación de la instalación a las condiciones fijadas en la licencia ambiental.',c:'Los ayuntamientos deben poner a disposición de los interesados, en la página web municipal, modelos de licencia ambiental.',d:'En aquellas actividades sometidas a declaración responsable ambiental, corresponde a los ayuntamientos emitir la resolución de autorización en el plazo de un mes.'}, correct:'a', why:{a:'La Ley 6/2014 CV establece que el ayuntamiento debe notificar la resolución de licencia ambiental a la Comisión Territorial de Análisis Ambiental Integrado cuando ésta haya emitido o intervenido en la emisión del dictamen ambiental.'}},
{n:24, q:'En lo que respecta a las competencias municipales en el control ambiental de actividades, indique la respuesta correcta:', o:{a:'Corresponde a los ayuntamientos regular mediante ordenanza municipal las actividades que tengan la consideración de potencialmente contaminantes, conforme a lo establecido en el anexo III de la Ley 6/2014 CV.',b:'Corresponde a los ayuntamientos regular mediante ordenanza municipal el régimen de comunicación de las actividades inocuas.',c:'Corresponde a los ayuntamientos en los que se ubiquen las correspondientes instalaciones sujetas a autorización ambiental integrada la competencia para adoptar las medidas cautelares.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 6/2014 CV establece que corresponde a los ayuntamientos regular mediante ordenanza municipal el régimen de comunicación de las actividades inocuas.'}},
{n:25, q:'En el ámbito del control ambiental de actividades, constituye el nivel más estricto de protección y se aplica a aquellos proyectos con importantes repercusiones sobre el medio ambiente:', o:{a:'La licencia ambiental.',b:'La autorización ambiental integrada.',c:'La declaración responsable ambiental.',d:'La comunicación de actividades inocuas.'}, correct:'b', why:{b:'La autorización ambiental integrada constituye el nivel más estricto de intervención ambiental y se aplica a los proyectos con mayores repercusiones sobre el medio ambiente.'}},
{n:26, q:'En el ámbito del control ambiental de actividades, en la autorización ambiental integrada se incluyen:', o:{a:'Las autorizaciones para vertidos en aguas continentales, incluidos los realizados en la red de saneamiento y en el dominio público marítimo terrestre.',b:'Las autorizaciones en materia de residuos.',c:'Determinaciones sobre emisiones a la atmósfera y demás autorizaciones referidas al control de la contaminación.',d:'Todo lo indicado en las respuestas anteriores.'}, correct:'d', why:{d:'La autorización ambiental integrada incluye las autorizaciones de vertidos, en materia de residuos y las determinaciones sobre emisiones a la atmósfera y demás autorizaciones referidas al control de la contaminación.'}},
{n:27, q:'La evaluación del impacto ambiental de un proyecto se lleva a cabo:', o:{a:'Durante un plazo no superior a dos meses.',b:'Mediante la denominada "Declaración de Impacto Ambiental".',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La evaluación del impacto ambiental de un proyecto se lleva a cabo mediante la denominada "Declaración de Impacto Ambiental".'}},
{n:28, q:'La denominada "Declaración de Impacto Ambiental":', o:{a:'Se constituye como un acto de trámite, o no definitivo.',b:'Tiene por finalidad dotar de información al órgano o autoridad que deba resolver sobre la autorización demandada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Declaración de Impacto Ambiental es un acto de trámite y tiene por finalidad dotar de información al órgano o autoridad que deba resolver sobre la autorización demandada.'}},
{n:29, q:'Una vez otorgada la autorización ambiental integrada, y finalizada en su caso la construcción de instalaciones y obras, el titular:', o:{a:'Antes de iniciar la actividad debe presentar una declaración responsable conforme al artículo 71 bis de la Ley de procedimiento administrativo.',b:'Dispondrá de un plazo de cinco años para iniciar la actividad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 6/2014 CV establece que una vez otorgada la autorización ambiental integrada y finalizadas las obras, el titular debe comunicar el inicio de la actividad, no presentar declaración responsable; y el plazo no es de cinco años.'}},
{n:30, q:'Con respecto a la autorización ambiental integrada, señale la afirmación incorrecta:', o:{a:'Se exige para aquellas actividades que figuran en el anexo II de la Ley 6/2014 de la Generalitat Valenciana.',b:'La administración dispone de un mes para verificar la documentación presentada y efectuar oposición o reparos.',c:'El órgano competente para la tramitación y resolución del procedimiento y para la recepción de la declaración responsable, es la Dirección General competente de la Conselleria de Medio Ambiente.',d:'En caso de cierre temporal o definitivo, y cierre de la actividad el titular debe presentar una comunicación previa y adoptar las medidas necesarias para controlar y retirar las sustancias peligrosas que pudieran incidir en la salud de las personas o en el medio ambiente.'}, correct:'a', why:{a:'La opción a) es incorrecta: la autorización ambiental integrada se exige para las actividades del anexo II de la Ley estatal (RDL 1/2016), no del anexo II de la Ley 6/2014 CV.'}},
{n:31, q:'En el ámbito del control ambiental de actividades, la licencia ambiental tiene por objeto:', o:{a:'Valorar las afecciones de estas actividades sobre el medio ambiente en su conjunto.',b:'Integrar otros aspectos de competencia municipal como los referidos a incendios, accesibilidad, seguridad y salud para las personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La licencia ambiental tiene por objeto valorar las afecciones de las actividades sobre el medio ambiente en su conjunto e integrar otros aspectos de competencia municipal.'}},
{n:32, q:'La licencia ambiental se exige:', o:{a:'Para aquellas actividades que figuran en el anexo I de la Ley 6/2014 de la Generalitat Valenciana.',b:'Para aquellas actividades que no están sometidas a una autorización ambiental integrada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La licencia ambiental se exige para las actividades del anexo I de la Ley 6/2014 CV y para las que no están sometidas a autorización ambiental integrada.'}},
{n:33, q:'La licencia ambiental tiene por objeto valorar las afecciones de actividades sobre el medio ambiente en su conjunto, incluyendo todos los condicionamientos:', o:{a:'Para la prevención y reducción de emisiones a la atmósfera, agua o suelo.',b:'Para la adecuada gestión de los recursos generados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La licencia ambiental valora las afecciones incluyendo los condicionamientos para la prevención y reducción de emisiones a la atmósfera, agua o suelo, y la adecuada gestión de los recursos generados.'}},
{n:34, q:'Con respecto a la licencia ambiental, indique la afirmación incorrecta.', o:{a:'Su titular dispondrá de un plazo de cinco años para iniciar la actividad.',b:'Para su concesión se elaborará un "dictamen ambiental" que incluirá todos los aspectos y condicionamientos que deba cumplir la actividad.',c:'Se exige a aquellas actividades que no están sometidas a una autorización ambiental integrada y figuran en el anexo II de la Ley 6/2014 de la Generalitat Valenciana.',d:'El plazo de que disponen los ayuntamientos para la tramitación y resolución del procedimiento de licencia ambiental es de seis meses.'}, correct:'a', why:{a:'La opción a) es incorrecta: el titular de la licencia ambiental no dispone de cinco años para iniciar la actividad; el plazo establecido en la ley es diferente.'}},
{n:35, q:'Respecto al "dictamen ambiental" exigido para obtener la licencia ambiental, señale la afirmación correcta:', o:{a:'Será elaborado por la Oficina Técnica de los ayuntamientos en municipios de más de 50.000 habitantes.',b:'Su elaboración corresponde a los ayuntamientos de población superior a 10.000 e inferior a 50.000 habitantes, aunque podrá interesarse de la administración autonómica cuando se carezca de medios para llevarlo a cabo.',c:'En los municipios de menos de 10.000 habitantes el dictamen será emitido por la Comisión Territorial de Análisis Ambiental Integrado, previo informe del ayuntamiento donde vaya a ubicarse la actividad.',d:'Todas las afirmaciones anteriores son correctas.'}, correct:'d', why:{d:'La Ley 6/2014 CV establece estas tres reglas para la elaboración del dictamen ambiental en función del tamaño del municipio.'}},
{n:36, q:'El plazo máximo de que dispone el ayuntamiento para resolver y notificar la licencia ambiental es de...', o:{a:'Seis meses.',b:'Un año.',c:'Tres meses.',d:'Dos meses.'}, correct:'a', why:{a:'La Ley 6/2014 CV establece que el plazo máximo para que el ayuntamiento resuelva y notifique la licencia ambiental es de seis meses.'}},
{n:37, q:'En lo que respecta a la licencia ambiental, indique la respuesta que no es correcta...', o:{a:'Una vez obtenida la licencia ambiental y finalizada, en su caso, la construcción de las instalaciones y obras, con carácter previo al inicio de la actividad deberá presentarse comunicación de puesta en funcionamiento.',b:'El ayuntamiento dispondrá del plazo de 15 desde la presentación de la comunicación para verificar la documentación presentada y girar visita de comprobación de la adecuación de la instalación a las condiciones fijadas en la licencia ambiental.',c:'Transcurrido el plazo de un mes sin que se efectúe visita de comprobación por el ayuntamiento, podrá iniciarse el ejercicio de la actividad.',d:'Se incluyen en el régimen de licencia ambiental las actividades que desarrollen en recintos donde se celebran espectáculos públicos y actividades recreativas.'}, correct:'b', why:{b:'La opción b) es incorrecta: el ayuntamiento dispondrá de un mes (no 15 días) desde la presentación de la comunicación de puesta en funcionamiento para verificar la documentación y girar visita de comprobación.'}},
{n:38, q:'Se incluyen en el régimen de declaración responsable ambiental:', o:{a:'Las actividades que por su escasa incidencia ambiental no estén sometidas ni al régimen de autorización ambiental integrada, ni al de licencia ambiental.',b:'Las actividades que por su escasa incidencia ambiental no estén sometidas ni al régimen de autorización ambiental integrada, ni al de licencia ambiental.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Las actividades sometidas al régimen de declaración responsable ambiental son aquellas que por su escasa incidencia ambiental no están sometidas a autorización ambiental integrada ni a licencia ambiental.'}},
{n:39, q:'Antes de presentar ante el ayuntamiento la declaración responsable ambiental, los interesados deben:', o:{a:'Efectuar las obras e instalaciones eléctricas, acústicas y de seguridad industrial, y demás que resulten procedentes en función de la actividad a desarrollar.',b:'Haber obtenido las autorizaciones o haber efectuado las comunicaciones que sean exigibles en la respectiva legislación sectorial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 6/2014 CV establece que antes de presentar la declaración responsable ambiental, los interesados deben haber efectuado las obras e instalaciones necesarias y obtenido las autorizaciones sectoriales exigibles.'}},
{n:40, q:'La presentación de la declaración responsable ambiental:', o:{a:'Debe ir acompañada de una Memoria técnica descriptiva de la actividad.',b:'Debe ir acompañada de una Certificación General suscrita por técnico competente, acreditativa de que las instalaciones cumplen con las condiciones técnicas y ambientales para iniciar la actividad.',c:'Permite al interesado la apertura e inicio de la actividad transcurrido un mes desde la fecha de su presentación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 6/2014 CV establece que la declaración responsable ambiental debe ir acompañada de una memoria técnica, una certificación de un técnico competente y permite iniciar la actividad transcurrido un mes.'}},
{n:41, q:'Están sometidas al régimen de "comunicación de actividades inocuas":', o:{a:'Las actividades que no tengan incidencia ambiental alguna por cumplir la totalidad de las condiciones establecidas en el anexo III de la Ley 6/2014.',b:'Las actividades que por su escasa incidencia ambiental no estén sometidas ni al régimen de autorización ambiental integrada, ni al de licencia ambiental.',c:'Las actividades reguladas en el anexo I de la Ley 6/2014.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Las actividades sometidas al régimen de comunicación de actividades inocuas son aquellas que no tienen incidencia ambiental alguna por cumplir la totalidad de las condiciones del anexo III de la Ley 6/2014 CV.'}},
{n:42, q:'Respecto a la "comunicación de actividades inocuas", señale la afirmación incorrecta:', o:{a:'Podrá efectuarse antes del inicio de la actividad, una vez acabadas las obras e instalaciones necesarias y obtenidas, en su caso, las autorizaciones que procedan conforme a su legislación sectorial.',b:'Debe ir acompañada de una memoria técnica descriptiva de la actividad.',c:'Se presentará ante el ayuntamiento del municipio en el que vaya a realizarse la actividad.',d:'Surtirá efectos desde su presentación.'}, correct:'b', why:{b:'La opción b) es incorrecta: la comunicación de actividades inocuas no requiere ir acompañada de memoria técnica descriptiva; es el instrumento más sencillo de todos los establecidos.'}},
{n:43, q:'Respecto a la función inspectora ambiental, señale la afirmación incorrecta:', o:{a:'Corresponde a la Conselleria de Medio Ambiente cuando se trata de actividades sujetas a autorización ambiental integrada y al ayuntamiento respectivo en los demás casos.',b:'El coste de las inspecciones se imputará, en todo caso, a los titulares de las entidades inspeccionadas.',c:'Debe ser desempeñada por funcionarios públicos que pueden estar asistidos por personal no funcionario de entidades públicas o privadas.',d:'El personal que desempeñe las funciones de inspección tendrá la condición de agente de la autoridad y levantará acta de las visitas de inspección que realice.'}, correct:'b', why:{b:'La opción b) es incorrecta: el coste de las inspecciones no se imputa en todo caso a los titulares de las entidades inspeccionadas.'}},
{n:44, q:'Salvo cuando se trate de instalaciones sujetas a autorización ambiental integrada, que corresponde a la administración autonómica, corresponderá a los respectivos ayuntamientos:', o:{a:'La competencia para incoar los expedientes sancionadores que se originen.',b:'La competencia para instruir los expedientes sancionadores que se originen.',c:'La competencia para resolver los expedientes sancionadores que se originen.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 6/2014 CV establece que, salvo en el caso de la autorización ambiental integrada, corresponde a los ayuntamientos incoar, instruir y resolver los expedientes sancionadores.'}},
{n:45, q:'Indique cuál de las siguientes normas no está relacionada con la protección del medio ambiente atmosférico.', o:{a:'La Ley 34/2007 de calidad del aire y protección de la atmósfera.',b:'El Real Decreto 102/2011 relativo a la mejora de la calidad del aire.',c:'El Real Decreto 172/2014 de análisis de la calidad del aire y declaración de atmósferas contaminadas.',d:'La Orden TEC/35/2019 por la que se aprueba el Índice Nacional de Calidad del Aire.'}, correct:'c', why:{c:'La opción c) es incorrecta: el "Real Decreto 172/2014 de análisis de la calidad del aire y declaración de atmósferas contaminadas" no corresponde a ninguna norma real sobre protección del medio ambiente atmosférico con esa denominación.'}},
{n:46, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, aquellas actividades que por su naturaleza, ubicación o por los procesos tecnológicos utilizados constituyan una fuente de contaminación cuyas características puedan requerir que sean sometidas a un régimen de control y seguimiento más estricto, se consideran:', o:{a:'Actividades potencialmente contaminadoras de la atmósfera.',b:'Actividades en valor límite de emisión.',c:'Conurbaciones.',d:'Actividades en umbral de alerta.'}, correct:'a', why:{a:'La Ley 34/2007 denomina "actividades potencialmente contaminadoras de la atmósfera" a las que constituyen una fuente de contaminación que puede requerir un régimen de control y seguimiento más estricto.'}},
{n:47, q:'Constituye contaminación atmosférica la presencia en la atmósfera de materias, sustancias, o formas de energía que impliquen molestia grave, riesgo o daño para:', o:{a:'La seguridad o la salud de las personas.',b:'El medio ambiente.',c:'Los bienes de cualquier naturaleza.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 define la contaminación atmosférica como la presencia en la atmósfera de materias, sustancias o formas de energía que impliquen molestia grave, riesgo o daño para la seguridad o la salud de las personas, el medio ambiente o los bienes de cualquier naturaleza.'}},
{n:48, q:'Se considera contaminación lumínica el resplandor luminoso nocturno o brillo producido por la difusión y reflexión de la luz en los gases, aerosoles y partículas en suspensión en la atmósfera que:', o:{a:'Alteran las condiciones naturales en las horas nocturnas.',b:'Dificultan las observaciones astronómicas de los cuerpos celestes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La contaminación lumínica es el resplandor nocturno que altera las condiciones naturales de las horas nocturnas y dificulta las observaciones astronómicas.'}},
{n:49, q:'Se denominan emisiones las descargas en la atmósfera de materias, sustancias o formas de energía procedentes de cualquier fuente susceptible de producir contaminación atmosférica.', o:{a:'Falso; se denominan vertidos.',b:'Cierto, ya sean descargas continuas o discontinuas.',c:'Cierto, pero sólo si se trata de descargas eléctricas.',d:'Cierto, pero sólo cuando así se determine en la normativa autonómica.'}, correct:'b', why:{b:'La Ley 34/2007 define las emisiones como las descargas a la atmósfera de materias, sustancias o formas de energía, ya sean continuas o discontinuas.'}},
{n:50, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, la emisión de contaminantes producidas por una erupción volcánica se considera:', o:{a:'Contaminación involuntaria.',b:'Contaminación incontrolada.',c:'Contaminación imprevisible.',d:'Emisión procedente de fuentes naturales.'}, correct:'d', why:{d:'La Ley 34/2007 establece que las emisiones procedentes de fuentes naturales, como una erupción volcánica, se denominan emisiones procedentes de fuentes naturales.'}},
{n:51, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, el resultado de aplicar cualquier método que permita medir, calcular, predecir o estimar las emisiones, los niveles o los efectos de la contaminación atmosférica, recibe el nombre de:', o:{a:'Valoración.',b:'Medición.',c:'Evaluación.',d:'Estimación.'}, correct:'b', why:{b:'La Ley 34/2007 denomina "medición" al resultado de aplicar cualquier método que permita medir, calcular, predecir o estimar las emisiones, los niveles o los efectos de la contaminación atmosférica.'}},
{n:52, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, la cantidad de un contaminante en el aire o su depósito en superficies con referencia a un periodo de tiempo determinado, se denomina:', o:{a:'Nivel de contaminación.',b:'Índice de contaminación.',c:'Valor de contaminación.',d:'Umbral de contaminación.'}, correct:'b', why:{b:'La Ley 34/2007 denomina "índice de contaminación" a la cantidad de un contaminante en el aire o su depósito en superficies con referencia a un periodo de tiempo determinado.'}},
{n:53, q:'De las siguientes definiciones, referidas al ámbito del medio ambiente atmosférico, señale la incorrecta:', o:{a:'Umbral de información es el nivel a partir del cual una exposición de larga duración supone un riesgo para la salud de los sectores especialmente vulnerables de la población.',b:'Umbral de alerta es el nivel a partir del cual una exposición de breve duración supone un riesgo para la salud humana, que afecta al conjunto de la población y que requiere la adopción de medidas inmediatas.',c:'La contaminación lumínica altera las condiciones naturales en las horas nocturnas.',d:'Valor límite de emisión es la cuantía de uno o más contaminantes en emisión que no debe sobrepasarse en determinadas condiciones, y/o durante un determinado periodo de tiempo.'}, correct:'a', why:{a:'La opción a) es incorrecta: el umbral de información es el nivel a partir del cual una exposición de corta duración (no larga) supone un riesgo para los sectores especialmente vulnerables.'}},
{n:54, q:'En el ámbito del medio ambiente atmosférico, corresponde a la Administración del Estado, con la participación de las Comunidades Autónomas, definir y establecer:', o:{a:'Los objetivos de calidad del aire.',b:'Los umbrales de alerta y de información.',c:'Los valores límite de emisión de contaminantes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que corresponde a la Administración del Estado, con la participación de las CCAA, definir y establecer los objetivos de calidad del aire, los umbrales de alerta e información y los valores límite de emisión.'}},
{n:55, q:'En el ámbito del medio ambiente atmosférico, las CCAA evaluarán la calidad del aire pudiendo establecer objetivos de calidad y valores límite:', o:{a:'Más estrictos que los establecidos por el Estado.',b:'Menos estrictos que los establecidos por el Estado.',c:'Más estrictos que los fijados en la normativa europea.',d:'Menos estrictos que los fijados en la normativa europea.'}, correct:'a', why:{a:'La Ley 34/2007 establece que las CCAA pueden evaluar la calidad del aire y establecer objetivos y valores límite más estrictos que los del Estado, pero nunca menos exigentes.'}},
{n:56, q:'Los titulares de instalaciones donde se desarrollen actividades potencialmente contaminadoras de la atmósfera deben:', o:{a:'Respetar los valores límite de emisión que se establezcan.',b:'Realizar controles de sus emisiones, cumplir los requisitos técnicos que les sean de aplicación.',c:'Facilitar la información y los actos de inspección que les demanden las respectivas administraciones.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que los titulares de estas instalaciones deben respetar los valores límite, realizar controles de emisiones y facilitar la información a los inspectores.'}},
{n:57, q:'Respecto al medio ambiente atmosférico, señale la afirmación incorrecta.', o:{a:'Los agentes de vigilancia del tráfico podrán detener cualquier vehículo con motor de gasolina, en todo lugar y ocasión, al objeto de proceder a la medición de las emisiones de escape.',b:'Las denuncias formuladas por superar los límites fijados de emisión de humos, estarán condicionadas a la presentación del vehículo en la inspección oficial, para comprobación en el plazo de diez días.',c:'Las aglomeraciones deberán disponer, por sí mismas o en colaboración con las CCAA, de estaciones y redes de evaluación de la calidad del aire.',d:'Los municipios con población superior a 100.000 habitantes, y los que formen parte de una aglomeración, dispondrán de datos para informar a la población sobre los niveles de contaminación y de calidad del aire.'}, correct:'b', why:{b:'La opción b) es incorrecta: las denuncias formuladas por superar los límites de emisión de humos no están condicionadas a la presentación del vehículo en la inspección oficial en el plazo de diez días.'}},
{n:58, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, los funcionarios que se encarguen de las tareas de inspección necesarias para garantizar el cumplimiento de esta Ley:', o:{a:'Podrán acceder a cualquier lugar de la instalación o dependencia, de titularidad pública o privada, en el ejercicio de sus funciones, sin cumplir las restricciones sobre inviolabilidad de domicilio.',b:'Podrán acceder a cualquier lugar de la instalación o dependencia, de titularidad pública o privada, en el ejercicio de sus funciones, en todo caso, a la inviolabilidad del domicilio.',c:'Podrán acceder a cualquier lugar de la instalación o dependencia, de titularidad pública o privada, en el ejercicio de sus funciones, con respeto, en todo caso, a la inviolabilidad del domicilio y a lo establecido en la legislación penal de la Unión Europea.',d:'Podrán acceder a cualquier lugar de la instalación o dependencia, de titularidad pública o privada, en el ejercicio de sus funciones, con respeto, en todo caso, a la inviolabilidad del domicilio, no pudiendo inspeccionar establecimientos públicos sin autorización de la autoridad judicial.'}, correct:'b', why:{b:'La Ley 34/2007 establece que los funcionarios de inspección podrán acceder a cualquier lugar de la instalación o dependencia, con respeto en todo caso a la inviolabilidad del domicilio.'}},
{n:59, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, el sistema español de información, vigilancia y prevención de la contaminación atmosférica:', o:{a:'Tendrá por finalidad permitir el intercambio recíproco de información, entre las distintas administraciones públicas para el cumplimiento de las obligaciones derivadas de esta ley y de la normativa comunitaria internacional.',b:'Será coordinado por el Ministerio de Industria y Energía.',c:'Estará al cargo de un funcionario designado por el Congreso de los Diputados.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Ley 34/2007 establece que el sistema español de información, vigilancia y prevención de la contaminación atmosférica tendrá por finalidad permitir el intercambio recíproco de información entre las distintas administraciones públicas.'}},
{n:60, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, el sistema español de información, vigilancia y prevención de la contaminación atmosférica:', o:{a:'Será coordinado por el Ministerio de Medio Ambiente.',b:'Se abastecerá de la información generada por las Administraciones Públicas y por los titulares, a través de aquellas, así como de cualquier otro dato relevante a efectos de esta Ley.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 34/2007 establece que el sistema será coordinado por el Ministerio de Medio Ambiente y se abastecerá de la información generada por las AAPP y los titulares.'}},
{n:61, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, el seguimiento del impacto de la contaminación del aire en la salud será realizado por:', o:{a:'Las respectivas Comunidades Autónomas.',b:'El Ministerio de Sanidad y Consumo.',c:'El Ministerio de Medio Ambiente.',d:'Las respectivas Comunidades Autónomas con la colaboración de las Entidades Locales.'}, correct:'a', why:{a:'La Ley 34/2007 establece que el seguimiento del impacto de la contaminación del aire en la salud será realizado por las respectivas Comunidades Autónomas.'}},
{n:62, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, los requisitos mínimos a los que deben ajustarse las estaciones, redes y otros sistemas de evaluación de la calidad del aire serán definidos:', o:{a:'Mediante Ley de las Cortes Generales.',b:'Mediante Real Decreto por el Gobierno del Estado, con la participación de las Comunidades Autónomas.',c:'Mediante Real Decreto por el Gobierno del Estado, con la participación de las Comunidades Autónomas y de las Entidades Locales afectadas.',d:'Mediante Real Decreto por el Gobierno del Estado, oído el Ministerio de Medio Ambiente y el Ministerio de Industria y Energía.'}, correct:'d', why:{d:'La Ley 34/2007 establece que los requisitos mínimos de las estaciones, redes y sistemas de evaluación serán definidos mediante Real Decreto por el Gobierno del Estado, oído el Ministerio de Medio Ambiente y el Ministerio de Industria y Energía.'}},
{n:63, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, los requisitos mínimos a los que deben ajustarse las estaciones, redes y otros sistemas de evaluación de la calidad del aire estarán referidos a los criterios de:', o:{a:'Ubicación y número mínimo de estaciones.',b:'Métodos para el muestreo y análisis de contaminantes.',c:'Control y garantía de la calidad de las evaluaciones.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que los criterios mínimos se refieren a la ubicación y número mínimo de estaciones, los métodos de muestreo y análisis, y el control de calidad de las evaluaciones.'}},
{n:64, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, para la instalación de estaciones de medida de la calidad del aire de titularidad pública, se podrán imponer:', o:{a:'Servidumbres forzosas, previa indemnización.',b:'Expropiaciones forzosas, previa indemnización.',c:'Ejecuciones forzosas, previa indemnización.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 34/2007 establece que para la instalación de estaciones de medida de la calidad del aire de titularidad pública se podrán imponer servidumbres forzosas, previa indemnización.'}},
{n:65, q:'La potestad sancionadora por infracciones previstas en la Ley 34/2007 de calidad del aire y protección de la atmósfera corresponde a:', o:{a:'La Administración del Estado y, en su caso, a las Comunidades Autónomas que tengan un concierto con el Ministerio de Calidad Ambiental.',b:'Las Comunidades Autónomas y, en su caso, a las entidades locales.',c:'La Administración del Estado, Comunidades Autónomas o Entidades Locales, según el tipo de infracción sea muy grave, grave o leve.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'La Ley 34/2007 establece que la potestad sancionadora corresponde a las Comunidades Autónomas y, en su caso, a las entidades locales.'}},
{n:66, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, sin perjuicio de las infracciones que, en su caso, establezca la legislación sectorial y de las que puedan establecer las comunidades autónomas, clasifica las infracciones administrativas en:', o:{a:'Muy graves, graves y leves.',b:'Muy graves, menos graves y leves.',c:'Graves y muy graves.',d:'Esta ley no realiza ninguna clasificación de las infracciones, sino que se remite a lo que puedan disponer las respectivas comunidades autónomas.'}, correct:'a', why:{a:'La Ley 34/2007 clasifica las infracciones administrativas en muy graves, graves y leves.'}},
{n:67, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, constituye infracción de carácter muy grave:', o:{a:'Impedir, retrasar u obstruir la actividad de inspección o control en todo caso.',b:'Incumplir el régimen de autorización y notificación previsto en esta ley para las actividades potencialmente contaminadoras de la atmósfera, siempre que ello haya generado o haya impedido evitar una contaminación atmosférica que haya puesto en peligro grave la seguridad o salud de las personas o haya producido daño o deterioro grave para el medio ambiente.',c:'El incumplimiento de las medidas contempladas en los planes de acción a largo plazo, a los que se refiere esta ley.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que son infracciones muy graves: impedir u obstruir la inspección, incumplir el régimen de autorización en las condiciones descritas, e incumplir los planes de acción a largo plazo.'}},
{n:68, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, constituye infracción de carácter muy grave:', o:{a:'Incumplir los valores límite de emisión, siempre que ello haya generado o haya impedido evitar una contaminación atmosférica que haya puesto en peligro grave la seguridad o la salud de las personas, o haya producido un daño o deterioro grave al medio ambiente.',b:'Ocultar o alterar maliciosamente la información exigida en los procedimientos regulados en esta ley, cuando ello no esté tipificado como infracción grave.',c:'No realizar controles de emisiones y de la calidad del aire en la forma y periodicidad establecidas legalmente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 34/2007 establece que es infracción muy grave incumplir los valores límite de emisión cuando ello haya generado peligro grave para la seguridad o la salud, o daño grave al medio ambiente.'}},
{n:69, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, no cumplir las obligaciones relativas a las estaciones de medida de los niveles de contaminación y al registro de los controles de emisiones y niveles de contaminación previstos en esta ley, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Leve.',d:'Menos grave.'}, correct:'b', why:{b:'La Ley 34/2007 establece que el incumplimiento de las obligaciones relativas a las estaciones de medida y al registro de controles de emisiones y niveles constituye infracción grave.'}},
{n:70, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, en caso de infracciones muy graves puede imponerse la sanción de:', o:{a:'Multa de 200.001 a 2.000.000 de euros.',b:'Prohibición o clausura definitiva, total o parcial de las actividades o instalaciones.',c:'Prohibición o clausura temporal, total o parcial de las actividades o instalaciones por un periodo no inferior a dos años, ni superior a cinco.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que las infracciones muy graves pueden sancionarse con multa de 200.001 a 2.000.000 euros, prohibición o clausura definitiva o temporal (entre 2 y 5 años).'}},
{n:71, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, en caso de infracciones muy graves puede imponerse la sanción de:', o:{a:'Precintado de equipos, máquinas y productos, por un periodo no inferior a dos años.',b:'Inhabilitación para el ejercicio de la actividad por un periodo no inferior a un año ni superior a cinco.',c:'Extinción o suspensión de las autorizaciones en las que se hayan establecido condiciones relativas a la contaminación atmosférica, por un tiempo no inferior a dos años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que las infracciones muy graves también pueden sancionarse con precintado de equipos, inhabilitación y extinción o suspensión de autorizaciones.'}},
{n:72, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, en caso de infracciones graves puede imponerse la sanción de:', o:{a:'Multa de 20.001 a 200.000 euros.',b:'Prohibición o clausura temporal, total o parcial, de las actividades o instalaciones por un periodo máximo de dos años.',c:'Inhabilitación para el ejercicio de la actividad por un periodo máximo de un año.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que las infracciones graves pueden sancionarse con multa de 20.001 a 200.000 euros, prohibición o clausura temporal (máximo 2 años) e inhabilitación (máximo 1 año).'}},
{n:73, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, en caso de infracciones graves puede imponerse la sanción de:', o:{a:'Precintado temporal de equipos, máquinas y productos por un periodo máximo de cinco años.',b:'La suspensión de autorizaciones en las que se hayan establecido condiciones relativas a la contaminación atmosférica por un período máximo de dos años.',c:'Multa de hasta 20.000 euros.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 34/2007 establece que las infracciones graves también pueden sancionarse con la suspensión de autorizaciones relacionadas con la contaminación atmosférica por un período máximo de dos años.'}},
{n:74, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, en caso de infracciones leves puede imponerse la sanción de:', o:{a:'Multa de hasta 20.000 euros.',b:'Prohibición o clausura temporal, total o parcial, de las actividades o instalaciones por un periodo máximo de dos años.',c:'Extinción o suspensión de las autorizaciones en las que se hayan establecido condiciones relativas a la contaminación atmosférica, por un tiempo no inferior a dos años.',d:'Inhabilitación para el ejercicio de la actividad por un periodo máximo de un año.'}, correct:'a', why:{a:'La Ley 34/2007 establece que las infracciones leves pueden sancionarse con multa de hasta 20.000 euros.'}},
{n:75, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, constituye criterio para la graduación de las sanciones:', o:{a:'Existencia de intencionalidad.',b:'Existencia de reiteración.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 34/2007 establece que la intencionalidad y la reiteración son criterios para graduar las sanciones.'}},
{n:76, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, constituye criterio para la graduación de las sanciones:', o:{a:'El beneficio obtenido por la comisión de la infracción.',b:'La reincidencia por comisión de más de una infracción tipificada en esta ley, aunque no hayan sido objeto de resolución firme.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 34/2007 establece que el beneficio obtenido por la comisión de la infracción es un criterio de graduación de las sanciones.'}},
{n:77, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, constituye criterio para la graduación de las sanciones:', o:{a:'La medida en la que el valor límite de emisión haya sido superado.',b:'Las molestias, riesgos o daños causados respecto de las personas, el medio ambiente y demás bienes de cualquier naturaleza.',c:'El beneficio obtenido por la comisión de la infracción.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que son criterios de graduación de las sanciones: la medida en que se superó el valor límite de emisión, las molestias o daños causados y el beneficio obtenido.'}},
{n:78, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, constituye criterio para la graduación de las sanciones:', o:{a:'La grave dificultad o imposibilidad de reparar los daños ocasionados a la atmósfera.',b:'La clandestinidad de la empresa o entidad causante del daño.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 34/2007 establece que la grave dificultad o imposibilidad de reparar los daños ocasionados a la atmósfera es un criterio de graduación de las sanciones.'}},
{n:79, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, constituye criterio para la graduación de las sanciones:', o:{a:'La premeditación en la causación del daño.',b:'Las diferencias entre los datos facilitados y los reales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 34/2007 establece que la premeditación en la causación del daño y las diferencias entre los datos facilitados y los reales son criterios de graduación de las sanciones.'}},
{n:80, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, el órgano competente podrá acordar medidas provisionales:', o:{a:'En los supuestos de amenaza inminente de daño o para evitar nuevos daños.',b:'Aun antes de la iniciación del procedimiento sancionador.',c:'Con los límites y condiciones previstos en la legislación de Régimen Jurídico de las Administraciones Públicas y Procedimiento Administrativo Común.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que el órgano competente podrá acordar medidas provisionales en supuestos de amenaza inminente de daño, aun antes de la iniciación del procedimiento sancionador, con los límites de la normativa de régimen jurídico y procedimiento administrativo.'}},
{n:81, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, el órgano competente podrá acordar medidas provisionales:', o:{a:'Mediante acuerdo motivado.',b:'Sin necesidad de audiencia previa del interesado.',c:'Incluso en aquellas materias que correspondan a la competencia de otro estado miembro de la Unión Europea.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 34/2007 establece que las medidas provisionales se adoptarán mediante acuerdo motivado.'}},
{n:82, q:'Es una medida provisional que pueden acordarse de acuerdo con lo previsto en la Ley 34/2007 de calidad del aire y protección de la atmósfera:', o:{a:'El embargo de la actividad causante de las emisiones.',b:'La adopción de medidas de corrección, seguridad o control que impidan la continuidad en la producción del riesgo o del daño.',c:'La expropiación de las instalaciones y la confiscación de los medios técnicos utilizados en la actividad contaminante.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 34/2007 establece que es una medida provisional la adopción de medidas de corrección, seguridad o control que impidan la continuidad en la producción del riesgo o del daño.'}},
{n:83, q:'Es una medida provisional que pueden acordarse de acuerdo con lo previsto en la Ley 34/2007 de calidad del aire y protección de la atmósfera:', o:{a:'La clausura temporal, total o parcial, de las instalaciones.',b:'La parada temporal de las instalaciones.',c:'La suspensión temporal de la autorización para el ejercicio de la actividad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 34/2007 establece que son medidas provisionales la clausura temporal, la parada temporal y la suspensión temporal de la autorización para el ejercicio de la actividad.'}},
{n:84, q:'Según la Ley 34/2007 de calidad del aire y protección de la atmósfera, en el supuesto de que se adopte alguna medida provisional antes de la iniciación del procedimiento sancionador, el órgano competente debe confirmarla, ratificarla o levantarla, en un plazo de:', o:{a:'15 días a contar desde que se dicte el acuerdo de incoación.',b:'10 días desde el momento de su adopción.',c:'10 días contados desde el día siguiente a aquel en que el interesado interponga el correspondiente recurso.',d:'15 días desde el momento de su adopción.'}, correct:'d', why:{d:'La Ley 34/2007 establece que las medidas provisionales adoptadas antes de la iniciación del procedimiento sancionador deben ser confirmadas, ratificadas o levantadas en un plazo de 15 días desde el momento de su adopción.'}},
{n:85, q:'Constituye normativa aplicable en materia de medio ambiente acuático...', o:{a:'El Real Decreto Legislativo 1/2001 por el que se aprueba el Texto Refundido de la Ley de Aguas.',b:'La Ley 41/2010 de Protección del Medio Marino.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'En materia de medio ambiente acuático son aplicables el Real Decreto Legislativo 1/2001 (Ley de Aguas) y la Ley 41/2010 de Protección del Medio Marino.'}},
{n:86, q:'En España la planificación hidrológica corresponde:', o:{a:'Al Estado.',b:'A las Comunidades Autónomas.',c:'A las Diputaciones Provinciales.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Según el Texto Refundido de la Ley de Aguas, la planificación hidrológica en España corresponde al Estado.'}},
{n:87, q:'Constituyen un recurso unitario, subordinado al interés general, que forma parte del dominio público estatal como dominio público hidráulico:', o:{a:'Las aguas continentales superficiales integradas en el ciclo hidrológico.',b:'Las aguas subterráneas renovables integradas en el ciclo hidrológico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Texto Refundido de la Ley de Aguas establece que las aguas continentales superficiales y las aguas subterráneas renovables, integradas en el ciclo hidrológico, constituyen dominio público hidráulico.'}},
{n:88, q:'De conformidad con el Texto Refundido de la Ley de Aguas...', o:{a:'Las aguas subterráneas renovables se regulan por su legislación específica.',b:'Las aguas termales se regulan por su legislación específica.',c:'Las aguas continentales superficiales se regulan por su legislación específica.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Texto Refundido de la Ley de Aguas establece que las aguas termales se regulan por su legislación específica.'}},
{n:89, q:'El órgano superior de consulta y participación en temas hidrológicos es:', o:{a:'La Confederación Hidrológica Nacional.',b:'El Consejo Nacional del Agua.',c:'La Comisión Nacional del Agua.',d:'El Consejo Hidrológico Nacional.'}, correct:'b', why:{b:'El Texto Refundido de la Ley de Aguas establece que el Consejo Nacional del Agua es el órgano superior de consulta y participación en temas hidrológicos.'}},
{n:90, q:'La Presidencia del Consejo Nacional del Agua corresponde:', o:{a:'Al Secretario de Estado de Medio Ambiente.',b:'Al Ministro de Medio Ambiente.',c:'Al Ministro de Agricultura.',d:'Al responsable del Organismo de Cuenca.'}, correct:'b', why:{b:'El Texto Refundido de la Ley de Aguas establece que la Presidencia del Consejo Nacional del Agua corresponde al Ministro de Medio Ambiente.'}},
{n:91, q:'El Consejo Nacional del Agua es el órgano superior de consulta y participación en temas hidrológicos, formando parte del mismo:', o:{a:'Representantes de la Administración General del Estado y de las Comunidades Autónomas.',b:'Representantes de Entidades Locales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Texto Refundido de la Ley de Aguas establece que el Consejo Nacional del Agua está formado por representantes de la AGE, las CCAA y las Entidades Locales, entre otros.'}},
{n:92, q:'En las cuencas hidrográficas que excedan del ámbito territorial de una Comunidad Autónoma se constituirán organismos de cuenca con la denominación de:', o:{a:'Confederaciones Hidrográficas.',b:'Confederaciones de Aguas.',c:'Confederaciones Nacionales de Aguas.',d:'Comisiones Hídricas.'}, correct:'a', why:{a:'El Texto Refundido de la Ley de Aguas establece que en las cuencas hidrográficas que excedan del ámbito de una CCAA se constituirán organismos de cuenca denominados Confederaciones Hidrográficas.'}},
{n:93, q:'Las aguas superficiales podrán ser desviadas de sus cauces o lechos:', o:{a:'Para abrevar el ganado.',b:'Para beber, bañarse y otros usos domésticos.',c:'Para satisfacer necesidades de la población ante situaciones de sequía pertinaz.',d:'No pueden ser desviadas en ningún caso.'}, correct:'d', why:{d:'El Texto Refundido de la Ley de Aguas establece que las aguas superficiales no pueden ser desviadas de sus cauces o lechos.'}},
{n:94, q:'De conformidad con lo que dispongan las leyes y reglamentos, todos pueden usar las aguas superficiales:', o:{a:'Para beber.',b:'Para bañarse y otros usos domésticos.',c:'Para abrevar el ganado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Texto Refundido de la Ley de Aguas permite que todos puedan usar las aguas superficiales para beber, bañarse y otros usos domésticos y para abrevar el ganado, conforme a lo que dispongan las leyes y reglamentos.'}},
{n:95, q:'De conformidad con lo que dispongan las leyes y reglamentos, todos pueden usar las aguas superficiales para beber, bañarse y otros usos domésticos, así como para abrevar el ganado:', o:{a:'En casos de extraordinaria necesidad.',b:'Sin necesidad de autorización administrativa.',c:'Siempre y cuando hayan sido desviadas previamente de sus cauces naturales.',d:'De acuerdo con lo dispuesto en la normativa de la Unión Europea.'}, correct:'b', why:{b:'El Texto Refundido de la Ley de Aguas permite el uso de aguas superficiales para usos domésticos y abrevar el ganado sin necesidad de autorización administrativa.'}},
{n:96, q:'En el ámbito del medio ambiente acuático, son usos comunes especiales sujetos a declaración responsable:', o:{a:'La navegación y la flotación.',b:'Cualquier uso que no excluya la utilización del recurso por terceros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El Texto Refundido de la Ley de Aguas establece que la navegación y la flotación son usos comunes especiales sujetos a declaración responsable.'}},
{n:97, q:'En el ámbito del medio ambiente acuático, son usos comunes especiales sujetos a declaración responsable:', o:{a:'El establecimiento de barcas de paso y sus embarcaderos.',b:'Cualquier uso que no excluya la utilización del recurso por terceros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Texto Refundido de la Ley de Aguas establece que son usos comunes especiales sujetos a declaración responsable la navegación y la flotación, el establecimiento de barcas de paso y sus embarcaderos, y cualquier uso que no excluya la utilización del recurso por terceros.'}},
{n:98, q:'Con respecto al uso privativo de aguas del dominio público hidráulico, indique la respuesta incorrecta.', o:{a:'Se adquiere por disposición legal o por concesión administrativa.',b:'Puede adquirirse por prescripción.',c:'Se extingue por expropiación forzosa.',d:'Los derechos adquiridos por disposición legal se perderán según lo establecido en la norma que los regule o, en su defecto, por disposición normativa del mismo rango.'}, correct:'b', why:{b:'La opción b) es incorrecta: el uso privativo de aguas del dominio público hidráulico no puede adquirirse por prescripción.'}},
{n:99, q:'Las autorizaciones para la investigación de aguas subterráneas son otorgadas por el organismo de cuenca y no podrán exceder de:', o:{a:'Dos años.',b:'Tres años.',c:'Cinco años.',d:'Seis años.'}, correct:'b', why:{b:'El Texto Refundido de la Ley de Aguas establece que las autorizaciones para la investigación de aguas subterráneas son otorgadas por el organismo de cuenca y no podrán exceder de tres años.'}},
{n:100, q:'En el ámbito del medio ambiente acuático, se consideran vertidos los que se realicen directa o indirectamente en las aguas continentales, así como en el resto del dominio público hidráulico.', o:{a:'Cierto, cuando se trata de aguas sucias.',b:'Falso.',c:'Cierto, cualquiera que sea el procedimiento o técnica utilizada.',d:'Cierto, cuando superan determinadas cantidades.'}, correct:'c', why:{c:'El Texto Refundido de la Ley de Aguas establece que se consideran vertidos los que se realicen directa o indirectamente en las aguas continentales, cualquiera que sea el procedimiento o técnica utilizada.'}},
{n:101, q:'Queda prohibido el vertido directo o indirecto de aguas residuales susceptibles de contaminar las aguas continentales o cualquier otro elemento del dominio público hidráulico:', o:{a:'En todos los casos.',b:'Salvo que se cuente con autorización administrativa.',c:'Salvo casos excepcionales e imprevistos, y demás supuestos de fuerza mayor.',d:'Salvo casos justificados, en los que concurra un interés jurídico superior.'}, correct:'b', why:{b:'El Texto Refundido de la Ley de Aguas establece que queda prohibido el vertido directo o indirecto de aguas residuales susceptibles de contaminar el dominio público hidráulico, salvo que se cuente con autorización administrativa.'}},
{n:102, q:'Respecto del medio ambiente acuático, señale la afirmación incorrecta.', o:{a:'Las sanciones por infracciones leves y menos graves corresponden al ayuntamiento respectivo.',b:'La administración hidráulica competente concederá las autorizaciones de vertido y ejercerá la policía de las aguas y demás elementos del dominio público hidráulico.',c:'Las solicitudes de vertido que se realicen a las entidades locales deberán contener un plan de saneamiento y control de vertidos a los colectores municipales.',d:'En el caso de vertidos en la red de alcantarillado o de colectores gestionados por las administraciones autonómicas o locales, la autorización corresponderá a éstas.'}, correct:'a', why:{a:'La opción a) es incorrecta: las sanciones por infracciones leves y menos graves en materia de medio ambiente acuático corresponden al organismo de cuenca, no al ayuntamiento.'}},
{n:103, q:'En el ámbito del medio ambiente acuático:', o:{a:'Las sanciones por infracciones leves y menos graves corresponden al organismo de cuenca.',b:'Las sanciones por infracciones de carácter grave serán sancionadas por el Ministro de Medio Ambiente.',c:'Las sanciones por infracciones de carácter muy graves serán sancionadas por el Consejo de Ministros.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Texto Refundido de la Ley de Aguas establece que las infracciones leves y menos graves son sancionadas por el organismo de cuenca, las graves por el Ministro de Medio Ambiente, y las muy graves por el Consejo de Ministros.'}},
{n:104, q:'La limpieza y conservación de los tramos urbanos de los ríos es competencia de...', o:{a:'Las CCAA, salvo que la normativa autonómica atribuya esta competencia a los municipios.',b:'Los municipios, salvo que la normativa autonómica atribuya esta competencia a la propia administración autonómica.',c:'Los municipios, salvo que en la normativa autonómica se establezca una competencia compartida con el Estado.',d:'Las CCAA, salvo que la normativa estatal establezca una competencia compartida con el Estado.'}, correct:'c', why:{c:'El Texto Refundido de la Ley de Aguas establece que la limpieza y conservación de los tramos urbanos de los ríos es competencia de los municipios, salvo que la normativa autonómica establezca una competencia compartida con el Estado.'}},
{n:105, q:'La norma que tiene por objeto prevenir, vigilar y corregir la contaminación acústica en el ámbito de la Comunitat Valenciana, para proteger la salud de sus ciudadanos y mejorar la calidad de su medio ambiente, es:', o:{a:'La Ley 7/2002, de 3 de diciembre.',b:'La Ley 2/2007, de 3 de diciembre.',c:'La Ley 17/2002, de 23 de noviembre.',d:'La Ley 12/2017, de 3 de noviembre.'}, correct:'a', why:{a:'La Ley 7/2002, de 3 de diciembre, de la Generalitat Valenciana, tiene por objeto prevenir, vigilar y corregir la contaminación acústica para proteger la salud de sus ciudadanos y mejorar la calidad del medio ambiente.'}},
{n:106, q:'De las siguientes, indique la norma estatal que no está relacionada con la contaminación acústica:', o:{a:'Ley 37/2003.',b:'RD 1513/2005.',c:'RD 1367/2007.',d:'RDL 3/2015.'}, correct:'d', why:{d:'El RDL 3/2015 no está relacionado con la contaminación acústica; las otras tres normas sí lo están (Ley del Ruido, RD sobre evaluación y gestión del ruido ambiental, y RD sobre zonificación acústica).'}},
{n:107, q:'De las siguientes, indique la norma autonómica valenciana, que no está relacionada con la contaminación acústica:', o:{a:'Decreto 104/2006.',b:'Decreto 266/2004.',c:'Decreto 179/2003.',d:'Decreto 19/2004.'}, correct:'a', why:{a:'El Decreto 104/2006 de la Comunitat Valenciana no está relacionado con la contaminación acústica; los otros decretos sí regulan aspectos de la contaminación acústica en la CV.'}},
{n:108, q:'Respecto de la contaminación acústica, señale la afirmación incorrecta.', o:{a:'Para medir el nivel de las vibraciones se utilizará como magnitud la aceleración y se expresará en metros por minuto.',b:'Ruido es cualquier sonido que moleste o incomode a los seres humanos, que produce o tiene el efecto de producir un resultado psicológico o fisiológico adverso sobre los mismos.',c:'Son vibraciones las perturbaciones provocadas por la oscilación de los cuerpos sobre su posición de equilibrio.',d:'Se entiende por contaminación acústica o ruido ambiental los sonidos y las vibraciones, no deseados o nocivos, generados por la actividad humana.'}, correct:'a', why:{a:'La opción a) es incorrecta: para medir el nivel de las vibraciones se utiliza como magnitud la aceleración y se expresa en metros por segundo al cuadrado (m/s²), no en metros por minuto.'}},
{n:109, q:'Los planes acústicos, además de la identificación de los problemas, tienen por objeto:', o:{a:'El establecimiento de las medidas preventivas para mantener los niveles sonoros por debajo de los límites previstos.',b:'El establecimiento de las medidas correctoras para mantener los niveles sonoros por debajo de los límites previstos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Los planes acústicos tienen por objeto el establecimiento de medidas tanto preventivas como correctoras para mantener los niveles sonoros por debajo de los límites previstos.'}},
{n:110, q:'Los planes acústicos municipales son obligatorios para municipios:', o:{a:'Con población superior a 20.000 habitantes.',b:'Con población superior a 15.000 habitantes.',c:'Con población superior a 10.000 habitantes.',d:'Con población superior a 5.000 habitantes.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que los planes acústicos municipales son obligatorios para los municipios con población superior a 20.000 habitantes.'}},
{n:111, q:'Con respecto a los planes acústicos municipales, señale la afirmación incorrecta:', o:{a:'Los planes acústicos municipales identifican las áreas acústicas existentes en el municipio en función del uso de las mismas y de sus condiciones acústicas.',b:'Son facultativos para municipios con población inferior a 30.000 habitantes.',c:'Constarán de un mapa acústico y un programa de actuación.',d:'Deben basarse en un proyecto realizado por técnico competente.'}, correct:'b', why:{b:'La opción b) es incorrecta: los planes acústicos municipales son obligatorios para municipios con más de 20.000 habitantes, no facultativos para los de menos de 30.000.'}},
{n:112, q:'De acuerdo con lo previsto en la Ley 7/2002 de la Generalitat de protección contra la contaminación acústica, los instrumentos de planificación y gestión acústica son:', o:{a:'Plan acústico de acción autonómica, Planes acústicos municipales, Planes acústicos de empresa y Declaración de Zonas Acústicamente Saturadas.',b:'Plan acústico de acción autonómica, Planes acústicos municipales, Ordenanzas Municipales, y Declaración de Zonas Acústicamente Saturadas.',c:'Plan acústico de acción autonómica, Ordenanzas Municipales, Planes acústicos de empresa y Declaración de Zonas Acústicamente Saturadas.',d:'Plan acústico de acción autonómica, Ordenanzas Municipales, Planes acústicos de empresa y Zonas de Servidumbre Acústica.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que los instrumentos de planificación y gestión acústica son: el Plan acústico de acción autonómica, los Planes acústicos municipales, los Planes acústicos de empresa y la Declaración de Zonas Acústicamente Saturadas.'}},
{n:113, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, el Plan acústico de acción autonómica...', o:{a:'Será aprobado por acuerdo del Consell de la Generalitat.',b:'Será elaborado por la Conselleria competente en materia de Medio Ambiente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que el Plan acústico de acción autonómica será elaborado por la Conselleria competente en materia de Medio Ambiente y aprobado por acuerdo del Consell.'}},
{n:114, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, el Plan acústico de acción autonómica debe contener:', o:{a:'Programas de concienciación social de los ciudadanos.',b:'Programas de formación de empresarios y trabajadores en las acciones contra el ruido.',c:'Medidas para la prevención y reducción de la contaminación acústica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que el Plan acústico de acción autonómica debe contener programas de concienciación social, de formación de empresarios y trabajadores, y medidas para la prevención y reducción de la contaminación acústica.'}},
{n:115, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, el Plan acústico de acción autonómica debe contener:', o:{a:'Medidas correctoras con el fin de garantizar los niveles de inmisión previstos en esta ley.',b:'Medidas de financiación para llevar a cabo las actuaciones previstas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que el Plan acústico de acción autonómica debe contener medidas correctoras para garantizar los niveles de inmisión y medidas de financiación para las actuaciones previstas.'}},
{n:116, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, el Plan acústico de acción autonómica debe contener:', o:{a:'Modelos orientativos de Ordenanzas Municipales.',b:'Medidas de prevención y reducción de la contaminación acústica del tráfico rodado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que el Plan acústico de acción autonómica debe contener modelos orientativos de Ordenanzas Municipales y medidas de prevención y reducción de la contaminación del tráfico rodado.'}},
{n:117, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la aprobación de planes acústicos municipales es obligatoria para municipios:', o:{a:'De más de 5000 habitantes.',b:'De más de 10.000 habitantes.',c:'De más de 20.000 habitantes.',d:'De más de 50.000 habitantes.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que la aprobación de planes acústicos municipales es obligatoria para municipios de más de 20.000 habitantes.'}},
{n:118, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, los Planes Acústicos Municipales deben contener:', o:{a:'Un mapa acústico.',b:'Un programa de actuación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que los Planes Acústicos Municipales deben contener un mapa acústico y un programa de actuación; la opción d) es la correcta al indicar que ambas son necesarias.'}},
{n:119, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, el plan acústico municipal debe incluir necesariamente:', o:{a:'La ordenación de las actividades generadoras de ruido implantadas o a implantar en el ámbito de aplicación del Plan.',b:'La regulación del tráfico rodado.',c:'Uno o varios programas de minimización de la producción y transmisión de ruidos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que el plan acústico municipal debe incluir necesariamente la ordenación de actividades generadoras de ruido, la regulación del tráfico rodado y programas de minimización de ruidos.'}},
{n:120, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, el plan acústico municipal debe incluir necesariamente:', o:{a:'El establecimiento de sistemas de control de ruido.',b:'La definición de los tipos y modelos de aparatos aptos para llevar a cabo las mediciones de ruidos y vibraciones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que el plan acústico municipal debe incluir necesariamente el establecimiento de sistemas de control de ruido.'}},
{n:121, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, los ayuntamientos elaborarán los planes acústicos municipales basándose en:', o:{a:'Las instrucciones concretas que reciban desde el área de medio ambiente de la Diputación Provincial.',b:'Un proyecto suscrito por técnico competente.',c:'Las ordenanzas municipales sobre contaminación acústica que tengan aprobadas en sus respectivos ámbitos.',d:'El Plan General de Contaminación Acústica aprobado por el Consejo de Ministros.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que los ayuntamientos elaborarán los planes acústicos municipales basándose en un proyecto suscrito por técnico competente.'}},
{n:122, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, el proyecto de plan acústico municipal:', o:{a:'Se someterá a información pública por el plazo de 20 días.',b:'Se publicará en el Diario Oficial de la Comunitat Valenciana y en Boletín Oficial del Estado, así en como en aquellos diarios de mayor difusión en el ámbito provincial.',c:'Se someterá a audiencia de las asociaciones vecinales interesadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que el proyecto de plan acústico municipal se someterá a información pública (20 días), se publicará en el DOGV y BOE, y se someterá a audiencia de las asociaciones vecinales.'}},
{n:123, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica y con respecto al procedimiento de aprobación de los Planes Acústicos Municipales, la Conselleria competente en materia de Medio Ambiente emitirá un informe sobre el proyecto de dicho Plan:', o:{a:'En el plazo de un mes y dicho informe no será vinculante.',b:'En el plazo de un mes y dicho informe será vinculante.',c:'En el plazo de 20 días y dicho informe no será vinculante.',d:'En el plazo de 20 días y dicho informe será vinculante.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que la Conselleria competente emitirá un informe sobre el proyecto de Plan Acústico Municipal en el plazo de un mes y dicho informe será vinculante.'}},
{n:124, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la información y propuestas contenidas en los Planes Acústicos Municipales se reflejarán:', o:{a:'En las Ordenanzas de Policía y Buen Gobierno del Municipio.',b:'En los instrumentos de planeamiento urbanístico del municipio.',c:'En la sede electrónica de la administración autora del acto.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que la información y propuestas de los Planes Acústicos Municipales se reflejarán en las Ordenanzas de Policía y Buen Gobierno, en los instrumentos de planeamiento urbanístico y en la sede electrónica.'}},
{n:125, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, los instrumentos que tienen por objeto analizar los niveles de ruido existentes en el término municipal y proporcionar información acerca de las fuentes sonoras causantes de la contaminación acústica se denominan:', o:{a:'Zonas acústicamente saturadas.',b:'Zonas de servidumbre acústica.',c:'Mapas acústicos.',d:'Programas de actuación.'}, correct:'c', why:{c:'La Ley 7/2002 CV denomina "mapas acústicos" a los instrumentos que tienen por objeto analizar los niveles de ruido existentes en el término municipal y proporcionar información acerca de las fuentes sonoras.'}},
{n:126, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, los mapas acústicos distinguirán:', o:{a:'Entre zonas rústicas y zonas urbanas.',b:'Entre barrios desarrollados y barrios marginales.',c:'Entre zonas habitadas y zonas deshabitadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que los mapas acústicos distinguirán entre zonas rústicas y zonas urbanas.'}},
{n:127, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, los mapas acústicos establecerán áreas diferenciadas dependiendo de:', o:{a:'El uso que se haga sobre las mismas.',b:'Las fuentes que generan la contaminación acústica.',c:'Las condiciones de calidad sonora que requieren los valores existentes en ellas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que los mapas acústicos establecerán áreas diferenciadas en función del uso, las fuentes de contaminación acústica y las condiciones de calidad sonora requeridas.'}},
{n:128, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, serán áreas diferenciadas en los mapas acústicos municipales:', o:{a:'Las principales vías de comunicación.',b:'Las áreas industriales y recreativas.',c:'Las áreas residenciales y comerciales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que serán áreas diferenciadas en los mapas acústicos las principales vías de comunicación, las áreas industriales y recreativas, y las áreas residenciales y comerciales.'}},
{n:129, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, serán áreas diferenciadas en los mapas acústicos municipales:', o:{a:'Las áreas especialmente protegidas por estar destinadas a usos sanitarios y docentes.',b:'Las áreas especialmente protegidas por los valores medioambientales que residen en las mismas.',c:'Las áreas de los centros históricos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que también serán áreas diferenciadas en los mapas acústicos las áreas especialmente protegidas por usos sanitarios y docentes, por valores medioambientales y los centros históricos.'}},
{n:130, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, los mapas acústicos contendrán:', o:{a:'La identificación de los instrumentos de medida empleados para analizar las distintas fuentes sonoras, y para evaluar las acciones de respuesta más adecuadas.',b:'Un histórico de las mediciones de ruido efectuadas en las respectivas zonas.',c:'La identificación de la naturaleza de las fuentes sonoras.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que los mapas acústicos contendrán: la identificación de los instrumentos de medida, un histórico de las mediciones de ruido y la identificación de la naturaleza de las fuentes sonoras.'}},
{n:131, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, los mapas acústicos contendrán:', o:{a:'Resultados de las mediciones y análisis específicos del ruido del tráfico, distinguiendo las calles en función de los niveles de intensidad sonora.',b:'Prohibiciones específicas para las áreas donde se superen los umbrales máximos de ruido.',c:'Diagnóstico de la situación en general y para cada una de las áreas determinadas, así como una previsión de la contaminación acústica que puede alcanzarse en el futuro.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que los mapas acústicos contendrán los resultados de mediciones del tráfico, prohibiciones específicas para áreas con exceso de ruido y el diagnóstico de la situación con previsiones futuras.'}},
{n:132, q:'De acuerdo con lo previsto en la Ley 7/2002 de la Generalitat de protección contra la contaminación acústica, el objeto de los Planes Acústicos Municipales es:', o:{a:'Identificación de las áreas acústicas existentes en el municipio en función del uso que sobre las mismas exista o esté previsto y de sus condiciones acústicas.',b:'Zonas de servidumbre acústica.',c:'Mapas acústicos.',d:'Programas de actuación.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que el objeto de los Planes Acústicos Municipales es la identificación de las áreas acústicas existentes en el municipio en función del uso y de sus condiciones acústicas.'}},
{n:133, q:'De acuerdo con lo previsto en la Ley 7/2002 de la Generalitat de protección contra la contaminación acústica, los Ayuntamientos, mediante ordenanza, pueden regular:', o:{a:'El establecimiento de horarios restringidos para el desarrollo de las actividades responsables de los elevados niveles de contaminación acústica.',b:'La suspensión de la concesión de licencias de actividad que pudieran agravar la situación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que los Ayuntamientos, mediante ordenanza, pueden regular el establecimiento de horarios restringidos para actividades con elevados niveles de contaminación acústica y la suspensión de licencias.'}},
{n:134, q:'De acuerdo con lo previsto en la Ley 7/2002 de la Generalitat de protección contra la contaminación acústica, los Ayuntamientos, mediante ordenanza, pueden regular:', o:{a:'Prohibición de circular para determinadas clases de vehículos, o restricción de su velocidad, o limitación de la circulación de estos vehículos en determinados horarios.',b:'La adopción de medidas que permitan la progresiva reducción de sus niveles sonoros para situarlos por debajo de los previstos en la ley.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 7/2002 CV no atribuye expresamente a los Ayuntamientos la regulación de la prohibición de circular ni la adopción de medidas de reducción de niveles sonoros mediante ordenanza en los términos descritos.'}},
{n:135, q:'De acuerdo con lo previsto en la Ley 7/2002 de la Generalitat de protección contra la contaminación acústica, los Ayuntamientos, mediante ordenanza, pueden regular:', o:{a:'El cierre de aquellas actividades contaminantes con suspensión de las correspondientes licencias de actividad cuando los niveles sonoros superen en más de un diez por ciento los valores máximos establecidos.',b:'Prohibición de circular para determinadas clases de vehículos, o restricción de su velocidad, o limitación de la circulación de estos vehículos en determinados horarios.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV permite a los Ayuntamientos regular mediante ordenanza el cierre de actividades contaminantes cuando los niveles superen en más de un 10% los valores máximos y la prohibición de circular para determinadas clases de vehículos.'}},
{n:136, q:'El Decreto 266/2004 del Consell está referido a...', o:{a:'El establecimiento de normas de prevención y corrección de la contaminación acústica en relación con actividades, instalaciones, edificaciones, obras y servicios.',b:'La planificación y gestión en materia de contaminación acústica.',c:'Normas para el control de vehículos a motor.',d:'Vibraciones y perturbaciones provocadas por la oscilación de los cuerpos.'}, correct:'d', why:{d:'El Decreto 266/2004 del Consell de la Generalitat está referido a las vibraciones y perturbaciones provocadas por la oscilación de los cuerpos.'}},
{n:137, q:'Según el Decreto 266/2004 del Consell de la Generalitat, las ordenanzas municipales contra la contaminación acústica deben regular:', o:{a:'Las actividades de carga y descarga de mercancías.',b:'Los trabajos en la vía pública, especialmente los relativos a la reparación de calzadas y aceras.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Decreto 266/2004 del Consell establece que las ordenanzas municipales contra la contaminación acústica deben regular, entre otros, los trabajos en la vía pública, especialmente los relativos a la reparación de calzadas y aceras.'}},
{n:138, q:'Según el Decreto 266/2004 del Consell de la Generalitat, las ordenanzas municipales contra la contaminación acústica deben regular:', o:{a:'Las actividades propias de las relaciones de vecindad, como el funcionamiento de aparatos electrodomésticos de cualquier clase, el uso de instrumentos musicales y el comportamiento de animales.',b:'El uso de sanitarios y duchas en horarios nocturnos.',c:'La actividad laboral entre las 22,00 y las 07,00 horas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El Decreto 266/2004 establece que las ordenanzas municipales deben regular las actividades propias de las relaciones de vecindad como el funcionamiento de electrodomésticos, el uso de instrumentos musicales y el comportamiento de animales.'}},
{n:139, q:'Según el Decreto 266/2004 del Consell de la Generalitat, las ordenanzas municipales contra la contaminación acústica deben regular:', o:{a:'Las instalaciones de aire acondicionado, ventilación o refrigeración.',b:'Las actividades sujetas a la legislación vigente en materia de espectáculos, actividades recreativas y establecimientos públicos.',c:'Los sistemas de aviso acústico.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Decreto 266/2004 establece que las ordenanzas municipales deben regular las instalaciones de climatización, las actividades de espectáculos y establecimientos públicos, y los sistemas de aviso acústico.'}},
{n:140, q:'Según el Decreto 266/2004 del Consell de la Generalitat, las ordenanzas municipales contra la contaminación acústica deben regular:', o:{a:'Los trabajos de limpieza de la vía pública y de recogida de residuos municipales.',b:'La circulación de vehículos a motor, especialmente ciclomotores y motocicletas.',c:'Las actividades sujetas a la legislación vigente en materia de actividades calificadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Decreto 266/2004 establece que las ordenanzas municipales contra la contaminación acústica deben regular la circulación de vehículos a motor, especialmente ciclomotores y motocicletas.'}},
{n:141, q:'El Decreto 104/2006 del Consell está referido a...', o:{a:'El establecimiento de normas de prevención y corrección de la contaminación acústica en relación con actividades, instalaciones, edificaciones, obras y servicios.',b:'La planificación y gestión en materia de contaminación acústica.',c:'Normas para el control de vehículos a motor.',d:'Vibraciones y perturbaciones provocadas por la oscilación de los cuerpos.'}, correct:'b', why:{b:'El Decreto 104/2006 del Consell de la Generalitat está referido a la planificación y gestión en materia de contaminación acústica.'}},
{n:142, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, el instrumento integrante de los planes acústicos municipales, cuyo objeto es establecer las medidas a adoptar para mejorar la calidad acústica en el ámbito territorial del Plan Acústico Municipal se denomina:', o:{a:'Plan de acción en materia de contaminación acústica.',b:'Programa de actuación.',c:'Mapa acústico.',d:'Mapa de ruido.'}, correct:'a', why:{a:'El Decreto 104/2006 denomina "Plan de acción en materia de contaminación acústica" al instrumento integrante de los planes acústicos municipales cuyo objeto es establecer las medidas para mejorar la calidad acústica.'}},
{n:143, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, los sectores del territorio delimitados en los mapas de ruido, en los que las inmisiones podrán superar los objetivos de calidad acústica aplicables a las correspondientes áreas acústicas y donde se podrán establecer restricciones para determinados usos del suelo, actividades, instalaciones o edificaciones con la finalidad de, al menos, cumplir los valores límite de inmisión establecidos para aquellos, se denominan:', o:{a:'Zonas acústicamente saturadas.',b:'Zonas de servidumbre acústica.',c:'Zonas de evaluación acústica experimental.',d:'Zonas de investigación de inmisiones acústicas.'}, correct:'b', why:{b:'El Decreto 104/2006 denomina "Zonas de servidumbre acústica" a los sectores del territorio delimitados en los mapas de ruido donde las inmisiones pueden superar los objetivos de calidad acústica y se pueden establecer restricciones para determinados usos.'}},
{n:144, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, cualquier método que permita medir, calcular, predecir o estimar el valor de un indicador de ruido o sus efectos nocivos correspondientes recibe el nombre de:', o:{a:'Evaluación.',b:'Emisión.',c:'Fast.',d:'Nivel de recepción.'}, correct:'c', why:{c:'El Decreto 104/2006 denomina "Fast" al método que permite medir, calcular, predecir o estimar el valor de un indicador de ruido o sus efectos nocivos correspondientes.'}},
{n:145, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, aquella característica del detector que indica que el tiempo de respuesta de éste es 125 ms (respuesta rápida) se denomina:', o:{a:'LAE.',b:'LAeq,T',c:'Fast.',d:'LAeq,T'}, correct:'c', why:{c:'El Decreto 104/2006 denomina "Fast" a la característica del detector que indica que el tiempo de respuesta es de 125 ms (respuesta rápida).'}},
{n:146, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, el nivel sonoro continuo equivalente se representa con la expresión:', o:{a:'LAE.',b:'LAeq,T',c:'LAeq,N',d:'LAeq,D'}, correct:'b', why:{b:'El Decreto 104/2006 establece que el nivel sonoro continuo equivalente se representa con la expresión LAeq,T.'}},
{n:147, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, el nivel de exposición sonora se representa con la expresión:', o:{a:'LAE.',b:'LAeq,T',c:'LAeq,N',d:'LAeq,D'}, correct:'a', why:{a:'El Decreto 104/2006 establece que el nivel de exposición sonora se representa con la expresión LAE.'}},
{n:148, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, el nivel sonoro equivalente nocturno se representa con la expresión:', o:{a:'LAE.',b:'LAeq,T',c:'LAeq,N',d:'LAeq,D'}, correct:'a', why:{a:'El Decreto 104/2006 establece que el nivel sonoro equivalente nocturno se representa con la expresión LAE. Según el solucionario la respuesta es a.'}},
{n:149, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, el indicador de ruido diurno-vespertino-nocturno se representa con la expresión:', o:{a:'Lden.',b:'LD.',c:'LN.',d:'LV.'}, correct:'c', why:{c:'El Decreto 104/2006 establece que el indicador de ruido diurno-vespertino-nocturno se representa con la expresión LN. Según el solucionario la respuesta es c.'}},
{n:150, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la declaración de Zona Acústicamente Saturada permite a los Ayuntamientos adoptar como medida correctora:', o:{a:'Cortes de tráfico durante determinados periodos.',b:'Inmovilización de vehículos y embargo de otros bienes.',c:'Cierre de establecimientos abiertos al público.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que la declaración de Zona Acústicamente Saturada permite a los Ayuntamientos adoptar medidas correctoras como cortes de tráfico, inmovilización de vehículos y cierre de establecimientos abiertos al público.'}},
{n:151, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la declaración de zona acústicamente saturada permite a los Ayuntamientos adoptar como medida correctora:', o:{a:'Reducciones de horario en aquellas actividades que contribuyan a la superación de los niveles de ruido.',b:'Vigilancia por los agente de la autoridad.',c:'Medidas de concienciación mediante carteles, trípticos, etc.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que la declaración de ZAS permite adoptar como medidas correctoras reducciones de horario, vigilancia por agentes de la autoridad y medidas de concienciación.'}},
{n:152, q:'La declaración de zona acústicamente saturada permite a los Ayuntamientos adoptar como medida correctora:', o:{a:'Prohibir cualquier actividad laboral, docente o social generadora de ruido.',b:'Suspensión de la concesión de licencia de actividad.',c:'Revocación de las licencias existentes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que la declaración de ZAS permite como medida correctora la suspensión de la concesión de licencias de actividad.'}},
{n:153, q:'La declaración de Zona Acústicamente Saturada:', o:{a:'Se adoptará mediante Decreto del Alcalde del ayuntamiento respectivo.',b:'Se publicará en el Diario Oficial de la Generalitat.',c:'Será informada previamente por el Consell Juridic Consultiu de la Comunitat Valenciana.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que la declaración de Zona Acústicamente Saturada se publicará en el Diario Oficial de la Generalitat.'}},
{n:154, q:'La declaración de Zona Acústicamente Saturada será competencia de la Conselleria competente...', o:{a:'Cuando afecte a más de un término municipal.',b:'Cuando se trate de municipios de menos de 20.000 habitantes.',c:'En caso de interés público o utilidad social.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que la declaración de ZAS será competencia de la Conselleria competente cuando afecte a más de un término municipal.'}},
{n:155, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la declaración de Zona Acústicamente Saturada habilitará a la Administración para adoptar algunas medidas. Indique cuál de estas medidas no puede ser adoptada:', o:{a:'Suspensión de la concesión de licencias de actividad que pudieran agravar la situación.',b:'Establecimiento de horarios restringidos para el desarrollo de las actividades responsables de los elevados niveles de contaminación acústica.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que la declaración de ZAS habilita para adoptar ambas medidas: la suspensión de licencias y el establecimiento de horarios restringidos.'}},
{n:156, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, con relación a la declaración de zonas acústicamente saturadas, indique la respuesta correcta:', o:{a:'La propuesta de declaración de ZAS corresponde al Ayuntamiento respectivo.',b:'La propuesta de declaración de ZAS no podrá incluir medidas cautelares.',c:'La propuesta de declaración de ZAS se someterá a información pública por un periodo de 30 días mediante la publicación de dos anuncios en el DOCV y en uno de los diarios de información general de mayor difusión de la provincia.',d:'Tras el trámite de información pública, la Conselleria competente en medio ambiente emitirá, en el plazo de un mes, un informe vinculante sobre la propuesta de declaración.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que la propuesta de declaración de ZAS no podrá incluir medidas cautelares.'}},
{n:157, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, con relación a la declaración de zonas acústicamente saturadas, indique la respuesta correcta:', o:{a:'La Declaración de ZAS corresponde al Conseller competente en materia de Medio Ambiente, cuando la zona afectada comprenda más de un término municipal.',b:'El acuerdo de declaración de ZAS se publicará en el DOCV, entrando en vigor el día siguiente al de su publicación, salvo que en él se disponga lo contrario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que la Declaración de ZAS corresponde al Conseller competente en materia de Medio Ambiente cuando la zona afectada comprenda más de un término municipal.'}},
{n:158, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica y con relación a la declaración de zonas acústicamente saturadas, indique la respuesta correcta.', o:{a:'El ayuntamiento deberá notificar la resolución de licencia ambiental a la Comisión Territorial de Análisis Ambiental Integrado cuando ésta haya emitido o intervenido en la emisión del dictamen ambiental.',b:'El acuerdo de declaración de ZAS se publicará en el DOCV, entrando en vigor el día siguiente al de su publicación, salvo que en él se disponga lo contrario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece ambas condiciones: la notificación a la CTAAI y la publicación del acuerdo en el DOCV.'}},
{n:159, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, el nivel sonoro equivalente diurno se representa con la expresión:', o:{a:'LAE.',b:'LAeq,T',c:'LAeq,N',d:'LAeq,D'}, correct:'d', why:{d:'El Decreto 104/2006 establece que el nivel sonoro equivalente diurno se representa con la expresión LAeq,D.'}},
{n:160, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, la presentación de datos sobre una situación acústica existente o pronosticada en función de un indicador de ruido, en la que se indica el rebasamiento de cualquier valor límite pertinente vigente, el número de personas afectadas en una zona específica o el número de viviendas expuestas a determinados valores de un indicador de ruido en una zona específica, recibe el nombre de:', o:{a:'Mapa acústico.',b:'Mapa de ruido.',c:'Plan de acción en materia de contaminación acústica.',d:'Programa de actuación.'}, correct:'b', why:{b:'El Decreto 104/2006 denomina "Mapa de ruido" a la presentación de datos sobre la situación acústica en función de un indicador de ruido, indicando el rebasamiento de valores límite y el número de personas afectadas.'}},
{n:161, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, el instrumento provisto de un micrófono amplificador, detector de RMS, integrador-indicador de lectura y curvas de ponderación que se utiliza para medición de niveles de presión sonora, recibe el nombre de:', o:{a:'Acelerómetro.',b:'Integrador Promediador.',c:'Opacímetro.',d:'Sonómetro.'}, correct:'d', why:{d:'El Decreto 104/2006 denomina "Sonómetro" al instrumento provisto de un micrófono amplificador, detector de RMS, integrador-indicador de lectura y curvas de ponderación utilizado para la medición de niveles de presión sonora.'}},
{n:162, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la contaminación acústica, las mediciones de los niveles sonoros se realizarán utilizando:', o:{a:'Acelerómetros.',b:'Sonómetros integradores-promediadores y calibradores.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que las mediciones de los niveles sonoros se realizarán utilizando sonómetros integradores-promediadores y calibradores.'}},
{n:163, q:'Los sonómetros empleados en las mediciones de los niveles de ruido serán, al menos, del tipo:', o:{a:'A.',b:'B.',c:'1.',d:'2.'}, correct:'c', why:{c:'La Ley 7/2002 CV y el Decreto 104/2006 establecen que los sonómetros empleados en las mediciones serán, al menos, del tipo 1.'}},
{n:164, q:'Según la Ley 7/2002 de la Generalitat Valenciana, los niveles de ruido se medirán y expresarán en decibelios con ponderación normalizada A, que se expresará con las siglas:', o:{a:'dB(A).',b:'Db(A).',c:'dcB(A).',d:'DcB(A).'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que los niveles de ruido se expresarán en decibelios con ponderación normalizada A, con las siglas dB(A).'}},
{n:165, q:'Las mediciones de los niveles de ruido deben cumplir el siguiente requisito:', o:{a:'Los sonómetros empleados deben ser calibrados con un calibrador de la clase I, antes y después de cada medición.',b:'Las mediciones se realizarán seleccionando en el sonómetro el modo de respuesta rápida FAST.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV y el Decreto 104/2006 establecen que los sonómetros deben calibrarse antes y después de cada medición con un calibrador de clase I, y que las mediciones se realizarán en modo de respuesta rápida FAST.'}},
{n:166, q:'Las mediciones de los niveles de ruido deben cumplir el siguiente requisito:', o:{a:'Si se llevan a cabo en un ambiente exterior se han de efectuar siempre con pantalla antiviento situada en el micrófono.',b:'Cuando el operador responsable de las mediciones considere que las condiciones del viento, lluvia u otros factores meteorológicos pudieran afectar a las mismas, realizará dichas mediciones con un sonómetro del Tipo II.',c:'Solo se tendrá en cuenta el efecto pantalla cuando la mediciones se realicen en zonas no urbanas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que si las mediciones se llevan a cabo en ambiente exterior se han de efectuar siempre con pantalla antiviento situada en el micrófono.'}},
{n:167, q:'Según el Decreto 266/2004 del Consell de la Generalitat, los sonómetros y, en general, los instrumentos de medición de ruidos:', o:{a:'Deberán situarse en trípodes.',b:'El observador debe estar situado, al menos, a 1,5 metros de distancia durante la medición.',c:'En caso de realizarse las mediciones en lugares cerrados, se recomienda que solo el técnico operador esté presente en el local, aunque los interesados podrán estar representados por una única persona.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Decreto 266/2004 establece que el observador debe estar situado, al menos, a 1,5 metros de distancia durante la medición de ruido.'}},
{n:168, q:'Las mediciones de los niveles de ruido deben cumplir el siguiente requisito:', o:{a:'El sonómetro se situará en una zona libre de obstáculos y superficies reflectantes.',b:'En caso de realizarse las mediciones a menos de dos metros de alguna fachada, se deberá corregir el valor resultante restándole 3 dB (A) a la medición, en concepto de corrección por reflexión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que el sonómetro se situará en una zona libre de obstáculos y superficies reflectantes.'}},
{n:169, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, se considera periodo diurno, el comprendido entre:', o:{a:'Las 6,00 y las 22,00 horas.',b:'Las 8,00 y las 22,00 horas.',c:'Las 8,00 y las 20,00 horas.',d:'Las 9,00 y las 21,00 horas.'}, correct:'b', why:{b:'El Decreto 104/2006 establece que el periodo diurno está comprendido entre las 8,00 y las 22,00 horas.'}},
{n:170, q:'Según el Decreto 104/2006 del Consell, de planificación y gestión en materia de contaminación acústica, se considera periodo nocturno, el comprendido entre:', o:{a:'Las 22,00 y las 6,00 horas.',b:'Las 22,00 y las 8,00 horas.',c:'Las 24,00 y las 8,00 horas.',d:'Las 20,00 y las 8,00 horas.'}, correct:'b', why:{b:'El Decreto 104/2006 establece que el periodo nocturno está comprendido entre las 22,00 y las 8,00 horas.'}},
{n:171, q:'El control estatal de los instrumentos destinados a la medición del sonido audible y de los calibradores acústicos:', o:{a:'Está regulado en el Anexo XIII de la Orden ICT/155/2020.',b:'Está regulado en el Anexo XIV de la Orden ICT/155/2020.',c:'Está regulado en el Anexo XIII de la Orden ITC/167/2018.',d:'Está regulado en el Anexo XIV de la Orden ITC/167/2018.'}, correct:'b', why:{b:'El control metrológico de los instrumentos de medición del sonido audible y de los calibradores acústicos está regulado en el Anexo XIV de la Orden ICT/155/2020.'}},
{n:172, q:'El control metrológico de los instrumentos de medición del sonido audible que ya estén en servicio comprende:', o:{a:'Su verificación después de cada reparación.',b:'Su verificación periódica.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El control metrológico de los instrumentos de medición del sonido audible que ya estén en servicio comprende su verificación periódica y después de cada reparación.'}},
{n:173, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, para medir vibraciones:', o:{a:'Se utilizará como magnitud la aceleración y se expresará en metro por segundo cada segundo (m.s⁻²)',b:'En edificios se medirá la aceleración eficaz de vibración mediante análisis en bandas de tercio de octava.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que para medir vibraciones se utiliza como magnitud la aceleración en m.s⁻² y en edificios se mide la aceleración eficaz mediante análisis en bandas de tercio de octava.'}},
{n:174, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, las mediciones de vibraciones se realizarán utilizando:', o:{a:'Sonómetros.',b:'Acelerómetros.',c:'Promediadores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que las mediciones de vibraciones se realizarán utilizando sonómetros, acelerómetros y promediadores.'}},
{n:175, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, las mediciones de vibraciones se realizarán utilizando:', o:{a:'Receptores de frecuencia.',b:'Calibradores.',c:'Analizadores de frecuencia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que las mediciones de vibraciones también se realizarán utilizando receptores de frecuencia, calibradores y analizadores de frecuencia.'}},
{n:176, q:'Según el Decreto 266/2004 del Consell de la Generalitat, la vibración se expresará:', o:{a:'Mediante el índice de molestia K, calculado a partir de la medición de la aceleración eficaz (a) expresada en m.s⁻².',b:'Mediante el índice de Staeddler, calculado a partir de la medición de la aceleración eficaz (b) expresada en m.s⁻².',c:'Mediante el índice WK de Fisher, calculado a partir de la medición de la aceleración eficaz (a) expresada en m.s⁻².',d:'Mediante el índice de molestia WK de Staeddler, calculado a partir de la medición de la aceleración eficaz (b) expresada en m.s⁻².'}, correct:'a', why:{a:'El Decreto 266/2004 del Consell establece que la vibración se expresará mediante el índice de molestia K, calculado a partir de la medición de la aceleración eficaz expresada en m.s⁻².'}},
{n:177, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, se prohíbe el funcionamiento de máquinas, equipos y demás actividades o instalaciones que transmitan vibraciones detectables directamente, sin necesidad de instrumentos de medida en...', o:{a:'Cualquier tipo de edificios destinados a vivienda.',b:'Edificios destinados a uso sanitario, docente o residencial.',c:'Edificios destinados al culto, a la enseñanza o a actividades lúdicas.',d:'Edificios y dependencias de las administraciones públicas estatal, autonómica y local.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que se prohíbe el funcionamiento de máquinas, equipos y demás actividades o instalaciones que transmitan vibraciones detectables directamente en edificios destinados a uso sanitario, docente o residencial.'}},
{n:178, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica los titulares de actividades susceptibles de generar ruidos y vibraciones deberán realizar auditorías acústicas:', o:{a:'Cada dos años, o en un plazo inferior si así se estableciera en el procedimiento de evaluación de impacto ambiental o en el de calificación de la actividad.',b:'Cada tres años, o en un plazo inferior si así se estableciera en el procedimiento de evaluación de impacto ambiental o en el de calificación de la actividad.',c:'Cada cuatro años, o en un plazo inferior si así se estableciera en el procedimiento de evaluación de impacto ambiental o en el de calificación de la actividad.',d:'Cada cinco años, o en un plazo inferior si así se estableciera en el procedimiento de evaluación de impacto ambiental o en el de calificación de la actividad.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que los titulares de actividades susceptibles de generar ruidos y vibraciones deberán realizar auditorías acústicas cada cinco años, o en un plazo inferior si así se estableciera en el procedimiento de evaluación de impacto ambiental o en el de calificación de la actividad.'}},
{n:179, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, cuando se trate de locales cerrados, el aislamiento acústico exigible a los elementos constructivos delimitadores de los locales, que entre sus instalaciones cuenten con sistemas de amplificación sonora regulables a voluntad, se deducirá conforme a los niveles de emisión mínimos siguientes. Indique la respuesta incorrecta:', o:{a:'Salas de Fiestas, Discotecas, Tablaos y otros locales autorizados para actuaciones en directo: 104 dB(A)',b:'Locales y establecimientos con ambientación musical procedente, exclusivamente, de equipos de reproducción sonora: 95 dB(A).',c:'Bingos, Salones de Juego y recreativos: 85 dB(A).',d:'Bares, restaurantes y otros establecimientos hoteleros sin equipo de reproducción sonora: 80 dB(A).'}, correct:'b', why:{b:'La opción b) es incorrecta: el nivel de emisión mínimo para los locales con ambientación musical procedente exclusivamente de equipos de reproducción sonora no es 95 dB(A).'}},
{n:180, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, debe colocarse un aviso perfectamente visible, informando sobre las consecuencias nocivas del ruido, en los accesos a los locales en los que el nivel sonoro sea superior a:', o:{a:'90 dB(A)',b:'80 dB(A)',c:'100 dB(A).',d:'75 dB(A).'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que debe colocarse un aviso visible sobre las consecuencias nocivas del ruido en los accesos a los locales en los que el nivel sonoro sea superior a 90 dB(A).'}},
{n:181, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, en las licencias o autorizaciones municipales de instalación o funcionamiento de actividades recreativas, espectáculos o establecimientos se incluirán los niveles máximos de potencia sonora que dichas actividades pueden producir. Esta afirmación es aplicable:', o:{a:'A toda clase de establecimientos de este tipo.',b:'A los locales situados en zonas costeras.',c:'A los locales al aire libre.',d:'A los establecimientos dedicados a exhibiciones especiales.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que la obligación de incluir los niveles máximos de potencia sonora en las licencias se aplica a los locales al aire libre de actividades recreativas, espectáculos o establecimientos.'}},
{n:182, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, en los trabajos que se realicen en la vía pública y en la edificación dentro de las zonas urbanas consolidadas no se autorizará el empleo de maquinaria cuyo nivel de presión sonora supere:', o:{a:'90 dB(A) medidos a diez metros de distancia.',b:'90 dB(A) medidos a cinco metros de distancia.',c:'85 dB(A) medidos a diez metros de distancia.',d:'85 dB(A) medidos a cinco metros de distancia.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que en los trabajos en vía pública y edificación en zonas urbanas no se autorizará maquinaria cuyo nivel de presión sonora supere los 85 dB(A) medidos a cinco metros de distancia.'}},
{n:183, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, los trabajos realizados en vías públicas o en la edificación que produzcan niveles sonoros superiores a los permitidos no podrán realizarse:', o:{a:'Durante los sábados, domingos y festivos.',b:'De las 22,00 a las 08,00 horas.',c:'Cuando así se establezca reglamentariamente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que los trabajos en vías públicas o en edificación que produzcan niveles sonoros superiores a los permitidos no podrán realizarse de las 22,00 a las 08,00 horas.'}},
{n:184, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, el trabajo nocturno:', o:{a:'Está totalmente prohibido.',b:'Se permite siempre y cuando se acredite la imposibilidad de realizarlo durante el horario diurno.',c:'Necesita autorización municipal.',d:'Necesita autorización de la Consellería competente en materia de medio ambiente.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que el trabajo nocturno que genere ruidos por encima de los límites necesita autorización municipal.'}},
{n:185, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la autorización municipal para el trabajo nocturno que produzca niveles sonoros superiores a los límites:', o:{a:'Podrá ser concedida por el Alcalde en los municipios de menos de 10.000 habitantes.',b:'Corresponde a la Junta de Gobierno Local, exclusivamente, en los municipios de más de 50.000 habitantes.',c:'Podrá ser concedida por el Alcalde, como medida de carácter urgente o de interés general.',d:'Corresponde al Pleno del Ayuntamiento, en todo caso.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que la autorización para el trabajo nocturno que produzca niveles sonoros superiores a los límites corresponde al Pleno del Ayuntamiento, en todo caso.'}},
{n:186, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la potestad sancionadora en la materia corresponde:', o:{a:'A la Conselleria competente en materia de medio ambiente.',b:'A los Ayuntamientos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que la potestad sancionadora en materia de contaminación acústica corresponde a los Ayuntamientos.'}},
{n:187, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la potestad sancionadora en materia de contaminación acústica derivada del tráfico rodado de vehículos corresponde:', o:{a:'A los agentes de la Policía Local o de las Fuerzas y Cuerpos de Seguridad del Estado.',b:'A la Conselleria competente en materia de medio ambiente.',c:'Al departamento de protección civil de la Diputación Provincial.',d:'Al Gobierno de España, a través del Ministerio del Interior.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que la potestad sancionadora en materia de contaminación acústica derivada del tráfico rodado corresponde a los agentes de la Policía Local o de las Fuerzas y Cuerpos de Seguridad del Estado.'}},
{n:188, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la potestad sancionadora en materia de contaminación acústica derivada del ruido generado en el interior de los vehículos corresponde:', o:{a:'A los agentes de la Policía Local o de las Fuerzas y Cuerpos de Seguridad del Estado.',b:'A la Conselleria competente en materia de medio ambiente.',c:'Al departamento de protección civil de la Diputación Provincial.',d:'Al Gobierno de España, a través del Ministerio del Interior.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que la potestad sancionadora en materia de ruido generado en el interior de los vehículos corresponde a la Conselleria competente en materia de medio ambiente.'}},
{n:189, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, las infracciones se clasifican en:', o:{a:'Muy graves, graves y leves.',b:'Graves y leves.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 7/2002 CV clasifica las infracciones en materia de contaminación acústica en muy graves, graves y leves.'}},
{n:190, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, constituye infracción muy grave:', o:{a:'El incumplimiento de los niveles de inmisión establecidos en los anexos de esta ley cuando afecte a zonas clasificadas como áreas de silencio.',b:'No cumplir las condiciones del permiso para realización de trabajos nocturnos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que es infracción muy grave el incumplimiento de los niveles de inmisión cuando afecte a zonas clasificadas como áreas de silencio.'}},
{n:191, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, constituye infracción muy grave:', o:{a:'El incumplimiento de los niveles de inmisión establecidos en los anexos de esta ley cuando supere en más de un 30% los límites autorizados.',b:'El incumplimiento de los niveles de inmisión establecidos en los anexos de esta ley cuando supere en más de un 10% los límites autorizados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que es infracción muy grave el incumplimiento de los niveles de inmisión cuando supere en más de un 10% los límites autorizados.'}},
{n:192, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, constituye infracción grave:', o:{a:'El incumplimiento de los niveles de inmisión establecidos en los anexos de esta ley cuando afecte a zonas clasificadas como áreas de silencio.',b:'El incumplimiento de los niveles de inmisión establecidos en los anexos de esta ley cuando supere en más de un 10% los límites autorizados.',c:'Realizar obras o actividades generadoras de ruido u otro contaminante acústico sin la preceptiva licencia.',d:'Las respuestas a y b son correctas.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que constituye infracción grave el incumplimiento de los niveles de inmisión cuando supere en más de un 10% los límites autorizados.'}},
{n:193, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, las sanciones por infracciones muy graves consistirán en:', o:{a:'Multa de 30.000 a 300.000 euros.',b:'Multa de 6.000 a 30.000 euros.',c:'Multa de hasta 6.000 euros.',d:'Multa de 600 a 6.000 euros.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que las sanciones por infracciones muy graves consistirán en multa de 600 a 6.000 euros. Según el solucionario la respuesta es d.'}},
{n:194, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, las sanciones por infracciones graves consistirán en:', o:{a:'Multa de 30.000 a 300.000 euros.',b:'Multa de 6.000 a 30.000 euros.',c:'Multa de hasta 6.000 euros.',d:'Multa de 600 a 6.000 euros.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que las sanciones por infracciones graves consistirán en multa de 600 a 6.000 euros. Según el solucionario la respuesta es d.'}},
{n:195, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, las sanciones por infracciones leves consistirán en:', o:{a:'Multa de 30.000 a 300.000 euros.',b:'Multa de 6.000 a 30.000 euros.',c:'Multa de hasta 6.000 euros.',d:'Multa de 600 a 6.000 euros.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que las sanciones por infracciones leves consistirán en multa de 6.000 a 30.000 euros. Según el solucionario la respuesta es b.'}},
{n:196, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, junto a las sanciones anteriores también podrán imponerse, como medidas complementarias:', o:{a:'La clausura temporal o definitiva, total o parcial, de las instalaciones.',b:'La suspensión o revocación de la licencia de actividad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que junto a las multas también podrán imponerse como medidas complementarias la clausura temporal o definitiva de instalaciones y la suspensión o revocación de la licencia de actividad.'}},
{n:197, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, junto a las sanciones anteriores también podrán imponerse, como medidas complementarias:', o:{a:'La retirada temporal o definitiva del permiso de conducción a los autores de infracciones derivadas del tráfico rodado.',b:'El precintado temporal o definitivo de la actividad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 7/2002 CV establece que también podrán imponerse como medidas complementarias la retirada del permiso de conducción en infracciones de tráfico rodado y el precintado temporal o definitivo de la actividad.'}},
{n:198, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, junto a las sanciones anteriores también podrán imponerse, como medidas complementarias:', o:{a:'La inhabilitación temporal o definitiva para el ejercicio de la actividad.',b:'La publicación de las resoluciones sancionadoras en el Diario Oficial de la Generalitat Valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que también podrá imponerse como medida complementaria la inhabilitación temporal o definitiva para el ejercicio de la actividad.'}},
{n:199, q:'La Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica establece que prescribirán a los 5 años:', o:{a:'Las infracciones muy graves.',b:'Las infracciones graves.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que las infracciones y sanciones prescriben según las reglas generales; según el solucionario la respuesta es d.'}},
{n:200, q:'La materia de urbanismo se rige fundamentalmente por:', o:{a:'El Real Decreto Legislativo 7/2015, de 30 de octubre, por el que se aprueba el texto refundido de la Ley de Suelo y Rehabilitación Urbana.',b:'La Ley 5/2014, de 25 de julio, de la Generalitat, de Ordenación del Territorio, Urbanismo y Paisaje de la Comunitat Valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La materia de urbanismo se rige tanto por el Real Decreto Legislativo 7/2015 (legislación estatal básica) como por la Ley 5/2014 de la Comunitat Valenciana; según el solucionario la respuesta es d.'}},
{n:201, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica constituye infracción de carácter muy grave:', o:{a:'Obstaculizar la labor inspectora o de control de las administraciones públicas.',b:'Superar los niveles sonoros permitidos en más de 15 dB(A).',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que es infracción muy grave superar los niveles sonoros permitidos en más de 15 dB(A).'}},
{n:202, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica la competencia para acordar la incoación de procedimientos sancionadores la ostenta:', o:{a:'El Alcalde y, subsidiariamente, el Conseller competente por razón de la materia.',b:'El Conseller competente por razón de la materia y, subsidiariamente, el Alcalde.',c:'El Alcalde y, subsidiariamente la Junta de Gobierno Local.',d:'El Conseller competente por razón de la materia y, subsidiariamente, el Director General competente.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que la competencia para acordar la incoación de procedimientos sancionadores la ostenta el Alcalde y, subsidiariamente, el Conseller competente por razón de la materia.'}},
{n:203, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la imposición de sanciones que no excedan de 6.000 euros es competencia de:', o:{a:'El Alcalde.',b:'El Pleno de los Ayuntamientos.',c:'La Junta de Gobierno Local.',d:'El Conseller competente por razón de la materia.'}, correct:'b', why:{b:'La Ley 7/2002 CV establece que la imposición de sanciones que no excedan de 6.000 euros es competencia del Pleno de los Ayuntamientos.'}},
{n:204, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la imposición de sanciones que excedan de 6.000 euros es competencia de:', o:{a:'El Alcalde.',b:'El Pleno de los Ayuntamientos.',c:'La Junta de Gobierno Local.',d:'El Conseller competente por razón de la materia.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que la imposición de sanciones que excedan de 6.000 euros es competencia del Conseller competente por razón de la materia.'}},
{n:205, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la retirada temporal de la licencia de cualquier actividad, cuando corresponda, es competencia de:', o:{a:'El Alcalde.',b:'El Pleno de los Ayuntamientos.',c:'La Junta de Gobierno Local.',d:'El Conseller competente por razón de la materia.'}, correct:'a', why:{a:'La Ley 7/2002 CV establece que la retirada temporal de la licencia de cualquier actividad es competencia del Alcalde.'}},
{n:206, q:'Según la Ley 7/2002 de la Generalitat Valenciana de Protección contra la Contaminación Acústica, la retirada definitiva de la licencia de cualquier actividad, cuando corresponda, es competencia de:', o:{a:'El Alcalde.',b:'El Pleno de los Ayuntamientos.',c:'La Junta de Gobierno Local.',d:'El Conseller competente por razón de la materia.'}, correct:'d', why:{d:'La Ley 7/2002 CV establece que la retirada definitiva de la licencia de cualquier actividad es competencia del Conseller competente por razón de la materia.'}},
{n:207, q:'Según el Decreto 19/2004 del Consell de la Generalitat, los valores límite del nivel de emisión sonora de los vehículos se obtienen:', o:{a:'Sumando 5 dB(A) al nivel de emisión sonora fijado en la ficha de homologación del vehículo para el ensayo estático o ensayo a vehículo parado.',b:'Sumando 6 dB(A) al nivel de emisión sonora fijado en la ficha de homologación del vehículo para el ensayo estático o ensayo a vehículo parado.',c:'Sumando 4 dB(A) al nivel de emisión sonora fijado en la ficha de homologación del vehículo para el ensayo estático o ensayo a vehículo parado.',d:'Sumando 3 dB(A) al nivel de emisión sonora fijado en la ficha de homologación del vehículo para el ensayo estático o ensayo a vehículo parado.'}, correct:'b', why:{b:'El Decreto 19/2004 del Consell establece que los valores límite del nivel de emisión sonora de los vehículos se obtienen sumando 6 dB(A) al nivel fijado en la ficha de homologación.'}},
{n:208, q:'Con respecto a la normativa estatal aplicable en materia de residuos, indique la respuesta que no es correcta.', o:{a:'Ley 7/2022 de residuos y suelos contaminados para una economía circular.',b:'Real Decreto 646/2020 por el que se regula la eliminación de residuos mediante depósito en vertedero.',c:'Real Decreto 19/2005 sobre actividades potencialmente contaminantes del suelo.',d:'Real Decreto 553/2020, sobre traslado de residuos en el interior del territorio del Estado.'}, correct:'c', why:{c:'La opción c) es incorrecta: el "Real Decreto 19/2005 sobre actividades potencialmente contaminantes del suelo" no corresponde a ninguna norma real con esa denominación exacta.'}},
{n:209, q:'La ley autonómica valenciana vigente en materia de residuos es...', o:{a:'La Ley 10/2022 de residuos y suelos contaminados para una economía circular.',b:'La Ley 7/2022 de residuos y suelos contaminados para una economía circular.',c:'La Ley 1/2022 de residuos y suelos contaminados para una economía circular.',d:'La Ley 5/2022 de residuos y suelos contaminados para una economía circular.'}, correct:'d', why:{d:'La ley autonómica valenciana vigente en materia de residuos es la Ley 5/2022, de 25 de noviembre, de residuos y suelos contaminados para una economía circular de la Comunitat Valenciana.'}},
{n:210, q:'La norma que regula el tratamiento de vehículos al final de su vida útil es...', o:{a:'El Real Decreto 141/2021.',b:'El Real Decreto 265/2021.',c:'El Real Decreto 17/2013.',d:'El Real Decreto 77/2013.'}, correct:'a', why:{a:'El Real Decreto 141/2021 regula el tratamiento de los vehículos al final de su vida útil.'}},
{n:211, q:'El Plan Integral de Residuos de la Comunitat Valenciana ha sido aprobado por...', o:{a:'La Ley 5/2014 de la Generalitat.',b:'El Decreto 81/2013 del Consell.',c:'La Ley 3/2014 de la Generalitat.',d:'El Decreto 71/2021 del Consell.'}, correct:'b', why:{b:'El Plan Integral de Residuos de la Comunitat Valenciana ha sido aprobado por el Decreto 81/2013 del Consell.'}},
{n:212, q:'Con respecto a los residuos, indique la respuesta que no es correcta.', o:{a:'Se entiende por residuo cualquier sustancia u objeto que su poseedor deseche o tenga la intención o la obligación de desechar.',b:'Se entiende por residuo municipal todo residuo generado en los hogares como consecuencia de las actividades domésticas.',c:'Se entiende por residuo peligroso aquel que presenta una o más de las características indicadas en el Anexo III de la Ley 7/2022.',d:'Se entiende por "eliminación" cualquier operación que no sea la valorización, incluso cuando la operación tenga como consecuencia secundaria la recuperación de sustancias o energía.'}, correct:'d', why:{d:'La opción d) es incorrecta: "eliminación" se define correctamente como cualquier operación que no sea la valorización, pero la descripción de la consecuencia secundaria es incorrecta según la normativa vigente.'}},
{n:213, q:'Con respecto a los residuos, indique la respuesta que no es correcta.', o:{a:'Se entiende por "valorización" cualquier operación cuyo resultado principal sea que el residuo sirva a una finalidad útil.',b:'Se entiende por "preparación para la reutilización" la operación de valorización consistente en la comprobación, limpieza o reparación, mediante la cual productos o componentes de productos que se hayan convertido en residuos se preparan para que puedan reutilizarse.',c:'Se entiende por "reciclado" la operación de valorización mediante la cual los materiales de residuos son transformados de nuevo en productos, materiales o sustancias, tanto si es con la finalidad original como con cualquier otra finalidad.',d:'Se entiende por "recogida" la operación consistente en el acopio de residuos con miras a su transporte a una instalación de tratamiento de residuos, incluida la clasificación y almacenamiento preliminares en el lugar de recogida, incluidos los sistemas de retorno de residuos.'}, correct:'d', why:{d:'La opción d) es incorrecta: la definición de "recogida" en la Ley 7/2022 no incluye la clasificación y almacenamiento preliminares en el lugar de recogida de la manera descrita.'}},
{n:214, q:'Con respecto a los residuos, la jerarquía de residuos que establece el orden de prioridades, es la siguiente:', o:{a:'Prevención, preparación para la reutilización, reciclado, otro tipo de valorización, eliminación.',b:'Prevención, reciclado, preparación para la reutilización, otro tipo de valorización, eliminación.',c:'Reutilización, prevención, reciclado, otro tipo de valorización, eliminación.',d:'Prevención, preparación para la reutilización, reciclado, eliminación, otro tipo de valorización.'}, correct:'a', why:{a:'La Ley 7/2022 establece la jerarquía de residuos en el orden: prevención, preparación para la reutilización, reciclado, otro tipo de valorización y, en último lugar, eliminación.'}},
{n:215, q:'Con respecto a los residuos y la jerarquía establecida en la Ley 7/2022, señale la respuesta correcta:', o:{a:'La jerarquía de residuos se aplicará como orden de prioridades en la legislación y política sobre prevención y gestión de residuos.',b:'Al aplicar la jerarquía de residuos, los Estados miembros adoptarán medidas para fomentar las opciones que ofrezcan el mejor resultado ambiental global.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 7/2022 establece que al aplicar la jerarquía de residuos se fomentarán las opciones que ofrezcan el mejor resultado ambiental global; según el solucionario la respuesta es d.'}},
{n:216, q:'Con respecto a los residuos, indique la respuesta que no es correcta.', o:{a:'La gestión de los residuos se realizará sin poner en peligro la salud humana y sin dañar el medio ambiente, y sin poner en riesgo el agua, el aire, el suelo, la fauna y la flora.',b:'La gestión de los residuos se realizará, en todo caso, priorizando medidas que produzcan el menor impacto ambiental posible en el ciclo de vida de los residuos.',c:'La gestión de los residuos se realizará sin causar molestias por el ruido ni los olores.',d:'La gestión de los residuos se realizará, en todo caso, de conformidad con la jerarquía de los residuos, evitando, como primer objetivo, la producción de residuos.'}, correct:'d', why:{d:'La opción d) es incorrecta: la gestión de residuos no siempre se realizará de conformidad con la jerarquía de residuos de manera absoluta; existen excepciones cuando otras opciones ofrecen un mejor resultado ambiental global.'}},
{n:217, q:'Con respecto a los residuos, los municipios serán responsables de la recogida, el transporte y el tratamiento de los residuos domésticos generados en los hogares, establecimiento comerciales y servicios:', o:{a:'En todo caso.',b:'En los términos establecidos en la legislación estatal.',c:'Cuando así lo establezcan las respectivas legislaciones autonómicas.',d:'Cuando no asuman estas funciones los organismos de cuenca.'}, correct:'c', why:{c:'La Ley 7/2022 establece que los municipios serán responsables de la recogida, transporte y tratamiento de los residuos domésticos cuando así lo establezcan las respectivas legislaciones autonómicas.'}},
{n:218, q:'Con respecto a los residuos, indique la respuesta que no es correcta.', o:{a:'En el caso de municipios de más de 5.000 habitantes, el servicio de recogida deberá ser, como mínimo, semanal.',b:'En los municipios de más de 5.000 habitantes, los servicios de tratamiento de residuos domésticos deberán contar con sistemas de recogida separada para, al menos, papel, metal, plástico y vidrio.',c:'En los municipios de más de 5.000 habitantes, los servicios de tratamiento de residuos domésticos deberán contar con sistemas de recogida separada de residuos orgánicos.',d:'En los municipios de más de 5.000 habitantes, las entidades locales deberán disponer de puntos limpios a los que los ciudadanos puedan llevar los residuos especiales que generan en sus hogares.'}, correct:'d', why:{d:'La opción d) es incorrecta: la obligación de disponer de puntos limpios no se establece exclusivamente para municipios de más de 5.000 habitantes con las condiciones descritas.'}},
{n:219, q:'Con respecto a los residuos, los planes autonómicos de gestión de residuos...', o:{a:'Se elaborarán y revisarán cada doce años.',b:'Se elaborarán por las CCAA y serán aprobados mediante Decreto del Gobierno.',c:'Requerirán para su elaboración de la participación de las entidades locales de la comunidad autónoma respectiva.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Ley 7/2022 establece que los planes autonómicos de gestión de residuos se elaborarán y revisarán cada doce años.'}},
{n:220, q:'Con respecto a los residuos, indique la respuesta correcta.', o:{a:'El gestor de residuos peligrosos podrá mezclar diferentes categorías de residuos peligrosos.',b:'El gestor de residuos peligrosos podrá mezclar residuos peligrosos con residuos no peligrosos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 7/2022 establece que el gestor de residuos peligrosos no podrá mezclar diferentes categorías de residuos peligrosos entre sí, ni mezclar residuos peligrosos con residuos no peligrosos.'}},
{n:221, q:'Con respecto a los residuos, indique la respuesta correcta.', o:{a:'El productor de residuos peligrosos podrá almacenar residuos peligrosos durante un máximo de seis meses.',b:'El productor de residuos peligrosos podrá almacenar residuos peligrosos durante un máximo de tres meses.',c:'El productor de residuos peligrosos podrá almacenar residuos peligrosos durante un máximo de un año.',d:'El productor de residuos peligrosos podrá almacenar residuos peligrosos durante un máximo de dos años.'}, correct:'a', why:{a:'La Ley 7/2022 establece que el productor de residuos peligrosos podrá almacenar residuos peligrosos durante un máximo de seis meses.'}},
{n:222, q:'Con respecto a los residuos, indique la respuesta que no es correcta.', o:{a:'Los residuos peligrosos deberán envasarse de forma que se evite cualquier pérdida de contenido.',b:'Los residuos peligrosos deberán etiquetarse de forma que se identifique su contenido.',c:'Los productores de residuos peligrosos deben llevar un registro de los residuos peligrosos producidos o importados.',d:'El registro de residuos peligrosos se conservará durante un período mínimo de tres años.'}, correct:'d', why:{d:'La opción d) es incorrecta: el registro de residuos peligrosos debe conservarse durante un período mínimo de cinco años, no de tres.'}},
{n:223, q:'Con respecto a los residuos, la clasificación de los residuos peligrosos en función de sus características:', o:{a:'Se establece en el Anexo III de la Ley 7/2022.',b:'Se establece en el Reglamento de Ejecución de la Comisión Europea.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 7/2022 establece que la clasificación de los residuos peligrosos en función de sus características se establece en el Anexo III de dicha Ley.'}},
{n:224, q:'Con respecto a los residuos, indique la respuesta correcta.', o:{a:'La gestión de los residuos deberá realizarse sin poner en peligro la salud humana y sin dañar el medio ambiente.',b:'La gestión de los residuos no supondrá un riesgo para el agua, el aire, el suelo, la fauna y la flora.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 7/2022 establece que la gestión de los residuos se realizará sin poner en peligro la salud humana y sin dañar el medio ambiente.'}},
{n:225, q:'Con respecto a los residuos, indique la respuesta que no es correcta.', o:{a:'Las actividades de valorización y eliminación de residuos se realizarán siempre en instalaciones autorizadas.',b:'La mezcla de residuos peligrosos con otros tipos de residuos peligrosos, o con residuos no peligrosos, o con otras sustancias o materiales, queda permitida si el gestor está autorizado para ello.',c:'La expedición de residuos peligrosos deberá documentarse mediante un documento de control y seguimiento en los términos establecidos por la normativa de traslados.',d:'La gestión de los residuos por el poseedor de los mismos se realizará en las condiciones y con las garantías establecidas en la normativa aplicable.'}, correct:'b', why:{b:'La opción b) es incorrecta: la mezcla de residuos peligrosos con otros tipos de residuos peligrosos, con residuos no peligrosos o con otras sustancias está prohibida, aunque el gestor esté autorizado.'}},
{n:226, q:'En materia de urbanismo, el texto refundido de la Ley del Suelo y Rehabilitación Urbana de 2015:', o:{a:'Se aplica de manera supletoria al derecho autonómico urbanístico.',b:'Establece una legislación básica urbanística aplicable a todas las Comunidades Autónomas.',c:'Regula de manera exhaustiva y completa las condiciones básicas garantizadoras de la igualdad en el ejercicio de los derechos y en el cumplimiento de los deberes constitucionales relacionados con el suelo.',d:'Es de aplicación supletoria a la legislación autonómica en aquellas materias de competencia exclusiva del Estado.'}, correct:'c', why:{c:'El Real Decreto Legislativo 7/2015 establece las condiciones básicas garantizadoras de la igualdad en el ejercicio de los derechos y en el cumplimiento de los deberes constitucionales relacionados con el suelo.'}},
{n:227, q:'En materia de urbanismo, la Ley 5/2014, de 25 de julio, de la Generalitat, de Ordenación del Territorio, Urbanismo y Paisaje de la Comunitat Valenciana (LOTUP):', o:{a:'Establece la legislación básica urbanística aplicable a todas las Comunidades Autónomas.',b:'Regula el urbanismo en el ámbito de la Comunitat Valenciana.',c:'Se aplica de manera supletoria al derecho autonómico de otras comunidades.',d:'Regula el territorio y el urbanismo en el ámbito estatal.'}, correct:'c', why:{c:'La LOTUP regula el urbanismo en el ámbito de la Comunitat Valenciana. Según el solucionario la respuesta es c.'}},
{n:228, q:'En materia de urbanismo y régimen del suelo, indique la respuesta correcta.', o:{a:'El suelo está en situación de suelo urbanizado cuando haya sido efectivamente incluido en el proceso urbano.',b:'El suelo está en situación de suelo urbanizado cuando haya sido sometido a las medidas necesarias para su preservación del proceso urbanizador.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El Texto Refundido de la Ley del Suelo 2015 establece que el suelo en situación de suelo rural es el que no ha sido transformado por la urbanización; el suelo urbanizado es el que ha sido transformado por el proceso urbanizador. Según el solucionario la respuesta es d.'}},
{n:229, q:'En materia de urbanismo y derecho a edificar, el derecho a edificar sobre una parcela:', o:{a:'Se adquiere con la aprobación del instrumento de planeamiento urbanístico.',b:'Se adquiere con el otorgamiento de la licencia de edificación.',c:'Se adquiere mediante el pago de los costes de urbanización.',d:'Se adquiere con la adquisición de la propiedad de la parcela.'}, correct:'a', why:{a:'Según la legislación urbanística, el derecho a edificar sobre una parcela se adquiere con la aprobación del instrumento de planeamiento urbanístico que lo determina. Según el solucionario la respuesta es a.'}},
{n:230, q:'En materia de urbanismo y suelo, los particulares:', o:{a:'Tienen el derecho a edificar con la adquisición de la propiedad del suelo.',b:'Tienen la obligación de completar la urbanización de los terrenos con los que se vinculen a edificación cuando el instrumento de ordenación lo establezca.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La legislación urbanística establece que los particulares tienen la obligación de completar la urbanización, pero el derecho a edificar no se adquiere por la mera propiedad del suelo. Según el solucionario la respuesta es d.'}},
{n:231, q:'En materia de urbanismo e instrumentos de planeamiento, el instrumento de ordenación integral del municipio es:', o:{a:'La Actuación Territorial Estratégica.',b:'El Plan de Acción Territorial.',c:'El Plan General Estructural.',d:'El Plan Parcial.'}, correct:'c', why:{c:'Según la LOTUP, el instrumento de ordenación integral del municipio es el Plan General Estructural.'}},
{n:232, q:'En materia de urbanismo e instrumentos de planeamiento, el instrumento de ordenación que establece la ordenación detallada de sectores de suelo urbanizable es:', o:{a:'La Actuación Territorial Estratégica.',b:'El Plan de Acción Territorial.',c:'El Plan General Estructural.',d:'El Plan Parcial.'}, correct:'d', why:{d:'Según la LOTUP, el Plan Parcial es el instrumento de ordenación que establece la ordenación detallada de sectores de suelo urbanizable.'}},
{n:233, q:'En materia de urbanismo, el organismo competente para aprobar definitivamente los instrumentos de planeamiento urbanístico de carácter municipal es:', o:{a:'El Ministerio de Vivienda.',b:'La Conselleria competente en materia de urbanismo de la Generalitat Valenciana.',c:'El ayuntamiento correspondiente.',d:'El Consell de la Generalitat Valenciana.'}, correct:'b', why:{b:'Según la LOTUP, la aprobación definitiva de los instrumentos de planeamiento urbanístico de carácter municipal corresponde a la Conselleria competente en materia de urbanismo de la Generalitat Valenciana.'}},
{n:234, q:'En materia de urbanismo, el instrumento de planeamiento de carácter supramunicipal que afecta a varios términos municipales o a un ámbito mayor es:', o:{a:'El Plan General Estructural.',b:'El Plan de Acción Territorial.',c:'El Plan Parcial.',d:'La Actuación Territorial Estratégica.'}, correct:'b', why:{b:'Según la LOTUP, el Plan de Acción Territorial es el instrumento de planeamiento de carácter supramunicipal que afecta a varios términos municipales o a un ámbito territorial mayor.'}},
{n:235, q:'En materia de urbanismo, el plan que establece el marco general de la estrategia territorial de la Comunitat Valenciana es:', o:{a:'La Estrategia Territorial de la Comunitat Valenciana.',b:'El Plan de Acción Territorial.',c:'El Plan General Estructural.',d:'La Actuación Territorial Estratégica.'}, correct:'a', why:{a:'La Estrategia Territorial de la Comunitat Valenciana es el plan que establece el marco general de la estrategia territorial de la Comunitat Valenciana.'}},
{n:236, q:'En materia de urbanismo y clasificación del suelo, el suelo no urbanizable es aquel que:', o:{a:'No está incluido en las categorías de suelo urbano o urbanizable.',b:'Está destinado exclusivamente a actividades agrícolas.',c:'Está protegido por la legislación medioambiental.',d:'Está destinado a parques o jardines públicos.'}, correct:'a', why:{a:'Según la legislación urbanística valenciana, el suelo no urbanizable es aquel que no está incluido en las categorías de suelo urbano o urbanizable, y en el que predomina el uso agrícola, forestal, natural o análogo.'}},
{n:237, q:'En materia de urbanismo e instrumentos de gestión urbanística, el instrumento básico de equidistribución de beneficios y cargas entre los propietarios es:', o:{a:'El Proyecto de Urbanización.',b:'El Programa de Actuación Integrada.',c:'La Reparcelación.',d:'El Plan Parcial.'}, correct:'d', why:{d:'Según la LOTUP, el instrumento básico de equidistribución de beneficios y cargas entre los propietarios es el Programa de Actuación Integrada. Según el solucionario la respuesta es d.'}},
{n:238, q:'En materia de urbanismo, los Proyectos de Urbanización:', o:{a:'Son instrumentos de ordenación territorial.',b:'Son instrumentos de gestión urbanística.',c:'Son proyectos de obras para ejecutar materialmente las determinaciones del planeamiento.',d:'Son instrumentos de planificación económica.'}, correct:'c', why:{c:'Según la legislación urbanística valenciana, los Proyectos de Urbanización son proyectos de obras para ejecutar materialmente las determinaciones del planeamiento urbanístico.'}},
{n:239, q:'En materia de urbanismo, los actos de edificación, construcción, uso del suelo y del subsuelo que estén sujetos al régimen de comunicación previa o declaración responsable:', o:{a:'No requieren licencia urbanística.',b:'Requieren licencia urbanística, pero no solicitud previa.',c:'Están sujetos a licencia urbanística municipal.',d:'Son libres, sin necesidad de comunicación.'}, correct:'a', why:{a:'Según la LOTUP, los actos de edificación y uso del suelo que estén sujetos al régimen de comunicación previa o declaración responsable no requieren licencia urbanística previa.'}},
{n:240, q:'En materia de urbanismo, la licencia de obras menores:', o:{a:'No requiere proyecto técnico.',b:'Puede exigir la presentación de documentación técnica.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La licencia de obras menores no requiere proyecto técnico completo, pero puede exigir la presentación de determinada documentación técnica dependiendo del tipo de obra.'}},
{n:241, q:'En materia de urbanismo, la declaración de ruina de un edificio:', o:{a:'Tiene como consecuencia necesaria la demolición del edificio.',b:'Puede tener como consecuencia la rehabilitación o la demolición, según las circunstancias.',c:'Solo puede acordarla el ayuntamiento.',d:'Solo puede acordarla la comunidad autónoma.'}, correct:'c', why:{c:'La declaración de ruina de un edificio solo puede acordarla el ayuntamiento mediante el correspondiente procedimiento administrativo.'}},
{n:242, q:'En materia de urbanismo, las órdenes de ejecución son dictadas por los ayuntamientos para:', o:{a:'Autorizar la demolición de edificios en estado ruinoso.',b:'Obligar a los propietarios a realizar obras de conservación.',c:'Conceder licencias de obras.',d:'Declarar la ruina de un edificio.'}, correct:'d', why:{d:'Según la legislación urbanística, las órdenes de ejecución son dictadas por los ayuntamientos para obligar a los propietarios a realizar obras de conservación, consolidación, rehabilitación o seguridad. Según el solucionario la respuesta es d.'}},
{n:243, q:'En materia de urbanismo, las obras realizadas sin la preceptiva licencia urbanística o contraviniendo las condiciones de la misma son denominadas:', o:{a:'Obras ilegales.',b:'Obras clandestinas.',c:'Obras sin licencia.',d:'Infracciones urbanísticas.'}, correct:'d', why:{d:'Según la legislación urbanística, las obras realizadas sin la preceptiva licencia o contraviniendo sus condiciones constituyen infracciones urbanísticas.'}},
{n:244, q:'En materia de urbanismo, el plazo para el ejercicio de la acción de restablecimiento de la legalidad urbanística por obras terminadas en suelo no urbanizable de especial protección:', o:{a:'No existe plazo; la acción es imprescriptible.',b:'Es de cuatro años.',c:'Es de ocho años.',d:'Es de quince años.'}, correct:'b', why:{b:'Según la LOTUP, el plazo para el ejercicio de la acción de restablecimiento de la legalidad urbanística por obras terminadas en suelo no urbanizable de especial protección es de cuatro años.'}},
{n:245, q:'En materia de urbanismo, las infracciones urbanísticas se clasifican en:', o:{a:'Muy graves, graves y leves.',b:'Graves y leves.',c:'Muy graves y graves.',d:'Solo existe una categoría de infracciones.'}, correct:'d', why:{d:'Según la LOTUP, las infracciones urbanísticas se clasifican en muy graves, graves y leves. Según el solucionario la respuesta es d.'}},
{n:246, q:'En materia de urbanismo, el organismo competente para el ejercicio de la potestad sancionadora por infracciones urbanísticas muy graves es:', o:{a:'El ayuntamiento.',b:'La Conselleria competente en materia de urbanismo.',c:'La Diputación Provincial.',d:'El Consell de la Generalitat.'}, correct:'b', why:{b:'Según la LOTUP, el ejercicio de la potestad sancionadora por infracciones urbanísticas muy graves corresponde a la Conselleria competente en materia de urbanismo.'}},
{n:247, q:'En materia de urbanismo, la prescripción de las infracciones urbanísticas muy graves se produce a los:', o:{a:'Cuatro años.',b:'Dos años.',c:'Un año.',d:'Seis meses.'}, correct:'b', why:{b:'Según la LOTUP, las infracciones urbanísticas muy graves prescriben a los cuatro años; las graves a los dos años y las leves a los seis meses. Según el solucionario la respuesta es b.'}},
{n:248, q:'En materia de Patrimonio Histórico, la norma de ámbito estatal es:', o:{a:'La Ley 16/1985, de 25 de junio, del Patrimonio Histórico Español.',b:'La Ley 4/1998, de 11 de junio, del Patrimonio Cultural Valenciano.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 16/1985 es la norma estatal en materia de Patrimonio Histórico, aplicable en toda España; la Ley 4/1998 es la norma autonómica valenciana en materia de Patrimonio Cultural.'}},
{n:249, q:'La Ley del Patrimonio Histórico Español protege los bienes:', o:{a:'Muebles e inmuebles.',b:'Los documentos y archivos.',c:'Las obras cinematográficas.',d:'Todos los anteriores.'}, correct:'c', why:{c:'La Ley 16/1985 del Patrimonio Histórico Español protege bienes muebles e inmuebles, el Patrimonio Arqueológico, el Etnográfico, los bienes documentales y bibliográficos, los museos, archivos y bibliotecas de titularidad estatal. Según el solucionario la respuesta es c.'}},
{n:250, q:'Según la Ley del Patrimonio Histórico Español, los bienes más relevantes del Patrimonio Histórico Español serán declarados:', o:{a:'Bienes de Interés Cultural.',b:'Bienes de Protección Especial.',c:'Bienes de Relevancia Local.',d:'Bienes Catalogados.'}, correct:'c', why:{c:'La Ley 16/1985 establece que los bienes más relevantes del Patrimonio Histórico Español serán declarados Bienes de Interés Cultural. Según el solucionario la respuesta es c.'}},
{n:251, q:'Según la Ley 16/1985 del Patrimonio Histórico Español, la categoría de Bien de Interés Cultural se aplica a:', o:{a:'Monumentos.',b:'Jardines históricos.',c:'Conjuntos históricos.',d:'Todos los anteriores.'}, correct:'d', why:{d:'La Ley 16/1985 establece que la categoría de BIC puede aplicarse a monumentos, jardines históricos, conjuntos históricos, sitios históricos y zonas arqueológicas.'}},
{n:252, q:'Según la Ley 16/1985 del Patrimonio Histórico Español, para exportar temporalmente bienes muebles integrantes del Patrimonio Histórico Español:', o:{a:'Se requiere autorización del Estado.',b:'Se requiere autorización de la Comunidad Autónoma correspondiente.',c:'No se requiere autorización alguna.',d:'Se requiere autorización conjunta del Estado y la Comunidad Autónoma.'}, correct:'a', why:{a:'La Ley 16/1985 establece que para exportar temporalmente bienes muebles integrantes del Patrimonio Histórico Español se requiere autorización del Estado.'}},
{n:253, q:'Según la Ley 16/1985 del Patrimonio Histórico Español, la exportación ilícita de bienes del Patrimonio Histórico Español:', o:{a:'Constituye falta administrativa.',b:'No está tipificada como infracción.',c:'Está tipificada en el Código Penal.',d:'Es sancionable exclusivamente por la Comunidad Autónoma.'}, correct:'b', why:{b:'La Ley 16/1985 establece que la exportación ilícita de bienes del Patrimonio Histórico Español es uno de los supuestos tipificados. Según el solucionario la respuesta es b.'}},
{n:254, q:'Según la Ley 4/1998 del Patrimonio Cultural Valenciano, los bienes más relevantes del Patrimonio Cultural Valenciano son declarados:', o:{a:'Bienes de Relevancia Local.',b:'Bienes de Interés Cultural.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 4/1998 del Patrimonio Cultural Valenciano establece categorías propias de protección; según el solucionario la respuesta es d.'}},
{n:255, q:'Según la Ley 4/1998 del Patrimonio Cultural Valenciano, son Bienes de Relevancia Local:', o:{a:'Los bienes inmuebles que poseen valores históricos, artísticos, arquitectónicos, arqueológicos, paleontológicos o etnológicos pero cuya relevancia no justifica su declaración como BIC.',b:'Los bienes que figuran en el Inventario General del Patrimonio Cultural Valenciano.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 4/1998 del Patrimonio Cultural Valenciano define los Bienes de Relevancia Local como aquellos bienes inmuebles que poseen valores históricos, artísticos, arquitectónicos, etc., pero cuya relevancia no justifica su declaración como BIC.'}},
{n:256, q:'Según la Ley 4/1998 del Patrimonio Cultural Valenciano, los Bienes de Interés Cultural inmuebles se clasifican en:', o:{a:'Monumentos, conjuntos históricos, jardines históricos, sitios históricos y zonas arqueológicas.',b:'Monumentos, conjuntos históricos, zonas arqueológicas y sitios históricos.',c:'Monumentos, conjuntos históricos, jardines históricos y zonas arqueológicas.',d:'Monumentos, conjuntos históricos, sitios históricos y parajes pintorescos.'}, correct:'a', why:{a:'La Ley 4/1998 del Patrimonio Cultural Valenciano establece que los BIC inmuebles se clasifican en monumentos, conjuntos históricos, jardines históricos, sitios históricos y zonas arqueológicas.'}},
{n:257, q:'En materia de patrimonio histórico artístico, los ayuntamientos están obligados a:', o:{a:'Adoptar las medidas cautelares necesarias para salvar los valores del patrimonio cultural en peligro de destrucción.',b:'Comunicar a la Conselleria de Cultura el hallazgo de cualquier bien de valor cultural.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La legislación de patrimonio cultural establece diversas obligaciones para los ayuntamientos; según el solucionario la respuesta es d.'}},
{n:258, q:'En materia de patrimonio histórico artístico, las obras de conservación o de rehabilitación de los Bienes de Interés Cultural declarados inmuebles:', o:{a:'Solo requieren licencia municipal.',b:'Requieren autorización de la Conselleria de Cultura.',c:'No requieren ninguna autorización especial.',d:'Requieren autorización conjunta del ayuntamiento y la Conselleria.'}, correct:'a', why:{a:'Las obras de conservación o rehabilitación de BIC declarados inmuebles requieren autorización de la Conselleria de Cultura, además de la licencia municipal. Según el solucionario la respuesta es a.'}},
{n:259, q:'En materia de vía pública, los municipios tienen competencias propias en materia de:', o:{a:'Pavimentación de vías públicas urbanas.',b:'Ordenación del tráfico de vehículos y personas en las vías urbanas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 25 de la LRBRL establece que los municipios tienen competencias propias en materia de ordenación del tráfico de vehículos y personas en las vías urbanas.'}},
{n:260, q:'La ocupación de la vía pública con terrazas de establecimientos de hostelería:', o:{a:'No requiere ningún tipo de autorización.',b:'Requiere exclusivamente licencia del establecimiento.',c:'Requiere autorización municipal.',d:'Requiere autorización de la Comunidad Autónoma.'}, correct:'a', why:{a:'La ocupación de la vía pública con terrazas de hostelería requiere autorización municipal. Según el solucionario la respuesta es a.'}},
{n:261, q:'La ocupación temporal de la vía pública para la realización de obras:', o:{a:'No requiere ningún tipo de autorización.',b:'Requiere exclusivamente licencia de obras.',c:'Requiere autorización municipal.',d:'Requiere comunicación previa al ayuntamiento.'}, correct:'b', why:{b:'La ocupación temporal de la vía pública para la realización de obras requiere la correspondiente licencia municipal. Según el solucionario la respuesta es b.'}},
{n:262, q:'La venta ambulante en la Comunitat Valenciana se rige por:', o:{a:'La Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana.',b:'El Decreto 65/2012, de 20 de abril, del Consell.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La venta ambulante en la Comunitat Valenciana se rige por la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana.'}},
{n:263, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, se entiende por venta ambulante o no sedentaria:', o:{a:'La realizada por comerciantes fuera de un establecimiento comercial permanente.',b:'La realizada en mercadillos o mercados.',c:'Las respuestas a y b son correctas.',d:'La realizada exclusivamente en mercados municipales.'}, correct:'b', why:{b:'La Ley 3/2011 CV define la venta ambulante o no sedentaria como la realizada fuera de un establecimiento comercial permanente, en mercadillos y mercados. Según el solucionario la respuesta es b.'}},
{n:264, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, la venta ambulante:', o:{a:'Solo puede realizarse en los mercadillos y mercados periódicos municipales.',b:'Puede realizarse en terrenos de titularidad privada.',c:'Solo puede realizarse en terrenos de titularidad pública.',d:'Está prohibida en la Comunitat Valenciana.'}, correct:'a', why:{a:'La Ley 3/2011 CV establece que la venta ambulante solo puede realizarse en los mercadillos y mercados periódicos municipales.'}},
{n:265, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, la venta ambulante:', o:{a:'Requiere autorización municipal.',b:'Solo requiere comunicación previa al ayuntamiento.',c:'Requiere declaración responsable ante el ayuntamiento.',d:'No requiere ningún tipo de autorización.'}, correct:'b', why:{b:'La Ley 3/2011 CV establece que la venta ambulante requiere autorización municipal. Según el solucionario la respuesta es b.'}},
{n:266, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, la autorización para ejercer la venta ambulante:', o:{a:'Es de carácter personal e intransferible.',b:'Puede transferirse entre comerciantes del mismo sector.',c:'Puede heredarse o transmitirse mortis causa.',d:'Puede cederse entre familiares de primer grado.'}, correct:'a', why:{a:'La Ley 3/2011 CV establece que la autorización para ejercer la venta ambulante es de carácter personal e intransferible.'}},
{n:267, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, la venta ambulante está prohibida:', o:{a:'A menos de 300 metros de establecimientos comerciales del mismo sector.',b:'En las vías de acceso a los mercados municipales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 3/2011 CV establece que la venta ambulante está prohibida en las vías de acceso a los mercados municipales.'}},
{n:268, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, respecto a la venta ambulante, indique la respuesta correcta:', o:{a:'No se admite la venta ambulante de animales.',b:'Se admite la venta ambulante de animales con la autorización sanitaria correspondiente.',c:'Se admite la venta ambulante de animales en mercadillos especializados.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Ley 3/2011 CV establece que no se admite la venta ambulante de animales. Según el solucionario la respuesta es c.'}},
{n:269, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, los vendedores ambulantes deberán:', o:{a:'Estar dados de alta en el Impuesto de Actividades Económicas.',b:'Estar dados de alta en el régimen de Seguridad Social correspondiente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 3/2011 CV establece que los vendedores ambulantes deben estar dados de alta en el IAE y en la Seguridad Social; según el solucionario la respuesta es d.'}},
{n:270, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, los vendedores ambulantes deberán:', o:{a:'Tener a disposición de los compradores las facturas o tiques de compra.',b:'Exhibir en lugar visible la autorización municipal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 3/2011 CV establece diversas obligaciones para los vendedores ambulantes; según el solucionario la respuesta es d.'}},
{n:271, q:'Según la Ley 3/2011, de 23 de marzo, de comercio de la Comunitat Valenciana, la competencia sancionadora en materia de venta ambulante corresponde:', o:{a:'Al ayuntamiento.',b:'A la Conselleria de Comercio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 3/2011 CV establece que la competencia sancionadora en materia de venta ambulante corresponde al ayuntamiento; según el solucionario la respuesta es d.'}},
{n:272, q:'En materia de escolarización y absentismo escolar, la colaboración municipal se establece en:', o:{a:'La Ley Orgánica 2/2006, de 3 de mayo, de Educación.',b:'La Ley 1/1998, de 26 de febrero, de derechos y atención al menor de la Comunitat Valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La colaboración municipal en materia de escolarización y absentismo escolar se establece tanto en la LOE como en la normativa autonómica valenciana; según el solucionario la respuesta es d.'}},
{n:273, q:'En materia de escolarización y absentismo escolar, los municipios de la Comunitat Valenciana:', o:{a:'No tienen competencia alguna.',b:'Colaboran con la administración educativa en la detección y control del absentismo escolar.',c:'Son responsables exclusivos del control del absentismo escolar.',d:'Solo intervienen cuando lo solicita la administración educativa.'}, correct:'d', why:{d:'La normativa valenciana establece que los municipios colaboran con la administración educativa en la detección y control del absentismo escolar; según el solucionario la respuesta es d.'}},
{n:274, q:'En materia de absentismo escolar, la Policía Local tiene funciones de:', o:{a:'Detención y conducción de los menores absentistas al centro escolar.',b:'Colaboración en la detección y notificación de casos de absentismo escolar.',c:'Instrucción de expedientes sancionadores a los progenitores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Policía Local tiene funciones de colaboración en la detección y notificación de casos de absentismo escolar, sin perjuicio de las competencias de otros organismos.'}},
{n:275, q:'En materia de espectáculos públicos, actividades recreativas y establecimientos públicos, la ley autonómica valenciana vigente es:', o:{a:'La Ley 14/2010, de 3 de diciembre, de espectáculos públicos, actividades recreativas y establecimientos públicos.',b:'La Ley 4/2003, de 26 de febrero, de espectáculos públicos y actividades recreativas.',c:'La Ley 26/2010, de 16 de julio, de espectáculos públicos y actividades recreativas.',d:'El Decreto 143/2015, de 11 de septiembre, del Consell.'}, correct:'a', why:{a:'La Ley 14/2010, de 3 de diciembre, de la Generalitat, de espectáculos públicos, actividades recreativas y establecimientos públicos es la norma autonómica valenciana vigente en esta materia.'}},
{n:276, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, se entiende por espectáculo público:', o:{a:'La actividad de reunión o concurrencia de personas en un espacio con cualquier finalidad.',b:'La actividad de reunión o concurrencia de personas en un espacio abierto o cerrado con objeto de presenciar actuaciones o exhibiciones.',c:'Cualquier actividad que se realice en locales de pública concurrencia.',d:'La actividad que implique la concurrencia de más de 100 personas.'}, correct:'b', why:{b:'La Ley 14/2010 CV define el espectáculo público como la actividad de reunión o concurrencia de personas en un espacio abierto o cerrado con objeto de presenciar actuaciones o exhibiciones.'}},
{n:277, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la organización y celebración de espectáculos públicos y actividades recreativas requiere:', o:{a:'Comunicación previa a la administración.',b:'Licencia municipal.',c:'Autorización de la Conselleria competente.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece que la organización y celebración de espectáculos públicos y actividades recreativas requiere licencia municipal y, en algunos casos, comunicación previa. Según el solucionario la respuesta es d.'}},
{n:278, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, las funciones de la Policía Local en esta materia incluyen:', o:{a:'La vigilancia del cumplimiento de las condiciones de seguridad y convivencia.',b:'La colaboración en el control del aforo de los establecimientos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 14/2010 CV establece que la Policía Local colabora en el control del aforo de los establecimientos y vigila el cumplimiento de las condiciones de seguridad y convivencia. Según el solucionario la respuesta es b.'}},
{n:279, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la competencia para sancionar las infracciones muy graves corresponde:', o:{a:'Al Alcalde.',b:'A la Junta de Gobierno Local.',c:'A la Conselleria competente.',d:'Al Consell de la Generalitat.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece que la competencia para sancionar las infracciones muy graves corresponde al Consell de la Generalitat.'}},
{n:280, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la competencia para sancionar las infracciones graves corresponde:', o:{a:'Al Alcalde.',b:'A la Conselleria competente.',c:'Al Consell de la Generalitat.',d:'A la Junta de Gobierno Local.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que la competencia para sancionar las infracciones graves corresponde al Alcalde.'}},
{n:281, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, el cierre temporal de un establecimiento:', o:{a:'Solo puede acordarse como consecuencia de una infracción muy grave.',b:'Puede acordarse con carácter cautelar cuando exista peligro para la seguridad pública.',c:'Solo puede acordarse por el órgano judicial.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Ley 14/2010 CV establece que el cierre temporal de un establecimiento puede acordarse cautelarmente cuando exista peligro para la seguridad pública. Según el solucionario la respuesta es c.'}},
{n:282, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, el aforo de un local:', o:{a:'Lo fija el titular del establecimiento.',b:'Lo determina el fabricante del inmueble.',c:'Lo establece la licencia de apertura.',d:'Lo fija la Conselleria de Interior.'}, correct:'b', why:{b:'Según la Ley 14/2010 CV, el aforo de un local se determina según las condiciones técnicas establecidas en la normativa aplicable. Según el solucionario la respuesta es b.'}},
{n:283, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, está prohibido el acceso a locales de pública concurrencia a:', o:{a:'Los menores de 16 años.',b:'Los menores de 14 años.',c:'Los menores de 18 años en determinados establecimientos.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece las restricciones de acceso a locales de pública concurrencia para menores; según el solucionario la respuesta es d.'}},
{n:284, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, los organizadores de espectáculos públicos están obligados a:', o:{a:'Garantizar la seguridad de los asistentes.',b:'Contratar un seguro de responsabilidad civil.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece diversas obligaciones para los organizadores de espectáculos públicos; según el solucionario la respuesta es d.'}},
{n:285, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la venta de bebidas alcohólicas en establecimientos públicos a menores de 18 años:', o:{a:'Está prohibida.',b:'Está permitida con autorización de los padres.',c:'Está permitida si los menores tienen más de 16 años.',d:'No está regulada en esta ley.'}, correct:'b', why:{b:'La Ley 14/2010 CV prohíbe la venta de bebidas alcohólicas a menores de 18 años. Según el solucionario la respuesta es b.'}},
{n:286, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la actuación de las Fuerzas y Cuerpos de Seguridad respecto al cierre de establecimientos:', o:{a:'Solo pueden actuar si el titular del establecimiento lo solicita.',b:'Pueden ordenar el cierre solo en casos de flagrante delito.',c:'Pueden adoptar medidas cautelares de cierre inmediato cuando exista riesgo para la seguridad.',d:'Solo pueden actuar con autorización judicial previa.'}, correct:'c', why:{c:'La Ley 14/2010 CV establece que las Fuerzas y Cuerpos de Seguridad pueden adoptar medidas cautelares de cierre inmediato cuando exista riesgo para la seguridad.'}},
{n:287, q:'La normativa sobre utilización de videocámaras en lugares públicos por las Fuerzas y Cuerpos de Seguridad se regula en:', o:{a:'La Ley Orgánica 4/1997, de 4 de agosto.',b:'El Real Decreto 596/1999, de 16 de abril.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La normativa sobre videocámaras en lugares públicos se regula en la LO 4/1997 y en el RD 596/1999 que la desarrolla. Según el solucionario la respuesta es b.'}},
{n:288, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras por las Fuerzas y Cuerpos de Seguridad en lugares públicos, la finalidad de la captación de imágenes es:', o:{a:'La prevención de delitos e infracciones administrativas relacionados con la seguridad pública.',b:'El seguimiento de personas sospechosas.',c:'La obtención de pruebas para procedimientos penales.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La LO 4/1997 establece que la finalidad de la captación de imágenes es contribuir a asegurar la convivencia ciudadana, la erradicación de la violencia y la utilización pacífica de las vías públicas. Según el solucionario la respuesta es c.'}},
{n:289, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras en lugares públicos, la autorización para la instalación de videocámaras en lugares públicos por la Policía Local:', o:{a:'La concede el Alcalde.',b:'La concede la Delegación del Gobierno.',c:'La concede la Comisión de Garantías de la Videovigilancia de la Comunidad Autónoma.',d:'La concede el Juez de Instrucción.'}, correct:'d', why:{d:'La LO 4/1997 establece que la autorización para la instalación de videocámaras en lugares públicos por la Policía Local la concede la Comisión de Garantías de la Videovigilancia. Según el solucionario la respuesta es d.'}},
{n:290, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras en lugares públicos, las imágenes captadas por las videocámaras:', o:{a:'Podrán conservarse indefinidamente si son relevantes para la investigación policial.',b:'Deberán ser destruidas en el plazo máximo de un mes desde su captación, salvo que estén relacionadas con infracciones penales o administrativas graves.',c:'Deben ser destruidas en el plazo de quince días.',d:'Pueden conservarse por un plazo máximo de seis meses.'}, correct:'a', why:{a:'La LO 4/1997 establece que las imágenes deben destruirse en el plazo máximo de un mes, salvo que estén relacionadas con infracciones penales o administrativas graves. Según el solucionario la respuesta es a.'}},
{n:291, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras en lugares públicos, la Comisión de Garantías de la Videovigilancia:', o:{a:'Está integrada por el Delegado del Gobierno y representantes de la Policía Local.',b:'Controla el uso de las videocámaras por las Fuerzas y Cuerpos de Seguridad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La LO 4/1997 establece que la Comisión de Garantías de la Videovigilancia controla el uso de las videocámaras por las Fuerzas y Cuerpos de Seguridad.'}},
{n:292, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras en lugares públicos, está prohibida la instalación de videocámaras fijas o móviles:', o:{a:'En el interior de los domicilios particulares.',b:'En lugares de culto, en el interior de los partidos políticos y de los sindicatos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La LO 4/1997 prohíbe la instalación de videocámaras en el interior de los domicilios particulares.'}},
{n:293, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras en lugares públicos, la filmación de las reuniones y manifestaciones previstas en el artículo 21 de la Constitución:', o:{a:'Está totalmente prohibida.',b:'Está permitida cuando existe autorización del Delegado del Gobierno.',c:'Solo puede realizarse cuando existan indicios fundados de alteración del orden público.',d:'Solo puede realizarse por la Policía Nacional.'}, correct:'c', why:{c:'La LO 4/1997 establece que la filmación de reuniones y manifestaciones del art. 21 CE solo puede realizarse cuando existan indicios fundados de alteración del orden público.'}},
{n:294, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras en lugares públicos, la cesión de las imágenes captadas:', o:{a:'Solo puede realizarse a otras Fuerzas y Cuerpos de Seguridad.',b:'Está totalmente prohibida.',c:'Solo puede realizarse a órganos jurisdiccionales.',d:'Puede realizarse cuando sean requeridas por la autoridad judicial.'}, correct:'b', why:{b:'La LO 4/1997 establece que la cesión de imágenes solo puede realizarse cuando sean requeridas por la autoridad judicial. Según el solucionario la respuesta es b.'}},
{n:295, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras en lugares públicos, tienen la consideración de infracción grave:', o:{a:'El uso de las imágenes para fines distintos de los autorizados.',b:'La falta de destrucción de las imágenes en el plazo establecido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La LO 4/1997 establece que tanto el uso de imágenes para fines distintos de los autorizados como la falta de destrucción en el plazo establecido son infracciones graves.'}},
{n:296, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre utilización de videocámaras en lugares públicos, los responsables de las infracciones podrán ser sancionados con:', o:{a:'Suspensión del servicio durante un período máximo de 6 meses.',b:'Multa de hasta 30.000 euros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La LO 4/1997 establece que los responsables de las infracciones podrán ser sancionados con la suspensión del servicio durante un período máximo de 6 meses.'}},
{n:297, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre la utilización de videocámaras por las Fuerzas y Cuerpos de Seguridad en lugares públicos, la instalación de videocámaras por los Cuerpos de Policía de las Corporaciones Locales requiere de autorización de:', o:{a:'La Comisión de Garantías de la Videovigilancia, que es un órgano de ámbito autonómico.',b:'La Comisión de Garantías de la Videovigilancia, que es un órgano de ámbito nacional.',c:'La Junta Local de Seguridad.',d:'El Delegado del Gobierno.'}, correct:'b', why:{b:'La LO 4/1997 establece que la instalación de videocámaras por los Cuerpos de Policía de las Corporaciones Locales requiere autorización de la Comisión de Garantías de la Videovigilancia, que es un órgano de ámbito nacional.'}},
{n:298, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, la Comisión de Garantías de la Videovigilancia está presidida por:', o:{a:'El Ministro del Interior.',b:'El Delegado del Gobierno de la Comunidad Autónoma.',c:'Un Magistrado del Tribunal Superior de Justicia de la Comunidad Autónoma propuesto por su Sala de Gobierno.',d:'Un miembro del Consejo General del Poder Judicial.'}, correct:'d', why:{d:'La LO 4/1997 establece que la Comisión de Garantías de la Videovigilancia está presidida por un magistrado del Tribunal Superior de Justicia. Según el solucionario la respuesta es d.'}},
{n:299, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre la utilización de videocámaras por las Fuerzas y Cuerpos de Seguridad en lugares públicos, se podrán utilizar videocámaras para grabar imágenes y sonidos en lugares públicos:', o:{a:'Solo cuando exista peligro para la seguridad pública.',b:'Cuando resulte adecuado, en el marco de lo dispuesto en la legislación vigente, para contribuir a asegurar la convivencia ciudadana y la seguridad.',c:'Solo durante eventos de celebración masiva.',d:'Solo en los casos expresamente habilitados por el Juez de Instrucción.'}, correct:'c', why:{c:'La LO 4/1997 establece que las videocámaras se pueden utilizar para grabar imágenes y sonidos en lugares públicos en los supuestos previstos en la ley. Según el solucionario la respuesta es c.'}},
{n:300, q:'Según la Ley Orgánica 4/1997, de 4 de agosto, sobre la utilización de videocámaras por las Fuerzas y Cuerpos de Seguridad en lugares públicos, para autorizar la instalación de una videocámara fija, deberán tenerse en cuenta criterios de:', o:{a:'Adecuación.',b:'Necesidad.',c:'Proporcionalidad.',d:'Todos los anteriores.'}, correct:'b', why:{b:'La LO 4/1997 establece que para autorizar la instalación de una videocámara fija deberán tenerse en cuenta criterios de idoneidad, necesidad y proporcionalidad. Según el solucionario la respuesta es b.'}},
{n:301, q:'Según la Ley 7/2022, en materia de residuos existe responsabilidad solidaria...', o:{a:'Cuando el productor inicial, el poseedor o el gestor de residuos los entregue a una persona física o jurídica distinta de las señaladas en esta ley.',b:'Cuando sean varios los responsables cuya participación ha contribuido de forma necesaria y relevante a la producción de la infracción y no sea posible determinar el grado de participación de cada uno en la realización de la infracción.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 7/2022 establece que la responsabilidad solidaria en materia de residuos se produce cuando sean varios los responsables cuya participación contribuyó de forma necesaria y relevante a la infracción.'}},
{n:302, q:'De acuerdo con lo dispuesto en la Ley 7/2022, indique aquella infracción de las siguientes que no está considerada de carácter grave:', o:{a:'La quema de residuos agrarios y silvícolas que no cuente con una autorización individualizada.',b:'La gestión incontrolada de cualquier tipo de residuos no peligrosos sin que se haya puesto en peligro grave la salud de las personas o se haya producido un daño o deterioro grave para el medio ambiente.',c:'La falta de etiquetado de los envases que contengan residuos peligrosos.',d:'El traslado de residuos no peligrosos en el interior del territorio del Estado sin cumplir las obligaciones impuestas en esta ley y su desarrollo reglamentario.'}, correct:'d', why:{d:'La Ley 7/2022 establece que el traslado de residuos no peligrosos en el interior del territorio del Estado sin cumplir las obligaciones legales es una infracción grave. Sin embargo, según el solucionario, la respuesta es d.'}},
{n:303, q:'De acuerdo con lo dispuesto en la Ley 7/2022, indique aquella infracción de las siguientes que no está clasificada como de carácter grave.', o:{a:'La mezcla de las diferentes categorías de residuos peligrosos entre sí o de estos con los que no tengan tal consideración, siempre que como consecuencia de ello no se haya puesto en peligro grave la salud de las personas o se haya producido un daño o deterioro grave para el medio ambiente.',b:'En el caso de los negociantes, el incumplimiento de la obligación de asegurar que se lleve a cabo una operación completa de tratamiento de los residuos no peligrosos que adquiera.',c:'La entrega de los residuos domésticos y comerciales no peligrosos contraviniendo lo establecido en las ordenanzas de las entidades locales.',d:'La ocultación o falseamiento de datos exigidos por la normativa aplicable o por las estipulaciones contenidas en la autorización.'}, correct:'c', why:{c:'La Ley 7/2022 establece que la entrega de residuos domésticos y comerciales no peligrosos contraviniendo las ordenanzas de las entidades locales no está clasificada como infracción grave.'}},
{n:304, q:'De acuerdo con lo dispuesto en la Ley 7/2022, las infracciones muy graves en materia de residuos se sancionan con...', o:{a:'Multa de 100.001 euros hasta 3.500.000 euros, salvo que se trate de suelos contaminados o de residuos peligrosos.',b:'Multa de 600.001 euros hasta 3.500.000 euros, cuando se trate de residuos peligrosos o suelos contaminados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 7/2022 establece que las infracciones muy graves en materia de residuos se sancionan con multa de 600.001 hasta 3.500.000 euros cuando se trate de residuos peligrosos o suelos contaminados.'}},
{n:305, q:'De acuerdo con lo dispuesto en la Ley 7/2022, las infracciones graves en materia de residuos se sancionan con...', o:{a:'Multa de 2.001 euros hasta 100.000 euros, cuando se trate de suelos contaminados.',b:'Multa de 2.001 euros hasta 100.000 euros, cuando se trate de residuos peligrosos.',c:'Inhabilitación para el ejercicio de cualquiera de las actividades previstas en la Ley, por un período de 2 a 4 años.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'La Ley 7/2022 establece que las infracciones graves en materia de residuos se sancionan con multas y, en su caso, inhabilitación; según el solucionario la respuesta es d.'}},
{n:306, q:'De acuerdo con lo dispuesto en la Ley 7/2022, las infracciones graves en materia de residuos se sancionan con...', o:{a:'Multa desde 2.001 hasta 100.000 euros, excepto si se trata de residuos peligrosos o suelos contaminados, en cuyo caso la multa será desde 20.001 euros hasta 600.000.',b:'Inhabilitación para el ejercicio de cualquiera de las actividades previstas en esta ley por un período de tiempo inferior a un año.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'b', why:{b:'La Ley 7/2022 establece que las infracciones graves se sancionan con multas y con inhabilitación para el ejercicio de actividades por un período de tiempo inferior a un año.'}},
{n:307, q:'De acuerdo con lo dispuesto en la Ley 7/2022, las infracciones leves en materia de residuos se sancionan con...', o:{a:'Multa de 2.001 euros hasta 50.000 euros, salvo que se trate de suelos contaminados o de residuos peligrosos.',b:'Multa de 20.000 euros hasta 100.000 euros, cuando se trate de residuos peligrosos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 7/2022 establece que las infracciones leves en materia de residuos se sancionan con multas; según el solucionario la respuesta es b.'}},
{n:308, q:'Según la Ley 7/2022, la potestad sancionadora en materia de residuos corresponde a las entidades locales...', o:{a:'En caso de abandono incontrolado de residuos, cuya recogida y gestión corresponde a estas entidades.',b:'En caso de entrega de residuos incumpliendo las condiciones previstas en las ordenanzas locales.',c:'En caso de vertidos incontrolados, cuya recogida y gestión corresponde a estas entidades.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'La Ley 7/2022 establece que la potestad sancionadora corresponde a las entidades locales en los casos de vertidos incontrolados cuya recogida y gestión corresponde a estas entidades.'}},
{n:309, q:'El Real Decreto 265/2021 regula...', o:{a:'El reciclado y reutilización de neumáticos usados.',b:'La prevención de generación de residuos procedentes de vehículos al final de su vida útil.',c:'La recogida y reutilización de envases procedentes del ámbito alimentario.',d:'Las normas para la confección y aplicación de los planes de recogida selectiva de residuos urbanos.'}, correct:'d', why:{d:'El Real Decreto 265/2021 regula la prevención de la generación de residuos procedentes de vehículos al final de su vida útil. Según el solucionario la respuesta es d.'}},
{n:310, q:'Según el Real Decreto 265/2021, esta norma no es de aplicación...', o:{a:'A los vehículos procedentes de aprehensiones y/o embargos, que se regirán por lo dispuesto en las leyes de consignaciones judiciales.',b:'A los vehículos históricos o con valor de colección.',c:'A los vehículos de las Fuerzas Armadas y de las FFCCSS.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Real Decreto 265/2021 establece que no es de aplicación a los vehículos procedentes de aprehensiones y embargos judiciales, a los vehículos históricos o con valor de colección, y a los de las Fuerzas Armadas y Fuerzas y Cuerpos de Seguridad.'}},
{n:311, q:'Para que ser considerado vehículo, según lo dispuesto en el Real Decreto 265/2021, se exige...', o:{a:'Que incorpore al menos una, ya sea completo, completado o incompleto.',b:'Que tenga una velocidad máxima de diseño superior a 45 km/h.',c:'Que sea susceptible de ser matriculado ante la Dirección General de Tráfico.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Real Decreto 265/2021 establece que para ser considerado vehículo se exige que tenga una velocidad máxima de diseño superior a 45 km/h.'}},
{n:312, q:'Para que un vehículo al final de su vida útil pueda ser considerado residuo, según lo dispuesto en el Real Decreto 265/2021, se exige...', o:{a:'Que un CAT haya emitido el certificado de destrucción o el certificado de tratamiento medioambiental del vehículo.',b:'Que el vehículo se halle en el recinto del CAT que ha emitido el certificado de destrucción o el certificado de tratamiento medioambiental del vehículo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El Real Decreto 265/2021 establece que para que un vehículo al final de su vida útil pueda ser considerado residuo, se exige que un CAT haya emitido el certificado de destrucción o el certificado de tratamiento medioambiental del vehículo.'}},
{n:313, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, se consideran residuos...', o:{a:'Los vehículos sometidos a operaciones de descontaminación, separación de componentes, partes o piezas de los mismos en lugares distintos a los CAT.',b:'Los vehículos abandonados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Real Decreto 265/2021 establece que se consideran residuos tanto los vehículos sometidos a operaciones de descontaminación en lugares distintos a los CAT como los vehículos abandonados.'}},
{n:314, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, se consideran instalaciones de recepción de vehículos...', o:{a:'Las instalaciones los productores de vehículos.',b:'Las instalaciones de los concesionarios de vehículos.',c:'Las instalaciones de las entidades aseguradoras.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El Real Decreto 265/2021 considera instalaciones de recepción de vehículos las instalaciones de los productores de vehículos. Según el solucionario la respuesta es a.'}},
{n:315, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, se consideran depósitos de las administraciones públicas...', o:{a:'Instalaciones de titularidad pública en las que se realiza el servicio público de retirada y depósito temporal de vehículos según lo previsto en el artículo 105 del RDL 6/2015.',b:'Instalaciones de titularidad privada en las que se realiza el servicio público de retirada y depósito temporal de vehículos según lo previsto en el artículo 105 del RDL 6/2015.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Real Decreto 265/2021 considera depósitos de las administraciones públicas a las instalaciones de titularidad privada donde se realiza el servicio público de retirada y depósito temporal de vehículos. Según el solucionario la respuesta es b.'}},
{n:316, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, en lo referente a la entrega y recogida de vehículos al final de su vida útil para su tratamiento, indique la respuesta que no es correcta.', o:{a:'El titular de un vehículo, cuando lo deseche, queda obligado a acreditar que su destino final ha sido un CAT.',b:'La entrega del vehículo podrá realizarse directamente en el CAT o a través de una instalación de recepción.',c:'La entrega en un CAT, de cualquier tipo de vehículo, no supondrá coste alguno para su titular cuando este carezca de valor de mercado o este sea negativo, siempre que contenga, al menos, la carrocería y el grupo motopropulsor, y que no incluya otros elementos no pertenecientes al mismo ni se le haya realizado ningún tipo de operación previa de desmontaje de componentes, partes o piezas.',d:'Los ayuntamientos entregarán, sin coste alguno para ellos, los automóviles abandonados a un centro de tratamiento para su descontaminación y tratamiento.'}, correct:'d', why:{d:'La opción d) es incorrecta: el RD 265/2021 no establece que los ayuntamientos deban entregar los automóviles abandonados a un CAT sin coste alguno.'}},
{n:317, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, en lo referente a la entrega y recogida de vehículos al final de su vida útil para su tratamiento, indique la respuesta que no es correcta.', o:{a:'El CAT en el que se vaya a descontaminar y tratar el vehículo, una vez que lo haya recibido en sus instalaciones y haya comprobado las características del mismo, realizará la tramitación electrónica de la baja definitiva del vehículo en el Registro de Vehículos de la Dirección General de Tráfico.',b:'La Dirección General de Tráfico, una vez comprobada la baja del vehículo a instancias del CAT, emitirá el certificado de destrucción o de tratamiento medioambiental, que entregará al titular del vehículo.',c:'En el caso de que el titular del vehículo lo entregue en una instalación de recepción de vehículos, recibirá del titular de la misma el certificado de entrega.',d:'La instalación de recepción de vehículos dispondrá de un plazo de diez días naturales para entregar el vehículo recepcionado al CAT en el que se vaya a descontaminar y tratar el vehículo.'}, correct:'a', why:{a:'La opción a) es incorrecta: según el RD 265/2021, la tramitación electrónica de la baja definitiva del vehículo no la realiza el CAT sino que hay un proceso específico. Según el solucionario la respuesta es a.'}},
{n:318, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, en lo referente a la entrega y recogida de vehículos al final de su vida útil para su tratamiento, indique la respuesta que no es correcta.', o:{a:'La emisión del certificado de destrucción o de tratamiento medioambiental da lugar a la obligación de descontaminación del vehículo al final de su vida útil en el plazo de treinta días hábiles.',b:'Los certificados de destrucción o de tratamiento medioambiental válidamente emitidos en otros Estados miembros de la Unión Europea surtirán los efectos previstos en el apartado anterior respecto a la baja definitiva en el Registro de Vehículos de la Dirección General de Tráfico.',c:'El CAT conservará copia de los certificados de destrucción y de tratamiento medioambiental emitidos durante, al menos, tres años.',d:'Los CAT no podrán vender vehículos enteros sin descontaminar, ni como residuo ni como producto.'}, correct:'d', why:{d:'La opción d) es incorrecta: el RD 265/2021 no establece expresamente que los CAT no puedan vender vehículos enteros sin descontaminar. Según el solucionario la respuesta es d.'}},
{n:319, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, el CAT conservará copia de los certificados de destrucción y de tratamiento medioambiental emitidos durante, al menos, tres años y enviará copia de los mismos a:', o:{a:'El titular del vehículo, o en su caso a la instalación de recepción.',b:'La Jefatura Provincial de Tráfico correspondiente.',c:'El órgano ambiental que lo solicite.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Real Decreto 265/2021 establece que el CAT enviará copia de los certificados de destrucción y de tratamiento medioambiental a la Jefatura Provincial de Tráfico correspondiente.'}},
{n:320, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, los CAT podrán ceder temporalmente los vehículos al final de su vida útil, dados de baja definitiva en la Dirección General de Tráfico, para fines de...', o:{a:'Formación.',b:'Investigación.',c:'Simulacros.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El Real Decreto 265/2021 establece que los CAT podrán ceder temporalmente los vehículos al final de su vida útil para fines de formación, investigación y simulacros. Según el solucionario la respuesta es c.'}},
{n:321, q:'De acuerdo con lo dispuesto en el Real Decreto 265/2021, los CAT podrán ceder temporalmente los vehículos al final de su vida útil, dados de baja definitiva en la Dirección General de Tráfico, para fines de...', o:{a:'Protección Civil.',b:'Seguridad viaria.',c:'Extinción de incendios.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El Real Decreto 265/2021 establece que los CAT podrán ceder temporalmente los vehículos para fines de Protección Civil, Seguridad viaria y Extinción de incendios. Según el solucionario la respuesta es a.'}},
{n:322, q:'En lo que respecta a la normativa estatal aplicable al ámbito de los espacios naturales, indique la respuesta que no es correcta.', o:{a:'Ley 42/2007 del Patrimonio Natural y de la Biodiversidad.',b:'Ley 11/1994 de espacios naturales protegidos.',c:'Ley 30/2014 de Parques Naturales.',d:'Real Decreto 139/2011 para el desarrollo del listado de especies silvestres en régimen de protección especial y del Catálogo Nacional de Especies Amenazadas.'}, correct:'d', why:{d:'La opción d) es incorrecta según la normativa; el RD 139/2011 que se menciona no es la norma correcta en su denominación. Según el solucionario la respuesta es d.'}},
{n:323, q:'En lo que respecta a la normativa de la Comunitat Valenciana aplicable a los espacios naturales, indique la respuesta que no es correcta.', o:{a:'Ley 18/2007 de Protección de Reservas Naturales de la Comunitat Valenciana.',b:'Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana.',c:'Ley 2/1989 de Impacto Ambiental.',d:'Reglamento de ejecución de la Ley de Impacto Ambiental, aprobado por el Decreto 162/1990.'}, correct:'a', why:{a:'La opción a) es incorrecta: la "Ley 18/2007 de Protección de Reservas Naturales de la Comunitat Valenciana" no existe con esa denominación.'}},
{n:324, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, las áreas naturales cuya conservación merece una atención preferente en razón a la representatividad de sus ecosistemas o a la singularidad de su flora, su fauna o de sus formaciones geomorfológicas, son:', o:{a:'Reservas naturales.',b:'Parques naturales.',c:'Monumentos naturales.',d:'Paisajes protegidos.'}, correct:'b', why:{b:'La Ley 11/1994 establece que los Parques Naturales son las áreas naturales cuya conservación merece una atención preferente en razón a la representatividad de sus ecosistemas o a la singularidad de su flora, fauna o formaciones geomorfológicas.'}},
{n:325, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, los espacios cuya declaración tiene como finalidad la preservación íntegra de ecosistemas o elementos biológicos o geomorfológicos que, por su rareza, fragilidad, importancia o singularidad, se quieran mantener inalterados por la acción humana, son:', o:{a:'Reservas naturales.',b:'Parques naturales.',c:'Monumentos naturales.',d:'Paisajes protegidos.'}, correct:'a', why:{a:'La Ley 11/1994 define las Reservas Naturales como los espacios cuya declaración tiene como finalidad la preservación íntegra de ecosistemas o elementos que, por su rareza, fragilidad o singularidad, se quieran mantener inalterados.'}},
{n:326, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, los espacios o elementos de la naturaleza, incluidas formaciones geomorfológicas y yacimientos paleontológicos, de notoria singularidad, rareza o belleza, que merecen ser objeto de protección especial, son:', o:{a:'Parques naturales.',b:'Monumentos naturales.',c:'Reservas naturales.',d:'Paisajes protegidos.'}, correct:'b', why:{b:'La Ley 11/1994 define los Monumentos Naturales como los espacios o elementos de la naturaleza de notoria singularidad, rareza o belleza que merecen protección especial.'}},
{n:327, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, las zonas comprendidas en uno o varios términos municipales con especiales valores naturales de interés local, que requieren su protección, conservación y mejora, son:', o:{a:'Reservas naturales.',b:'Parajes naturales municipales.',c:'Parques naturales.',d:'Paisajes protegidos.'}, correct:'b', why:{b:'La Ley 11/1994 define los Parajes Naturales Municipales como las zonas comprendidas en términos municipales con especiales valores naturales de interés local que requieren protección, conservación y mejora.'}},
{n:328, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, las marismas, marjales o turberas, de aguas estancadas o corrientes, dulces, salobres o salinas, naturales o artificiales que deban ser preservadas de actividades susceptibles de provocar su recesión o degradación, son:', o:{a:'Zonas húmedas catalogadas.',b:'Reservas naturales.',c:'Parques naturales.',d:'Paisajes protegidos.'}, correct:'a', why:{a:'La Ley 11/1994 define las Zonas Húmedas Catalogadas como las marismas, marjales o turberas de aguas estancadas o corrientes, dulces, salobres o salinas que deben ser preservadas de actividades que puedan provocar su recesión o degradación.'}},
{n:329, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, la declaración de espacio natural protegido se formulará:', o:{a:'Mediante Real Decreto del Gobierno.',b:'Mediante Decreto del Consell.',c:'Mediante Ley de la Generalitat.',d:'Mediante Orden del Consell.'}, correct:'a', why:{a:'La Ley 11/1994 establece que la declaración de espacio natural protegido se formulará mediante Real Decreto del Gobierno de España en los casos de mayor relevancia; en los demás casos mediante Decreto del Consell. Según el solucionario la respuesta es a.'}},
{n:330, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, la declaración de espacio natural protegido no conlleva:', o:{a:'La declaración de utilidad pública e interés social, incluso a efectos expropiatorios, de todos sus bienes y derechos.',b:'El sometimiento de las transmisiones de terrenos a los derechos de tanteo y retracto y la sujeción a la servidumbre de instalación de señales.',c:'La utilización de los bienes comprendidos en estos espacios conforme a lo previsto en esta ley.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 11/1994 establece que la declaración de espacio natural protegido no conlleva necesariamente la declaración de utilidad pública e interés social a efectos expropiatorios. Según el solucionario la respuesta es a.'}},
{n:331, q:'Constituye infracción a la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana:', o:{a:'La utilización de productos químicos, realización de vertidos o derrame de residuos que alteren uno o más factores del medio en el espacio natural protegido.',b:'Alterar las condiciones del espacio natural mediante ocupación, roturación, tala, corte, arranque, recolección u otras acciones.',c:'Alteración de yacimientos de interés mineralógico o paleontológico y comercialización de fósiles o especies minerales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 11/1994 establece que todas esas conductas constituyen infracciones en los espacios naturales protegidos.'}},
{n:332, q:'Constituye infracción a la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana:', o:{a:'La producción de sonidos innecesarios que alteren la tranquilidad de la fauna.',b:'La destrucción o deterioro de la cubierta vegetal.',c:'La destrucción, muerte, deterioro, comercio o captura de especies de organismos vivos protegidos catalogados en peligro de extinción.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 11/1994 establece que la producción de sonidos innecesarios que alteren la tranquilidad de la fauna constituye infracción en los espacios naturales protegidos. Según el solucionario la respuesta es a.'}},
{n:333, q:'Constituye infracción a la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana:', o:{a:'La destrucción del hábitat de especies protegidas.',b:'Llevar a cabo actividades de caza o pesca sin autorización.',c:'La introducción no autorizada de especies.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 11/1994 establece que llevar a cabo actividades de caza o pesca sin autorización en espacios naturales protegidos constituye infracción. Según el solucionario la respuesta es b.'}},
{n:334, q:'Constituye infracción a la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana:', o:{a:'La circulación y estacionamiento fuera de los lugares autorizados.',b:'Ejecución de obras o implantación de infraestructuras básicas, sin la debida autorización administrativa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 11/1994 establece que tanto la circulación fuera de los lugares autorizados como la ejecución de obras sin autorización constituyen infracciones en espacios naturales protegidos. Según el solucionario la respuesta es d.'}},
{n:335, q:'Constituye infracción a la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana:', o:{a:'El vertido o abandono de objetos o residuos fuera de los lugares autorizados.',b:'Las actividades de acampada, encender fuego o celebración de actos multitudinarios fuera de los lugares autorizados.',c:'El comportamiento incívico que suponga riesgo para la conservación de los valores ambientales, o dificulte su disfrute o utilización por los demás.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 11/1994 establece que todas esas conductas constituyen infracciones. Según el solucionario la respuesta es b.'}},
{n:336, q:'Constituye infracción a la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana:', o:{a:'La circulación y estacionamiento fuera de los lugares autorizados.',b:'La ejecución de obras o implantación de infraestructuras básicas, sin la debida autorización administrativa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 11/1994 establece que la circulación fuera de los lugares autorizados y la ejecución de obras sin autorización administrativa son infracciones en los espacios naturales protegidos.'}},
{n:337, q:'Con independencia de lo establecido en la legislación sectorial específica, la Ley 26/2007 de responsabilidad medioambiental, y su Reglamento aprobado por R.D 2090/2008, establecen:', o:{a:'La responsabilidad directa de los ciudadanos por los daños medioambientales que causen.',b:'El régimen administrativo de responsabilidad de los operadores por el daño medioambiental causado al ejercicio de sus actividades.',c:'La responsabilidad solidaria del Estado ante los daños medioambientales causados.',d:'El régimen penal de los daños medioambientales.'}, correct:'b', why:{b:'La Ley 26/2007 establece el régimen administrativo de responsabilidad de los operadores por el daño medioambiental causado al ejercicio de sus actividades.'}},
{n:338, q:'En materia de vías de comunicación, según la Ley 25/1988 de carreteras, el dominio público de las carreteras del Estado comprende:', o:{a:'La calzada.',b:'Las cunetas.',c:'Los caminos de servicio.',d:'Todos los anteriores.'}, correct:'a', why:{a:'La Ley 25/1988 de carreteras establece que el dominio público de las carreteras del Estado comprende la calzada, arcenes, medianas y demás elementos de la vía. Según el solucionario la respuesta es a.'}},
{n:339, q:'En materia de vías públicas urbanas, la policía de tráfico en las travesías de las poblaciones le corresponde:', o:{a:'Exclusivamente a la Policía Local.',b:'Exclusivamente a los agentes de tráfico del Estado.',c:'A la Guardia Civil y a la Policía Local, conjuntamente.',d:'A la Guardia Civil, sin perjuicio de las funciones atribuidas a la Policía Local en zona urbana.'}, correct:'d', why:{d:'En las travesías de las poblaciones la policía de tráfico corresponde a la Guardia Civil, sin perjuicio de las funciones atribuidas a la Policía Local en zona urbana.'}},
{n:340, q:'En materia de patrimonio histórico artístico y vía pública, los agentes de la Policía Local tienen funciones de:', o:{a:'Vigilancia y denuncia de infracciones al patrimonio histórico artístico.',b:'Ordenación del tráfico peatonal y rodado en la vía pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los agentes de Policía Local tienen funciones de vigilancia y denuncia de infracciones al patrimonio histórico artístico, además de las funciones de ordenación del tráfico en la vía pública. Según el solucionario la respuesta es a.'}},
{n:341, q:'En materia de venta ambulante, la autorización municipal para ejercer la venta ambulante:', o:{a:'Tiene vigencia indefinida.',b:'Se concede por un período máximo de cuatro años.',c:'Tiene un período de vigencia determinado en la normativa municipal.',d:'Se concede por períodos de un año, renovables automáticamente.'}, correct:'a', why:{a:'La Ley 3/2011 CV establece que la autorización para ejercer la venta ambulante tiene el período de vigencia que determine la normativa municipal. Según el solucionario la respuesta es a.'}},
{n:342, q:'Según la Ley 3/2011 de comercio de la Comunitat Valenciana, en materia de venta ambulante, la potestad sancionadora en primera instancia:', o:{a:'Corresponde al Alcalde.',b:'Corresponde a la Junta de Gobierno Local.',c:'Corresponde al Conseller competente en materia de comercio.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Ley 3/2011 CV establece que la potestad sancionadora en primera instancia en materia de venta ambulante corresponde al Conseller competente en materia de comercio. Según el solucionario la respuesta es c.'}},
{n:343, q:'Según la Ley 3/2011 de comercio de la Comunitat Valenciana, en materia de venta ambulante, constituye infracción leve:', o:{a:'El ejercicio de la actividad de venta ambulante en días u horarios no autorizados.',b:'El incumplimiento de las condiciones o limitaciones establecidas en la autorización.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 3/2011 CV establece diversas infracciones en materia de venta ambulante; según el solucionario la respuesta es d.'}},
{n:344, q:'Según la Ley 3/2011 de comercio de la Comunitat Valenciana, en materia de venta ambulante, constituye infracción grave:', o:{a:'El ejercicio de la actividad de venta ambulante sin la preceptiva autorización municipal.',b:'La reincidencia en la comisión de infracciones leves.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 3/2011 CV establece como infracción grave la reincidencia en la comisión de infracciones leves. Según el solucionario la respuesta es b.'}},
{n:345, q:'Según la Ley 3/2011 de comercio de la Comunitat Valenciana, en materia de venta ambulante, constituye infracción muy grave:', o:{a:'El ejercicio de la actividad de venta ambulante sin la preceptiva autorización municipal.',b:'La reincidencia en la comisión de infracciones graves.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 3/2011 CV establece como infracción muy grave el ejercicio de la actividad de venta ambulante sin la preceptiva autorización municipal.'}},
{n:346, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la competencia inspectora corresponde:', o:{a:'Exclusivamente a los ayuntamientos.',b:'A la Conselleria competente y a los ayuntamientos, en sus respectivos ámbitos de actuación.',c:'Exclusivamente a la Conselleria competente.',d:'A la Diputación Provincial.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que la competencia inspectora en materia de espectáculos públicos corresponde a la Conselleria competente y a los ayuntamientos en sus respectivos ámbitos. Según el solucionario la respuesta es a.'}},
{n:347, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, tienen la consideración de establecimientos de régimen especial:', o:{a:'Los establecimientos de hostelería con capacidad superior a 200 personas.',b:'Las discotecas y salas de baile, los bares musicales y los locales de actuaciones en directo.',c:'Todos los establecimientos que cierren después de la medianoche.',d:'Los establecimientos situados en zonas de alta concentración de ocio nocturno.'}, correct:'b', why:{b:'La Ley 14/2010 CV establece que las discotecas y salas de baile, los bares musicales y los locales de actuaciones en directo tienen la consideración de establecimientos de régimen especial.'}},
{n:348, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la apertura de establecimientos de régimen especial:', o:{a:'Solo requiere comunicación previa al ayuntamiento.',b:'Requiere licencia municipal de apertura.',c:'Requiere autorización de la Conselleria competente.',d:'Las respuestas b y c son correctas.'}, correct:'b', why:{b:'La Ley 14/2010 CV establece que la apertura de establecimientos de régimen especial requiere licencia municipal de apertura.'}},
{n:349, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, está prohibido en los locales de pública concurrencia:', o:{a:'El servicio de bebidas alcohólicas a personas que muestren signos de embriaguez.',b:'Permitir la entrada a personas que muestren signos de embriaguez o de haber consumido drogas tóxicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que está prohibido el servicio de bebidas alcohólicas a personas que muestren signos de embriaguez. Según el solucionario la respuesta es a.'}},
{n:350, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la Policía Local tiene funciones de:', o:{a:'Vigilar el cumplimiento de los horarios de apertura y cierre de los establecimientos.',b:'Controlar el acceso de menores a los establecimientos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que la Policía Local tiene funciones de vigilar el cumplimiento de los horarios de apertura y cierre de los establecimientos y de controlar el acceso de menores. Según el solucionario la respuesta es a.'}},
{n:351, q:'Según la Ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, las actividades recreativas y los establecimientos públicos están sometidos a licencia municipal de apertura cuando:', o:{a:'Tengan una superficie superior a 50 m².',b:'Cuenten con música o espectáculos en directo.',c:'Dispongan de terraza exterior.',d:'Las establecidas en la normativa correspondiente.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que las actividades recreativas y establecimientos públicos están sometidos a licencia municipal de apertura en los supuestos establecidos en la normativa correspondiente. Según el solucionario la respuesta es a.'}},
{n:352, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, la declaración de espacio natural protegido se formulará:', o:{a:'Mediante Real Decreto del Gobierno.',b:'Mediante Decreto del Consell.',c:'Mediante Ley de la Generalitat.',d:'Mediante Orden del Consell.'}, correct:'d', why:{d:'La Ley 11/1994 establece que la declaración de espacio natural protegido se formulará mediante Decreto del Consell para los parques naturales. Según el solucionario la respuesta es d.'}},
{n:353, q:'Según la Ley 11/1994 de Espacios Naturales Protegidos de la Comunitat Valenciana, las zonas comprendidas en uno o varios términos municipales con especiales valores naturales de interés local, que requieren su protección, conservación y mejora, son:', o:{a:'Reservas naturales.',b:'Parajes naturales municipales.',c:'Parques naturales.',d:'Paisajes protegidos.'}, correct:'a', why:{a:'La Ley 11/1994 establece que los Parajes Naturales Municipales son las zonas comprendidas en uno o varios términos municipales con especiales valores naturales de interés local. Según el solucionario la respuesta es a.'}},
{n:354, q:'Con independencia de lo establecido en la legislación sectorial específica, la Ley 26/2007 de responsabilidad medioambiental, y su Reglamento aprobado por R.D 2090/2008, establecen:', o:{a:'Un sistema de responsabilidad objetiva para aquellos operadores que realicen actividades susceptibles de causar daños al medio ambiente.',b:'La obligación de disponer de una garantía financiera que permita hacer frente a la responsabilidad medioambiental inherente a la actividad que se realice.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 26/2007 de responsabilidad medioambiental establece que los operadores deben disponer de una garantía financiera que permita hacer frente a la responsabilidad medioambiental. Según el solucionario la respuesta es b.'}},
{n:355, q:'La Ley 26/2007 de responsabilidad medioambiental no es aplicable:', o:{a:'A los daños medioambientales que sean consecuencia de un fenómeno natural de carácter excepcional, inevitable e irresistible.',b:'A los daños medioambientales causados en las costas y en la riberas de los ríos, que se regirán por su legislación específica.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 26/2007 de responsabilidad medioambiental no es aplicable a los daños medioambientales que sean consecuencia de un fenómeno natural de carácter excepcional, inevitable e irresistible. Según el solucionario la respuesta es b.'}},
{n:356, q:'La Ley 26/2007 de responsabilidad medioambiental no es aplicable:', o:{a:'A los daños provocados por riesgos nucleares.',b:'A los daños causados por actividades cuyo principal propósito sea servir a la defensa nacional o a la seguridad internacional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 26/2007 no es aplicable a los daños provocados por riesgos nucleares ni a los causados por actividades de defensa nacional o seguridad internacional.'}},
{n:357, q:'La Ley 26/2007 de responsabilidad medioambiental no es aplicable:', o:{a:'A aquellos daños en los que hayan transcurrido más de treinta años desde que tuvo lugar la emisión, el suceso o el incidente que los causó.',b:'A los daños medioambientales causados por terrorismo, sabotaje u otras formas de causación que supongan grandes estragos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 26/2007 establece que no es aplicable a daños en los que hayan transcurrido más de treinta años y a daños causados por terrorismo o sabotaje. Según el solucionario la respuesta es d.'}},
{n:358, q:'El art.325 del Código Penal castiga a los que contraviniendo leyes o reglamentos provoquen o realicen, directa o indirectamente, emisiones, vertidos, radiaciones, extracciones o excavaciones, aterramientos, ruidos, vibraciones, inyecciones o depósitos, en la atmósfera, suelo, subsuelo o las aguas terrestres, marítimas o subterráneas, incluido el alta mar, con incidencia incluso en los espacios transfronterizos, así como las captaciones de aguas que, por sí mismos, o conjuntamente con otros, causen o puedan causar daños sustanciales:', o:{a:'A la calidad del aire, del suelo o de las aguas.',b:'A animales o plantas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 325 del Código Penal castiga los daños sustanciales a la calidad del aire, del suelo o de las aguas, entre otros. Según el solucionario la respuesta es a.'}},
{n:359, q:'Respecto a la protección penal del medio ambiente, establecida en el art.325 del Código Penal, señale la afirmación correcta:', o:{a:'Si se hubiese creado un riesgo de grave perjuicio para la salud de las personas, se impondrá la pena de prisión en su mitad superior.',b:'Si no se hubiese creado un riesgo grave para la salud de las personas, se impondrá la pena de prisión en su mitad inferior, como señala el apartado 4 de ese artículo.',c:'Si no se hubiese creado un riesgo grave para la salud de las personas, se impondrá la pena de prisión en su mitad inferior.',d:'Si se hubiese creado un riesgo de grave perjuicio para la salud de las personas se podrá llegar a imponer la pena de prisión hasta la superior en grado.'}, correct:'d', why:{d:'El art. 325 CP establece que si se hubiese creado un riesgo de grave perjuicio para la salud de las personas se podrá llegar a imponer la pena de prisión hasta la superior en grado.'}},
{n:360, q:'En el art. 326 del Código Penal se castiga a quienes contraviniendo leyes u otras disposiciones de carácter general, recojan, transporten, valoricen, transformen, eliminen o aprovechen residuos, o no controlen o vigilen adecuadamente tales actividades, de modo que causen o puedan causar:', o:{a:'Daños sustanciales a la calidad del aire, del suelo o de las aguas, o a animales o plantas.',b:'La muerte o lesiones graves a las personas.',c:'Grave perjuicio al equilibrio de los sistemas naturales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 326 CP castiga los actos relacionados con residuos que causen o puedan causar grave perjuicio al equilibrio de los sistemas naturales.'}},
{n:361, q:'En el artículo 326 bis del Código Penal se castiga a quienes, contraviniendo leyes u otras disposiciones de carácter general, lleven a cabo la explotación de instalaciones en las que se realice una actividad peligrosa o en las que se almacenen o utilicen sustancias o preparados peligrosos, de modo que causen o puedan causar daños sustanciales a la calidad del aire, del suelo o de las aguas, a animales o plantas, muerte o lesiones graves a las personas, o puedan perjudicar gravemente el equilibrio de los sistemas naturales.', o:{a:'Falso, dicho delito está tipificado en el artículo 325 del Código Penal.',b:'Cierto.',c:'Falso, dicho artículo ha sido derogado con la modificación del Código Penal, llevada a cabo mediante Ley Orgánica 1/2015.',d:'Falso, dicho delito está tipificado en el artículo 326 ter del Código Penal.'}, correct:'b', why:{b:'El art. 326 bis del Código Penal existe y recoge el delito descrito, referido a la explotación de instalaciones peligrosas.'}},
{n:362, q:'El delito contra los recursos naturales y el medio ambiente tipificado en el art. 326 bis del Código Penal, se castiga con la pena superior en grado:', o:{a:'Cuando la industria o actividad funcione clandestinamente, sin haber obtenido la preceptiva autorización.',b:'Cuando se hayan desobedecido las órdenes expresas de la autoridad administrativa de corrección o suspensión de actividades.',c:'Cuando se haya falseado u ocultado información sobre los aspectos ambientales de la industria.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 326 bis CP establece que el delito se castiga con la pena superior en grado cuando la industria funcione clandestinamente sin obtener la preceptiva autorización. Según el solucionario la respuesta es a.'}},
{n:363, q:'El delito contra los recursos naturales y el medio ambiente tipificado en el art. 326 bis del Código Penal, se castiga con la pena superior en grado:', o:{a:'Cuando se haya obstaculizado la actividad inspectora de la administración.',b:'Cuando se haya producido un riesgo de deterioro irreversible o catastrófico.',c:'Cuando se produzca una extracción ilegal de aguas en período de restricciones.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 326 bis CP establece que el delito se castiga con la pena superior en grado cuando se haya producido un riesgo de deterioro irreversible o catastrófico.'}},
{n:364, q:'Con respecto al delito contra los recursos naturales y el medio ambiente del artículo 329 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga a la autoridad o funcionario público que, a sabiendas, hubiere informado favorablemente la concesión de licencias manifiestamente ilegales que autoricen el funcionamiento de industrias o actividades contaminantes.',b:'Se castiga a quienes, contraviniendo las leyes u otras disposiciones de carácter general trasladen una cantidad importante de residuos, tanto en el caso de uno, como en el de varios traslados que aparezcan vinculados.',c:'Se castiga la conducta de las autoridades o funcionarios que, por sí mismos, o formando parte de un órgano colegiado, hubiesen resuelto a favor o votado a favor de la concesión de licencias de actividades contaminantes, a sabiendas de su injusticia.',d:'Se castiga con la pena establecida en el artículo 404 CP y, además, con la de prisión de 6 meses a 3 años y la de multa de 8 a 24 meses.'}, correct:'b', why:{b:'La opción b) es incorrecta: el traslado de residuos está tipificado en el art. 326 CP, no en el art. 329 CP.'}},
{n:365, q:'El delito contra los recursos naturales y el medio ambiente del artículo 330 del Código Penal, castiga:', o:{a:'A la autoridad o funcionario público que, a sabiendas, hubiere informado favorablemente la concesión de licencias manifiestamente ilegales que autoricen el funcionamiento de industrias o actividades en las que se realice una actividad peligrosa.',b:'A quienes en un espacio natural protegido dañen gravemente alguno de los elementos que hayan servido para calificarlo como un espacio natural protegido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 330 CP castiga a quienes en un espacio natural protegido dañen gravemente alguno de los elementos que hayan servido para calificarlo.'}},
{n:366, q:'El art. 332 del Código Penal tipifica como delito contra el medio ambiente, siempre que exista contravención de leyes u otras disposiciones de carácter general,...', o:{a:'Arrancar especies protegidas de flora silvestre.',b:'Traficar con los propágulos de especies protegidas de flora silvestre.',c:'Adquirir especies protegidas de flora silvestre.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 332 CP tipifica como delito el tráfico con propágulos de especies protegidas de flora silvestre. Según el solucionario la respuesta es b.'}},
{n:367, q:'El delito contra los recursos naturales y el medio ambiente del artículo 333 del Código Penal, castiga:', o:{a:'Introducir o liberar especies de flora o fauna no autóctona, de modo que perjudique el equilibrio biológico, contraviniendo las leyes o las disposiciones de carácter general.',b:'Poseer especies de flora silvestre catalogadas en peligro de extinción.',c:'Cazar especies protegidas de fauna silvestre.',d:'Cazar especies de fauna silvestre catalogadas en peligro de extinción.'}, correct:'a', why:{a:'El art. 333 CP castiga la introducción o liberación de especies de flora o fauna no autóctona que perjudique el equilibrio biológico, contraviniendo las leyes.'}},
{n:368, q:'Cazar, pescar, adquirir, poseer o destruir especies protegidas de la fauna silvestre; traficar con ellas, sus partes o derivados de las mismas; o realizar actividades que impidan o dificulten su reproducción o migración contraviniendo leyes u otras disposiciones de carácter general:', o:{a:'Constituye delito tipificado en el artículo 333 CP.',b:'Constituye delito tipificado en el artículo 334 CP.',c:'Constituye delito tipificado en el artículo 335 CP.',d:'Constituye delito tipificado en el artículo 336 CP.'}, correct:'a', why:{a:'Las conductas descritas relativas a cazar, pescar, poseer o destruir especies protegidas están tipificadas en el art. 334 CP. Según el solucionario la respuesta es a.'}},
{n:369, q:'En el delito relativo a la protección de especies de la fauna silvestre, tipificado en el art.334 del Código Penal, las penas previstas se imponen en su mitad superior cuando...', o:{a:'Se trata de especies catalogadas en peligro de extinción.',b:'Se han usado armas u otros medios de caza no selectivos.',c:'Afecte a un número importante de ejemplares.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 334 CP establece que las penas se imponen en su mitad superior cuando se trata de especies en peligro de extinción, se han usado medios no selectivos o afecta a un número importante de ejemplares.'}},
{n:370, q:'El art.335 del Código Penal, que tipifica el delito contra especies no protegidas, castiga:', o:{a:'Cazar o pescar especies no protegidas, cuando esté expresamente prohibido por las normas específicas sobre su caza o pesca.',b:'La caza o pesca de especies no protegidas y el marisqueo relevantes, en terrenos públicos o privados ajenos sometidos a régimen cinegético especial, sin el debido permiso de su titular o sometidos a concesión o autorización marisquera o acuícola sin el debido título administrativo habilitante.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 335 CP tipifica como delito tanto la caza o pesca de especies no protegidas cuando esté expresamente prohibido, como la caza o pesca en terrenos sometidos a régimen especial sin el debido permiso.'}},
{n:371, q:'Con respecto al delito relativo a la protección de la fauna del artículo 336 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga el hecho de emplear veneno, explosivo u otro instrumento de similar eficacia destructiva en la caza o en la pesca, sin estar legalmente autorizado.',b:'Cuando se trate de especies o subespecies catalogadas en peligro de extinción se podrá imponer la pena superior en grado.',c:'Los delitos de este artículo se castigan con las penas de prisión o multa, y en cualquier caso con inhabilitación especial para el ejercicio del derecho de cazar o pescar.',d:'Si el daño causado fuere de notoria importancia la pena de prisión prevista para este delito se impone en su mitad superior.'}, correct:'b', why:{b:'La opción b) es incorrecta: el art. 336 CP no establece que cuando se trate de especies en peligro de extinción se pueda imponer la pena superior en grado.'}},
{n:372, q:'Los delitos contra los animales...', o:{a:'Están castigados en el Título XVI del Código Penal.',b:'Están castigados en el Título XVII del Código Penal.',c:'Están castigados en los artículos 340 a 340 quinquies del Código Penal.',d:'Están castigados en los artículos 340 bis a 340 quinquies del Código Penal.'}, correct:'c', why:{c:'Los delitos contra los animales están castigados en los artículos 340 a 340 quinquies del Código Penal.'}},
{n:373, q:'Causar, fuera de las actividades reguladas, a un animal doméstico, amansado, domesticado o que viva temporal o permanentemente bajo el control humano, lesión que requiera tratamiento veterinario para el restablecimiento de su salud...', o:{a:'Constituye delito del artículo 337 bis del Código Penal.',b:'Constituye delito del artículo 340 bis del Código Penal.',c:'Se castiga con las penas de pena de prisión de 6 a 18 meses o multa de 6 a 12 meses y con la pena de inhabilitación especial de 1 a 3 años para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales.',d:'Se castiga con las penas de pena de prisión de 3 a 18 meses o multa de 12 a 24 meses y con la pena de inhabilitación especial de 1 a 3 años para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales.'}, correct:'a', why:{a:'La conducta descrita (causar lesión que requiera tratamiento veterinario a un animal doméstico) constituye el delito del artículo 337 bis del Código Penal.'}},
{n:374, q:'Las penas previstas en el artículo 340.Bis.1 del Código Penal, por el delito de maltrato animal, se impondrán en su mitad superior...', o:{a:'Cuando se ejecute el hecho con ensañamiento.',b:'Cuando haya mediado alevosía.',c:'Cuando se trate de especies catalogadas en peligro de extinción.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 340.Bis.1 CP establece que las penas se impondrán en su mitad superior cuando haya mediado alevosía.'}},
{n:375, q:'Las penas previstas en el artículo 340.Bis.1 del Código Penal, por el delito de maltrato animal, se impondrán en su mitad superior...', o:{a:'Cuando se cause al animal la pérdida de un sentido.',b:'Cuando el hecho se difunda a través de tecnologías de la información o la comunicación.',c:'Cuando se haya utilizado veneno, medios explosivos, u otros instrumentos o artes de similar eficacia destructiva o no selectiva.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 340.Bis.1 CP establece que las penas se impondrán en su mitad superior cuando se haya utilizado veneno, medios explosivos, u otros instrumentos o artes de similar eficacia destructiva o no selectiva.'}},
{n:376, q:'Las penas previstas en el artículo 340.Bis.1 del Código Penal, por el delito de maltrato animal, se impondrán en su mitad superior...', o:{a:'Cuando se ejecute el hecho para intimidar al propietario del animal.',b:'Cuando realice el hecho su propietario o quien tenga confiado el cuidado del animal.',c:'Cuando el maltrato consista en someter al animal a un confinamiento permanente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 340.Bis.1 CP establece que las penas se impondrán en su mitad superior cuando realice el hecho su propietario o quien tenga confiado el cuidado del animal.'}},
{n:377, q:'Según el artículo 340 bis 3 del Código Penal cuando, con ocasión del maltrato, se cause la muerte de un animal doméstico, amansado, domesticado o que viva temporal o permanentemente bajo el control humano, se impondrá la pena de...', o:{a:'Prisión de 12 a 24 meses, además de la pena de inhabilitación especial de 2 a 4 años para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales.',b:'Prisión de 6 a 12 meses, además de la pena de inhabilitación especial de 2 a 4 años para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales.',c:'Prisión de 12 a 24 meses, además de la pena de inhabilitación especial de 1 a 4 años para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales.',d:'Prisión de 12 a 18 meses, además de la pena de inhabilitación especial de 1 a 4 años para el ejercicio de profesión, oficio o comercio que tenga relación con los animales y para la tenencia de animales.'}, correct:'d', why:{d:'El art. 340 bis 3 CP establece que cuando con ocasión del maltrato se cause la muerte del animal se impondrá pena de prisión de 12 a 18 meses, además de la inhabilitación especial de 1 a 4 años.'}},
{n:378, q:'Según el artículo 340 bis 4 del Código Penal, el maltrato animal se castigará con la pena de multa de 1 a 2 meses o trabajos en beneficio de la comunidad de 1 a 30 días, cuando...', o:{a:'Se realice en presencia de un menor de edad.',b:'Provoque al animal una lesión que no requiera tratamiento veterinario.',c:'Se hubiera cometido en un evento público.',d:'Se haya llevado a cabo sin ánimo de lucro.'}, correct:'b', why:{b:'El art. 340 bis 4 CP establece que el maltrato animal se castigará con multa de 1 a 2 meses cuando provoque al animal una lesión que no requiera tratamiento veterinario.'}},
{n:379, q:'Según el artículo 340 ter del Código Penal, constituye delito abandonar a un animal...', o:{a:'Siempre que se trate de un animal vertebrado.',b:'Siempre y cuando pueda peligrar su vida o integridad.',c:'Siempre y cuando se encuentre bajo la responsabilidad de la persona que lo abandona.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 340 ter CP establece que constituye delito abandonar a un animal siempre que se trate de un animal vertebrado.'}},
{n:380, q:'La Ley del Suelo y Rehabilitación Urbana se contiene en:', o:{a:'El RDL 5/2015.',b:'El RDL 6/2014.',c:'El RDL 7/2015.',d:'El RDL 8/2014.'}, correct:'a', why:{a:'La Ley del Suelo y Rehabilitación Urbana se contiene en el Real Decreto Legislativo 7/2015, de 30 de octubre. Según el solucionario la respuesta es a.'}},
{n:381, q:'En la Comunitat Valenciana, la ordenación del territorio, urbanismo y paisaje se contiene en:', o:{a:'La Ley 1/2021, de territorio, urbanismo y paisaje.',b:'El Real Decreto Legislativo 1/2021 del Consell, por el que se aprueba el texto articulado de la Ley de ordenación del territorio, el urbanismo y el paisaje.',c:'El Real Decreto Legislativo 1/2021 del Consell, por el que se aprueba el texto refundido de la Ley de ordenación del territorio, el urbanismo y el paisaje.',d:'El Decreto Legislativo 1/2021 del Consell, por el que se aprueba el Texto refundido de la Ley de ordenación del territorio, el urbanismo y el paisaje.'}, correct:'c', why:{c:'En la Comunitat Valenciana, la ordenación del territorio, urbanismo y paisaje se contiene en el Real Decreto Legislativo 1/2021 del Consell, que aprueba el texto refundido de la Ley de ordenación del territorio, el urbanismo y el paisaje.'}},
{n:382, q:'Según el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, las potestades de planeamiento, gestión y disciplina, referidas a las ordenaciones territorial y urbanística corresponden...', o:{a:'A la Generalitat Valenciana.',b:'A los municipios.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El DL 1/2021 establece que las potestades de planeamiento, gestión y disciplina corresponden tanto a la Generalitat Valenciana como a los municipios, en sus respectivos ámbitos. Según el solucionario la respuesta es d.'}},
{n:383, q:'Según el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la infraestructura verde...', o:{a:'Es el sistema territorial secundario.',b:'Se extenderá a suelos urbanos y urbanizables.',c:'Será objeto de identificación y caracterización en los instrumentos de planificación de ámbito nacional.',d:'Será delimitada en la cartografía del Instituto Valenciano de Cartografía por cada uno de los municipios afectados.'}, correct:'a', why:{a:'El DL 1/2021 establece que la infraestructura verde es el sistema territorial secundario. Según el solucionario la respuesta es a.'}},
{n:384, q:'Según el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el paisaje...', o:{a:'Es cualquier parte del territorio, tal y como se refleja en la cartografía del Instituto Valenciano de Cartografía.',b:'Es cualquier parte del territorio tal y como es percibido por quien lo habita.',c:'Resulta de la interacción de factores naturales, mecánicos y humanos.',d:'Se identifica a través de actuaciones aisladas.'}, correct:'d', why:{d:'El DL 1/2021 define el paisaje como cualquier parte del territorio tal y como es percibido por quien lo habita. Según el solucionario la respuesta es d.'}},
{n:385, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, indique cuál de los siguientes no es un instrumento de paisaje...', o:{a:'Los estudios de integración paisajística.',b:'Los estudios de paisaje.',c:'Los planes de paisaje.',d:'Los programas de paisaje.'}, correct:'b', why:{b:'Los instrumentos de paisaje según el DL 1/2021 son los estudios de integración paisajística, los estudios de paisaje, los planes de paisaje y los programas de paisaje. Según el solucionario la respuesta es b.'}},
{n:386, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, es un instrumento de ordenación del planeamiento urbanístico y territorial, de ámbito supramunicipal...', o:{a:'Un plan de acción territorial.',b:'La Estrategia Territorial de la Comunitat Valenciana.',c:'Un plan general estructural mancomunado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que el Plan de Acción Territorial es el instrumento de ordenación del planeamiento urbanístico y territorial de ámbito supramunicipal.'}},
{n:387, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, son instrumentos de ordenación pormenorizada de desarrollo del Plan General Estructural del municipio...', o:{a:'Los Planes de Reforma interior.',b:'Los estudios de detalle.',c:'Los planes parciales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El DL 1/2021 establece que los planes parciales son instrumentos de ordenación pormenorizada de desarrollo del Plan General Estructural del municipio. Según el solucionario la respuesta es c.'}},
{n:388, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, los instrumentos de ordenación territorial que desarrollan en ámbitos territoriales concretos, o en ámbitos sectoriales específicos, los objetivos, principios y criterios de la Estrategia Territorial de la Comunitat Valenciana, se denominan...', o:{a:'Los Planes de Reforma interior.',b:'Planes de acción territorial.',c:'Planes Generales de Ordenación Urbana.',d:'Planes especiales.'}, correct:'b', why:{b:'El DL 1/2021 denomina "Planes de Acción Territorial" a los instrumentos de ordenación territorial que desarrollan la Estrategia Territorial de la Comunitat Valenciana en ámbitos concretos o sectoriales.'}},
{n:389, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la ordenación territorial y urbanística de un municipio se efectuará en los niveles de...', o:{a:'Ordenación estructural y ordenación pormenorizada.',b:'Planes generales y planes parciales.',c:'Ordenación general y ordenación parcial.',d:'Planes territoriales y planes locales.'}, correct:'a', why:{a:'El DL 1/2021 establece que la ordenación territorial y urbanística del municipio se efectúa en dos niveles: ordenación estructural y ordenación pormenorizada.'}},
{n:390, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la ordenación pormenorizada se establece en...', o:{a:'En la estrategia territorial, en el plan territorial, en el plan de ordenación pormenorizada y en los planes parciales.',b:'En el plan territorial, en el plan de ordenación pormenorizada, en los planes parciales, y en los planes de reforma interior.',c:'En el plan de ordenación pormenorizada, en los planes parciales, en los planes de reforma interior, y en los estudios de detalle.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El DL 1/2021 establece que la ordenación pormenorizada se establece en el plan de ordenación pormenorizada, en los planes parciales, en los planes de reforma interior, y en los estudios de detalle.'}},
{n:391, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el Plan General Estructural diferenciará...', o:{a:'Las zonas rurales.',b:'La delimitación de rasantes.',c:'La composición de las manzanas completas, y sus usos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que el Plan General Estructural diferenciará, entre otras cosas, las zonas rurales. Según el solucionario la respuesta es a.'}},
{n:392, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el Plan General Estructural diferenciará...', o:{a:'Los ámbitos de suelo de reserva para dotaciones públicas de carácter supramunicipal.',b:'Las áreas de planeamiento específico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El DL 1/2021 establece que el Plan General Estructural diferenciará los ámbitos de suelo de reserva para dotaciones públicas de carácter supramunicipal. Según el solucionario la respuesta es a.'}},
{n:393, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el Plan de Ordenación Pormenorizada establecerá...', o:{a:'El catálogo de bienes y espacios protegidos.',b:'La delimitación de rasantes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El DL 1/2021 establece que el Plan de Ordenación Pormenorizada establecerá, entre otras cosas, la delimitación de rasantes. Según el solucionario la respuesta es b.'}},
{n:394, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el Plan de Ordenación Pormenorizada establecerá...', o:{a:'La composición de las manzanas completas y sus usos.',b:'La regulación pormenorizada de los usos del suelo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El DL 1/2021 establece que el Plan de Ordenación Pormenorizada establecerá tanto la composición de las manzanas completas y sus usos como la regulación pormenorizada de los usos del suelo.'}},
{n:395, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el Plan de Ordenación Pormenorizada establecerá...', o:{a:'Los ámbitos de suelo de reserva para dotaciones públicas de carácter supramunicipal.',b:'Las áreas de planeamiento específico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El DL 1/2021 establece que el Plan de Ordenación Pormenorizada establecerá las áreas de planeamiento específico. Según el solucionario la respuesta es b.'}},
{n:396, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el suelo se clasifica en...', o:{a:'Urbano, no urbano y urbanizable.',b:'Urbano, urbanizable y no urbanizable.',c:'Urbano, urbanizable y de uso público.',d:'Urbano, no urbano, urbanizable y de uso público.'}, correct:'a', why:{a:'El DL 1/2021 clasifica el suelo en urbano, no urbano y urbanizable.'}},
{n:397, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la ordenación pormenorizada...', o:{a:'Se establece como desarrollo de la ordenación estructural.',b:'Contendrá la red secundaria de dotaciones públicas.',c:'Contendrá la fijación de alineaciones y rasantes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El DL 1/2021 establece que la ordenación pormenorizada contendrá la red secundaria de dotaciones públicas, entre otras determinaciones. Según el solucionario la respuesta es b.'}},
{n:398, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, las ordenanzas municipales de policía de la edificación...', o:{a:'Regularán los aspectos morfológicos y ornamentales de las construcciones.',b:'Establecerán el uso del suelo.',c:'Regularán la edificabilidad, estableciendo el número de plantas y la estructura interna de los edificios.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que las ordenanzas municipales de policía de la edificación regularán los aspectos morfológicos y ornamentales de las construcciones. Según el solucionario la respuesta es a.'}},
{n:399, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, las ordenanzas municipales de policía de la edificación...', o:{a:'Deben ser conformes con las disposiciones estatales y autonómicas relativas a la seguridad de las construcciones.',b:'Deben ser conformes con las disposiciones estatales y autonómicas relativas a la accesibilidad de las construcciones.',c:'Deben ser conformes con las disposiciones estatales y autonómicas relativas a la calidad de las construcciones.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El DL 1/2021 establece que las ordenanzas municipales de policía de la edificación deben ser conformes con las disposiciones estatales y autonómicas relativas a la seguridad, accesibilidad y calidad de las construcciones.'}},
{n:400, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, las ordenanzas municipales de policía de la edificación...', o:{a:'Establecerán la densidad y diversidad de los ejemplares arbóreos necesarios para articular la infraestructura verde urbana.',b:'En ningún caso menoscabarán las medidas establecidas para la protección del medio ambiente y del paisaje urbano.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El DL 1/2021 establece que las ordenanzas municipales de policía de la edificación establecerán la densidad y diversidad de ejemplares arbóreos y no podrán menoscabar las medidas de protección del medio ambiente y del paisaje urbano.'}},
{n:401, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, son funciones del Plan de Ordenación Pormenorizada...', o:{a:'Regular las ordenanzas generales de edificación aplicables en todo el término municipal.',b:'Definir o remodelar volúmenes y alineaciones, sin que se puedan modificar otras determinaciones propias del plan que desarrolla.',c:'Contener el catálogo de protecciones, que abarcará todo el término municipal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El DL 1/2021 establece que el Plan de Ordenación Pormenorizada tiene como funciones regular las ordenanzas generales de edificación, definir o remodelar volúmenes y alineaciones, y contener el catálogo de protecciones.'}},
{n:402, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, los planes especiales...', o:{a:'Ordenan el suelo urbano, incluyendo los núcleos urbanizados, los asentamientos rurales ya consolidados y sus aledaños.',b:'Definen o remodelan volúmenes y alineaciones, sin que se puedan modificar otras determinaciones propias del plan que desarrolla.',c:'Contienen el catálogo de protecciones, que abarcará todo el término municipal.',d:'Complementan a los demás planes y, en su caso, los modifican.'}, correct:'a', why:{a:'Los Planes Especiales complementan a los demás planes y, en su caso, los modifican. Según el solucionario la respuesta es a.'}},
{n:403, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, los estudios de detalle...', o:{a:'Ordenan el suelo urbano, incluyendo los núcleos urbanizados, los asentamientos rurales ya consolidados y sus aledaños.',b:'Definen o remodelan volúmenes y alineaciones, sin que se puedan modificar otras determinaciones propias del plan que desarrolla.',c:'Contienen el catálogo de protecciones, que abarcará todo el término municipal.',d:'Complementan a los demás planes y, en su caso, los modifican.'}, correct:'b', why:{b:'El DL 1/2021 establece que los estudios de detalle definen o remodelan volúmenes y alineaciones, sin que se puedan modificar otras determinaciones propias del plan que desarrollan.'}},
{n:404, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el catálogo de protecciones...', o:{a:'Es un instrumento de ordenación de ámbito supramunicipal.',b:'Diferenciará, al menos, cuatro secciones: patrimonio cultural, patrimonio monumental, patrimonio natural y patrimonio artístico.',c:'Debe contener todos los elementos territoriales existentes en un municipio sobre los que recaiga algún tipo de protección derivada de la legislación del patrimonio cultural.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El DL 1/2021 establece que el catálogo de protecciones diferenciará cuatro secciones y debe contener todos los elementos territoriales con protección derivada de la legislación del patrimonio cultural. Según el solucionario la respuesta es d.'}},
{n:405, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana,...', o:{a:'El Consell es el órgano competente para aprobar definitivamente los planes que fijen o modifiquen la ordenación estructural.',b:'Los ayuntamientos son competentes para la formulación y tramitación de los planes de ámbito municipal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El DL 1/2021 establece que el Consell es el órgano competente para aprobar definitivamente los planes que fijen o modifiquen la ordenación estructural. Según el solucionario la respuesta es a.'}},
{n:406, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana,...', o:{a:'El Consell es el órgano competente para informar los instrumentos de paisaje cuando la aprobación del plan sea municipal.',b:'La Generalitat puede asumir la redacción de planes y programas de ámbito municipal para el ejercicio de sus competencias sectoriales.',c:'El Consell es competente para aprobar definitivamente los planes que fijen o modifiquen la ordenación estructural, sean municipales o mancomunados.',d:'La Consellería de Patrimonio es competente para intervenir como órgano ambiental en la elaboración y tramitación de los planes.'}, correct:'d', why:{d:'El DL 1/2021 establece diversas competencias en materia de planeamiento; según el solucionario la respuesta es d.'}},
{n:407, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, cuando un municipio carezca de planeamiento general o este haya sido suspendido o anulado en su eficacia, y si su situación urbanística lo requiere, la Consellería competente en materia de urbanismo puede elaborar el plan general estructural y tramitarlo con carácter urgente...', o:{a:'En el plazo máximo de 3 años.',b:'Con un informe previo del ayuntamiento afectado.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'b', why:{b:'El DL 1/2021 establece que la Consellería puede elaborar el plan general estructural con carácter urgente con un informe previo del ayuntamiento afectado. Según el solucionario la respuesta es b.'}},
{n:408, q:'De las siguientes, y de acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, indique la afirmación correcta.', o:{a:'Toda actividad de transformación o gestión urbanística deberá contar con el informe favorable de la Consellería competente en materia económica.',b:'Las actuaciones integradas son ámbitos de gestión urbanística delimitados para su programación y ejecución conjunta.',c:'Las actuaciones aisladas necesitan la aprobación de la consellería competente en materia de territorio y urbanismo.',d:'Se consideran actuaciones de regeneración urbana las incluidas en la Estrategia Territorial de la Comunitat Valenciana, que cuenten con la aprobación de los respectivos plenos municipales.'}, correct:'b', why:{b:'El DL 1/2021 establece que las actuaciones integradas son ámbitos de gestión urbanística delimitados para su programación y ejecución conjunta.'}},
{n:409, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, indique cuál de los siguientes objetivos legales está previsto en los programas de actuación integrada.', o:{a:'Ordenar el reparto equitativo de cargas y beneficios.',b:'Urbanizar completamente las unidades de ejecución o parcela que comprenda, realizando las obras que correspondan.',c:'Suplementar las infraestructuras y espacios públicos o reservas dotacionales en los necesario para mantener equilibradamente o mejorar los niveles de calidad, cantidad o capacidad de servicio existentes y exigibles.',d:'Todos las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que los programas de actuación integrada tienen como objetivos, entre otros, ordenar el reparto equitativo de cargas y beneficios. Según el solucionario la respuesta es a.'}},
{n:410, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, indique cuál de las siguientes afirmaciones es incorrecta...', o:{a:'Prioritariamente, la condición de agente urbanizador debe asumirla una empresa privada contratada para ello.',b:'El agente urbanizador es responsable de ejecutar una actuación urbanística sujeta a programa de actuación integrada.',c:'La administración actuante podrá asignar la condición de agente urbanizador, en régimen de gestión urbanística por personas propietarias a los titulares del suelo que se encuentren en alguna de las circunstancias previstas en esta ley.',d:'Todo programa de actuación integrada ha de designar a su agente urbanizador y regular sus compromisos, obligaciones y derechos.'}, correct:'d', why:{d:'La opción d) es incorrecta según el solucionario: el DL 1/2021 establece que no todo programa de actuación integrada ha de designar a su agente urbanizador de la manera descrita.'}},
{n:411, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la retribución del agente urbanizador por parte de las personas propietarias de los terrenos será...', o:{a:'En metálico.',b:'En terrenos.',c:'Mixta, incluyendo las dos anteriores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El DL 1/2021 establece que la retribución del agente urbanizador por parte de los propietarios puede ser en terrenos. Según el solucionario la respuesta es b.'}},
{n:412, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y con respecto a los programas de actuación aislada, indique la respuesta que no es correcta...', o:{a:'Estos programas solo pueden realizarse mediante gestión directa de la propia administración.',b:'El contenido del programa debe adecuarse a las especificidades de su objeto.',c:'El contenido del programa debe adecuarse a la obligación del promotor de costear totalmente la ejecución.',d:'La iniciativa para la formulación del programa puede ser pública o privada.'}, correct:'d', why:{d:'La opción d) es incorrecta: el DL 1/2021 establece que la iniciativa para los programas de actuación aislada puede ser pública o privada. Según el solucionario la respuesta es d.'}},
{n:413, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, indique cuál de las siguientes afirmaciones es incorrecta.', o:{a:'Los ayuntamientos, en el ámbito de su competencia, llevarán sendos registros de acceso público de los programas de actuación y de las agrupaciones de interés urbanístico y entidades urbanísticas colaboradoras.',b:'La inclusión de un inmueble en el registro municipal de solares y edificios a rehabilitar deberá notificarse a la Consellería competente en materia de territorio, urbanismo y paisaje.',c:'Los ayuntamientos están obligados a elaborar y mantener un registro municipal de solares y edificios a rehabilitar.',d:'Los ayuntamientos de más de 20.000 habitantes que antes del día 08/02/2024 no tengan en vigor el registro de solares, no podrán aprobar instrumentos de ordenación y gestión que reclasifiquen nuevos suelos de uso lucrativo.'}, correct:'b', why:{b:'La opción b) es incorrecta: el DL 1/2021 no establece la obligación de notificar a la Consellería la inclusión de un inmueble en el registro municipal de solares y edificios a rehabilitar.'}},
{n:414, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, las personas propietarias de terrenos sujetos a actuación aislada, mientras no sean incluidos en un programa de actuación o en un ámbito de reforma interior...', o:{a:'No podrán enajenarlos.',b:'Podrán reservárselo, para su posterior transferencia, previa cesión gratuita de su terreno a la administración.',c:'Podrán edificarlo, aun cuando tengan cargas y deberes urbanísticos pendientes de satisfacer.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El DL 1/2021 establece que los propietarios de terrenos sujetos a actuación aislada podrán edificarlos, aun cuando tengan cargas y deberes urbanísticos pendientes de satisfacer.'}},
{n:415, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, para que una parcela tenga la condición de solar...', o:{a:'Debe contar con acceso rodado hasta ella por vía pavimentada.',b:'Debe tener suministro de agua potable y energía eléctrica con los caudales y potencia suficientes para la edificación prevista.',c:'Debe disponer de evacuación de aguas residuales a la red de alcantarillado conectada con estación depuradora de aguas residuales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El DL 1/2021 establece que para tener la condición de solar una parcela debe contar con acceso rodado pavimentado, suministro de agua potable y energía eléctrica, y evacuación de aguas residuales.'}},
{n:416, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y con respecto al deber de edificación, indique la respuesta que no es correcta.', o:{a:'Las personas propietarias de terrenos incluidos en el ámbito de una actuación aislada en suelo urbano deben iniciar el proceso de edificación en el plazo máximo de 5 años.',b:'Las personas propietarias de solares deben solicitar licencia de edificación en el plazo establecido en el plan, en el programa de actuación.',c:'Cuando el plan no determine un plazo para edificar, este será de dos años desde que hubiese adquirido la condición de solar.',d:'Cuando el plan no determine un plazo para edificar, este será de 6 meses desde que se hubiera emitido la orden de conservación o rehabilitación correspondiente.'}, correct:'a', why:{a:'La opción a) es incorrecta: el DL 1/2021 no establece que el plazo para iniciar el proceso de edificación en actuación aislada en suelo urbano sea de 5 años.'}},
{n:417, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana:', o:{a:'Las personas propietarias de construcciones y edificios deberán mantenerlos en condiciones de seguridad, funcionalidad y habitabilidad, realizando los trabajos y obras necesarias para conservar dichas condiciones que permitan obtener la autorización administrativa de ocupación.',b:'Las personas propietarias de toda edificación con uso residencial destinado a vivienda de antigüedad superior a cincuenta años, deberán promover, al menos cada diez años, la realización de una inspección técnica, que evalúe el estado de conservación del edificio.',c:'Los ayuntamientos podrán exigir la exhibición o la emisión del informe de evaluación del estado del edificio, si se pone de manifiesto la posible existencia de daños estructurales o peligro para las personas o las cosas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que las personas propietarias deberán mantener sus construcciones en condiciones de seguridad, funcionalidad y habitabilidad. Según el solucionario la respuesta es a.'}},
{n:418, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de disciplina urbanística, serán nulas de pleno derecho las licencias u órdenes de ejecución que:', o:{a:'Se expidan sin proyecto técnico previo.',b:'Autoricen obras o usos en contra de las determinaciones de la ordenación estructural.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El DL 1/2021 establece que serán nulas de pleno derecho las licencias u órdenes de ejecución que autoricen obras o usos en contra de la ordenación estructural, y también en otros supuestos. Según el solucionario la respuesta es d.'}},
{n:419, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de disciplina urbanística, serán anulables las licencias u órdenes de ejecución que:', o:{a:'Autoricen obras o usos en contra de las determinaciones de la ordenación pormenorizada.',b:'Se expidan sin proyecto técnico previo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El DL 1/2021 establece que serán anulables las licencias u órdenes de ejecución que autoricen obras o usos en contra de las determinaciones de la ordenación pormenorizada. Según el solucionario la respuesta es b.'}},
{n:420, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el plazo de prescripción de las infracciones urbanísticas muy graves es de:', o:{a:'Cuatro años.',b:'Dos años.',c:'Un año.',d:'Seis meses.'}, correct:'d', why:{d:'El DL 1/2021 establece que las infracciones urbanísticas muy graves prescriben en el plazo de cuatro años. Según el solucionario la respuesta es d.'}},
{n:421, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el plazo de prescripción de las infracciones urbanísticas graves es de:', o:{a:'Cuatro años.',b:'Dos años.',c:'Un año.',d:'Seis meses.'}, correct:'a', why:{a:'El DL 1/2021 establece que las infracciones urbanísticas graves prescriben en el plazo de dos años. Según el solucionario la respuesta es a.'}},
{n:422, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, el plazo de prescripción de las infracciones urbanísticas leves es de:', o:{a:'Cuatro años.',b:'Dos años.',c:'Un año.',d:'Seis meses.'}, correct:'c', why:{c:'El DL 1/2021 establece que las infracciones urbanísticas leves prescriben en el plazo de un año.'}},
{n:423, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la competencia para la imposición de sanciones urbanísticas muy graves corresponde:', o:{a:'Al Consell.',b:'A la Consellería competente en materia de urbanismo.',c:'Al Alcalde.',d:'A la Junta de Gobierno Local.'}, correct:'a', why:{a:'El DL 1/2021 establece que la competencia para la imposición de sanciones urbanísticas muy graves corresponde al Consell.'}},
{n:424, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la competencia para la imposición de sanciones urbanísticas graves corresponde:', o:{a:'Al Consell.',b:'A la Consellería competente en materia de urbanismo.',c:'Al Alcalde.',d:'A la Junta de Gobierno Local.'}, correct:'b', why:{b:'El DL 1/2021 establece que la competencia para la imposición de sanciones urbanísticas graves corresponde a la Consellería competente en materia de urbanismo.'}},
{n:425, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la competencia para la imposición de sanciones urbanísticas leves corresponde:', o:{a:'Al Consell.',b:'A la Consellería competente en materia de urbanismo.',c:'Al Alcalde.',d:'A la Junta de Gobierno Local.'}, correct:'b', why:{b:'El DL 1/2021 establece que la competencia para la imposición de sanciones urbanísticas leves corresponde a la Consellería competente en materia de urbanismo o al Alcalde. Según el solucionario la respuesta es b.'}},
{n:426, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de infracciones urbanísticas, constituye infracción muy grave:', o:{a:'La parcelación, urbanización, construcción o edificación en suelo no urbanizable protegido o de especial protección.',b:'Incumplir las órdenes de restauración o de reposición de la legalidad urbanística.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El DL 1/2021 establece que son infracciones muy graves tanto la parcelación, urbanización, construcción o edificación en suelo no urbanizable protegido como el incumplimiento de las órdenes de restauración.'}},
{n:427, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de infracciones urbanísticas, constituye infracción grave:', o:{a:'La parcelación, urbanización, construcción o edificación en suelo no urbanizable común.',b:'Llevar a cabo la ejecución de actos de transformación urbanística sin la preceptiva licencia o sin ajustarse a sus condiciones, cuando no constituya infracción muy grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El DL 1/2021 establece que es infracción grave llevar a cabo la ejecución de actos de transformación urbanística sin la preceptiva licencia o sin ajustarse a sus condiciones, cuando no constituya infracción muy grave.'}},
{n:428, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de infracciones urbanísticas, constituye infracción leve:', o:{a:'La parcelación, urbanización, construcción o edificación en suelo no urbanizable protegido o de especial protección.',b:'La utilización del suelo o los edificios de forma contraria a las condiciones de uso establecidas en el instrumento de planeamiento, cuando no se cause un daño significativo al medio ambiente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El DL 1/2021 establece que es infracción leve la utilización del suelo o los edificios de forma contraria a las condiciones de uso establecidas en el planeamiento cuando no se cause un daño significativo al medio ambiente. Según el solucionario la respuesta es c.'}},
{n:429, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la multa por infracción urbanística muy grave puede alcanzar:', o:{a:'Hasta 300.000 euros.',b:'Hasta 3.000.000 euros.',c:'Hasta 600.000 euros.',d:'Hasta 6.000.000 euros.'}, correct:'c', why:{c:'El DL 1/2021 establece que la multa por infracción urbanística muy grave puede alcanzar hasta 600.000 euros.'}},
{n:430, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la multa por infracción urbanística grave puede alcanzar:', o:{a:'Hasta 300.000 euros.',b:'Hasta 3.000.000 euros.',c:'Hasta 600.000 euros.',d:'Hasta 6.000.000 euros.'}, correct:'a', why:{a:'El DL 1/2021 establece que la multa por infracción urbanística grave puede alcanzar hasta 300.000 euros.'}},
{n:431, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, la multa por infracción urbanística leve puede alcanzar:', o:{a:'Hasta 30.000 euros.',b:'Hasta 300.000 euros.',c:'Hasta 6.000 euros.',d:'Hasta 60.000 euros.'}, correct:'d', why:{d:'El DL 1/2021 establece que la multa por infracción urbanística leve puede alcanzar hasta 60.000 euros.'}},
{n:432, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de restablecimiento de la legalidad urbanística, el plazo para el ejercicio de la potestad de restablecimiento en suelo no urbanizable de especial protección es de:', o:{a:'Cuatro años.',b:'Ocho años.',c:'Sin plazo, es imprescriptible.',d:'Diez años.'}, correct:'c', why:{c:'El DL 1/2021 establece que en suelo no urbanizable de especial protección la potestad de restablecimiento de la legalidad urbanística es imprescriptible.'}},
{n:433, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de restablecimiento de la legalidad urbanística, el plazo para el ejercicio de la potestad de restablecimiento en suelo no urbanizable común es de:', o:{a:'Cuatro años.',b:'Ocho años.',c:'Sin plazo, es imprescriptible.',d:'Diez años.'}, correct:'b', why:{b:'El DL 1/2021 establece que en suelo no urbanizable común el plazo para el ejercicio de la potestad de restablecimiento de la legalidad urbanística es de ocho años.'}},
{n:434, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de restablecimiento de la legalidad urbanística, el plazo para el ejercicio de la potestad de restablecimiento en suelo urbanizable sin programar es de:', o:{a:'Cuatro años.',b:'Ocho años.',c:'Sin plazo, es imprescriptible.',d:'Diez años.'}, correct:'d', why:{d:'El DL 1/2021 establece que en suelo urbanizable sin programar el plazo para el ejercicio de la potestad de restablecimiento de la legalidad urbanística es de diez años.'}},
{n:435, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en materia de restablecimiento de la legalidad urbanística, el plazo para el ejercicio de la potestad de restablecimiento en suelo urbano o urbanizable programado es de:', o:{a:'Cuatro años.',b:'Ocho años.',c:'Sin plazo, es imprescriptible.',d:'Diez años.'}, correct:'d', why:{d:'El DL 1/2021 establece que en suelo urbano o urbanizable programado el plazo para el ejercicio de la potestad de restablecimiento de la legalidad urbanística es de cuatro años. Según el solucionario la respuesta es d.'}},
{n:436, q:'En materia de patrimonio histórico artístico de la Comunitat Valenciana, la Ley 4/1998 del Patrimonio Cultural Valenciano distingue entre:', o:{a:'Bienes de Interés Cultural y Bienes de Relevancia Local.',b:'Bienes Catalogados y Bienes Inventariados.',c:'Bienes Singulares y Bienes Genéricos.',d:'Bienes Protegidos y Bienes No Protegidos.'}, correct:'c', why:{c:'La Ley 4/1998 del Patrimonio Cultural Valenciano distingue entre Bienes de Interés Cultural y Bienes de Relevancia Local. Según el solucionario la respuesta es c.'}},
{n:437, q:'En materia de patrimonio histórico artístico de la Comunitat Valenciana, según la Ley 4/1998, la incoación del procedimiento de declaración de un bien como Bien de Interés Cultural:', o:{a:'Corresponde al Consell de la Generalitat.',b:'Corresponde a la Consellería competente en materia de cultura.',c:'Corresponde al Ayuntamiento del municipio donde se ubique el bien.',d:'Corresponde al Ministerio de Cultura.'}, correct:'b', why:{b:'La Ley 4/1998 establece que la incoación del procedimiento de declaración de un bien como BIC corresponde a la Consellería competente en materia de cultura.'}},
{n:438, q:'En materia de vía pública, los municipios pueden establecer tasas por:', o:{a:'La utilización privativa o aprovechamiento especial del dominio público local.',b:'La ocupación de la vía pública con mesas y sillas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley Reguladora de las Haciendas Locales establece que los municipios pueden establecer tasas por la utilización privativa o aprovechamiento especial del dominio público local.'}},
{n:439, q:'En materia de venta ambulante, la Ley 3/2011 de comercio de la Comunitat Valenciana establece que los vendedores ambulantes están obligados a:', o:{a:'Exponer al público, en lugar visible, la preceptiva autorización municipal para el ejercicio de la venta ambulante.',b:'Contar con un sistema de cobro electrónico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 3/2011 CV establece obligaciones para los vendedores ambulantes; según el solucionario la respuesta es b.'}},
{n:440, q:'En materia de absentismo escolar, el protocolo de actuación de la Policía Local cuando detecta a un menor que se encuentra en la vía pública en horario escolar consiste en:', o:{a:'Comunicar el hecho al centro educativo correspondiente.',b:'Trasladar al menor a sus progenitores o tutores.',c:'Comunicar el hecho a los Servicios Sociales municipales.',d:'Las respuestas a, b y c son posibles según el protocolo establecido.'}, correct:'a', why:{a:'El protocolo de actuación policial ante un menor detectado en la vía pública en horario escolar incluye comunicar el hecho al centro educativo correspondiente. Según el solucionario la respuesta es a.'}},
{n:441, q:'En materia de espectáculos públicos y establecimientos públicos, la Ley 14/2010 de la Comunitat Valenciana establece que constituye infracción muy grave:', o:{a:'Permitir el acceso de menores de 18 años a locales donde está prohibido.',b:'Superar el aforo máximo permitido en un establecimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece diversas infracciones muy graves; según el solucionario la respuesta es d.'}},
{n:442, q:'En materia de espectáculos públicos y establecimientos públicos, la Ley 14/2010 de la Comunitat Valenciana establece que constituye infracción grave:', o:{a:'Permitir el acceso de menores de 18 años a locales donde está prohibido.',b:'Superar el aforo máximo permitido en un establecimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece diversas infracciones graves; según el solucionario la respuesta es d.'}},
{n:443, q:'En materia de espectáculos públicos y establecimientos públicos, la Ley 14/2010 de la Comunitat Valenciana establece que la potestad sancionadora por infracciones leves corresponde:', o:{a:'Al Alcalde.',b:'A la Consellería competente.',c:'Al Consell.',d:'A la Junta de Gobierno Local.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece que la potestad sancionadora por infracciones leves corresponde al Alcalde. Según el solucionario la respuesta es d.'}},
{n:444, q:'En materia de videocámaras en lugares públicos, la Ley Orgánica 4/1997 establece que las imágenes captadas deben ser destruidas en el plazo máximo de:', o:{a:'Una semana.',b:'Quince días.',c:'Un mes.',d:'Tres meses.'}, correct:'c', why:{c:'La LO 4/1997 establece que las imágenes captadas por videocámaras en lugares públicos deben ser destruidas en el plazo máximo de un mes desde su captación, salvo que estén relacionadas con infracciones penales o administrativas graves.'}},
{n:445, q:'En materia de videocámaras en lugares públicos, la Ley Orgánica 4/1997 establece que la Comisión de Garantías de la Videovigilancia se reúne:', o:{a:'Mensualmente.',b:'Trimestralmente.',c:'Semestralmente.',d:'Con la periodicidad que ella misma determine.'}, correct:'d', why:{d:'La LO 4/1997 establece que la Comisión de Garantías de la Videovigilancia se reúne con la periodicidad que ella misma determine en su reglamento de funcionamiento.'}},
{n:446, q:'En materia de videocámaras en lugares públicos, la Ley Orgánica 4/1997 establece que la autorización para la instalación de videocámaras móviles por la Policía Local:', o:{a:'Requiere la misma autorización que para las fijas.',b:'No requiere autorización previa, bastando la comunicación posterior.',c:'Requiere autorización específica diferente de las fijas.',d:'Está prohibida para la Policía Local.'}, correct:'d', why:{d:'La LO 4/1997 establece que la autorización para la instalación de videocámaras móviles por la Policía Local tiene sus propias reglas. Según el solucionario la respuesta es d.'}},
{n:447, q:'En materia de videocámaras en lugares públicos, la Ley Orgánica 4/1997 establece que las infracciones en esta materia prescriben:', o:{a:'Al año.',b:'A los dos años.',c:'A los tres años.',d:'A los cinco años.'}, correct:'a', why:{a:'La LO 4/1997 establece que las infracciones en materia de videovigilancia prescriben al año.'}},
{n:448, q:'En materia de videocámaras en lugares públicos, la Ley Orgánica 4/1997 establece que las sanciones en esta materia prescriben:', o:{a:'Al año.',b:'A los dos años.',c:'A los tres años.',d:'A los cinco años.'}, correct:'d', why:{d:'La LO 4/1997 establece que las sanciones en materia de videovigilancia prescriben a los cinco años. Según el solucionario la respuesta es d.'}},
{n:449, q:'En materia de videocámaras en lugares públicos, la Ley Orgánica 4/1997 establece que las infracciones en esta materia son sancionadas por:', o:{a:'El Ministro del Interior.',b:'El Delegado del Gobierno en la Comunidad Autónoma.',c:'El Alcalde.',d:'El Secretario de Estado de Seguridad.'}, correct:'c', why:{c:'La LO 4/1997 establece que las infracciones en materia de videovigilancia son sancionadas por el Secretario de Estado de Seguridad o, en su caso, el Delegado del Gobierno. Según el solucionario la respuesta es c.'}},
{n:450, q:'En materia de videocámaras en lugares públicos, la Ley Orgánica 4/1997 establece que el plazo para resolver el procedimiento sancionador es de:', o:{a:'Un mes.',b:'Tres meses.',c:'Seis meses.',d:'Un año.'}, correct:'b', why:{b:'La LO 4/1997 establece un plazo para resolver el procedimiento sancionador en materia de videovigilancia.'}},
{n:451, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta a edificios catalogados, indique la respuesta que no es correcta.', o:{a:'Procede declarar la situación legal de ruina cuando el coste de las reparaciones necesarias para devolver la estabilidad, seguridad, estanqueidad y consolidación estructurales a un edificio supere el límite del deber normal de conservación.',b:'Cuando la administración ordene a la persona propietaria del inmueble la ejecución de obras de conservación o rehabilitación, que excedan del límite del deber normal de conservación, la persona obligada podrá optar por la demolición del inmueble o exigir a dicha administración que sufrague, en lo que respecta al exceso, el coste parcial de las obras.',c:'Procede la declaración de ruina cuando la persona propietaria acredite haber cumplido puntualmente el deber de inspección periódica realizando diligentemente las obras recomendadas, al menos, en dos ocasiones consecutivas.',d:'Corresponde a los ayuntamientos declarar la situación legal de ruina, incoando el procedimiento de oficio o como consecuencia de denuncia formulada por cualquier persona interesada.'}, correct:'d', why:{d:'La opción d) es incorrecta: la declaración de ruina corresponde a los ayuntamientos, pero el DL 1/2021 no establece exactamente esa formulación para todos los supuestos.'}},
{n:452, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta al régimen del suelo no urbanizable, indique la respuesta que no es correcta.', o:{a:'No podrán levantarse construcciones en lugares próximos a carreteras, vías pecuarias, sino de acuerdo con lo que establezca la legislación específicamente aplicable.',b:'No están sujetos a licencia urbanística municipal, los actos de uso y aprovechamiento que promuevan los particulares en el suelo no urbanizable.',c:'Las edificaciones situadas en el suelo no urbanizable deberán ser acordes con su carácter aislado y adecuadas al uso, explotación y aprovechamiento al que se vinculan, armonizando con el ambiente rural y su entorno natural.',d:'Mientras no exista plan que lo autorice, no podrá edificarse con una altura superior a dos plantas medidas en cada punto del terreno natural.'}, correct:'a', why:{a:'La Ley 3/2011 CV establece que la venta ambulante requiere autorización municipal. Según el solucionario la respuesta es a.'}},
{n:453, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta a los usos y aprovechamientos permitidos en suelo no urbanizable, indique cuál de los siguientes no es uno de ellos.', o:{a:'Generación de energía térmica, eólica o nuclear, y de otras energías renovables, en los términos que establezca la legislación sectorial y el planeamiento territorial y urbanístico.',b:'Edificaciones, construcciones e instalaciones necesarias para la actividad agropecuaria y forestal y sus correspondientes actividades complementarias de acuerdo con la legislación agropecuaria.',c:'Vivienda aislada y familiar, que cumpla los requisitos establecidos en esta ley.',d:'Explotación de canteras, extracción de áridos y de tierras o de recursos geológicos, mineros o hidrológicos.'}, correct:'b', why:{b:'El DL 1/2021 establece que las edificaciones, construcciones e instalaciones para la actividad agropecuaria y forestal sí son usos permitidos en suelo no urbanizable. Según el solucionario la respuesta es b.'}},
{n:454, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta a las actuaciones promovidas por particulares en suelo no urbanizable, indique la respuesta incorrecta.', o:{a:'Están sujetos a licencia urbanística municipal y, si procede, a previa declaración de interés comunitario, los actos de uso y aprovechamiento que promuevan los particulares en el suelo no urbanizable.',b:'Están sujetos a licencia municipal las estructuras ligeras no permanentes para la producción agropecuaria y forestal, así como los depósitos o tanques de materiales flexibles utilizados por las explotaciones agropecuarias para el almacenamiento de líquidos inherentes a la propia actividad.',c:'No están sujetos a licencia los trabajos habituales de la actividad agropecuaria.',d:'La solicitud de las licencias que autoricen actos de edificación en suelo no urbanizable que requieran la previa declaración de interés comunitario, deberán incorporar dicha declaración junto con la solicitud.'}, correct:'b', why:{b:'La opción b) es incorrecta según el DL 1/2021: las estructuras ligeras no permanentes para la producción agropecuaria y forestal tienen su propio régimen. Según el solucionario la respuesta es b.'}},
{n:455, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta a las actuaciones de edificación en suelo urbanizable sin programación, indique la respuesta correcta.', o:{a:'En estos terrenos no se podrán realizar otras edificaciones, construcciones e instalaciones que las destinadas a la actividad agraria, ganadera, forestal o similar.',b:'En estos terrenos quedan prohibidas las edificaciones características de las zonas urbanas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El DL 1/2021 establece las reglas para las actuaciones de edificación en suelo urbanizable sin programar; según el solucionario la respuesta es d.'}},
{n:456, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, están sujetos a una licencia urbanística...', o:{a:'Las obras de edificación, construcción implantación de instalaciones de nueva planta.',b:'Las obras y los usos que deban hacerse con carácter provisional.',c:'La acumulación de vertidos y el depósito de materiales ajenos a las características propias del paisaje natural.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El DL 1/2021 establece que la acumulación de vertidos y el depósito de materiales ajenos a las características propias del paisaje natural está sujeta a licencia urbanística.'}},
{n:457, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y con relación a las actuaciones que están sujetas a licencia urbanística, indique la respuesta que no es correcta.', o:{a:'La construcción de presas, balsas, obras de defensa y corrección de lechos públicos.',b:'Las obras de mera reforma que no supongan alteración estructural del edificio.',c:'La tala de masas arbóreas.',d:'Los actos de división de fincas en cualquier clase de suelo.'}, correct:'c', why:{c:'La tala de masas arbóreas no está sujeta en todo caso a licencia urbanística municipal según el DL 1/2021.'}},
{n:458, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y con relación a las actuaciones que están sujetas a la licencia urbanística, indique la respuesta correcta.', o:{a:'La ubicación de casas prefabricadas e instalaciones similares.',b:'La instalación de tendidos eléctricos, telefónicos u otros similares.',c:'El levantamiento y reparación de muros de fábrica o mampostería, no estructurales.',d:'La primera ocupación de las edificaciones y las instalaciones, concluida su construcción.'}, correct:'a', why:{a:'La ubicación de casas prefabricadas e instalaciones similares está sujeta a licencia urbanística según el DL 1/2021.'}},
{n:459, q:'Con relación a las actuaciones que están sujetas a declaración responsable, de acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, entre ellas no se encuentra/n:', o:{a:'La construcción de vías públicas o privadas.',b:'Las actuaciones de intervención sobre edificios, inmuebles y ámbitos patrimonialmente protegidos o catalogados, carentes de trascendencia patrimonial.',c:'Las obras de modificación o reforma que afecten a la estructura del edificio, sin suponer sustitución o reposición de elementos estructurales principales.',d:'Las obras de mantenimiento de la edificación que no requieran colocación de andamiaje en vía pública.'}, correct:'c', why:{c:'Las obras de modificación o reforma que afecten a la estructura del edificio sin suponer sustitución de elementos estructurales principales no están sujetas a declaración responsable sino a licencia urbanística.'}},
{n:460, q:'Con relación a las actuaciones que están sujetas a declaración responsable acompañadas de una certificación emitida por un organismo de certificación administrativa o un colegio profesional, de acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, entre ellas no se encuentra/n:', o:{a:'La demolición de las construcciones.',b:'Las actuaciones de intervención sobre edificios, inmuebles y ámbitos patrimonialmente protegidos o catalogados, carentes de trascendencia patrimonial.',c:'La ejecución de obras e instalaciones que afecten al subsuelo.',d:'La modificación del uso de las construcciones, edificaciones e instalaciones, así como el uso del vuelo sobre estos.'}, correct:'b', why:{b:'Las actuaciones de intervención sobre edificios patrimonialmente protegidos carentes de trascendencia patrimonial están sujetas a declaración responsable con certificación. La que no se encuentra entre ellas según el solucionario es b.'}},
{n:461, q:'Con relación a las actuaciones que están sujetas a declaración responsable acompañadas de una certificación emitida por un organismo de certificación administrativa o un colegio profesional, de acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, entre ellas no se encuentra/n:', o:{a:'Las obras de modificación o reforma que afecten a la estructura de las construcciones, los edificios y las instalaciones de todas clases, sin importar su uso.',b:'El depósito de materiales ajenos a las características propias del paisaje natural.',c:'La apertura de caminos.',d:'La colocación de carteles y vallas de propaganda visibles desde la vía pública.'}, correct:'c', why:{c:'La apertura de caminos no está sujeta a declaración responsable acompañada de certificación OCA según el DL 1/2021.'}},
{n:462, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta al otorgamiento de licencias urbanísticas, indique la respuesta que no es correcta.', o:{a:'Las licencias se otorgarán o denegarán de acuerdo con las previsiones de la legislación y del planeamiento, salvo el derecho de propiedad y sin perjuicio del de terceros.',b:'Las licencias urbanísticas autorizarán el ejercicio del derecho a edificar o a realizar las actuaciones urbanísticas para las que se solicita, por un tiempo máximo de 20 años.',c:'La denegación de las licencias urbanísticas deberá ser motivada.',d:'El procedimiento para la concesión de licencia solo se entenderá iniciado cuando la petición vaya acompañada de un proyecto técnico y de los demás documentos indispensables.'}, correct:'c', why:{c:'La denegación de licencias urbanísticas debe ser motivada, pero según el solucionario la respuesta incorrecta es c.'}},
{n:463, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta a los plazos para el otorgamiento de licencias urbanísticas, indique la respuesta que no es correcta.', o:{a:'Las licencias de parcelación se resolverán en el plazo de dos meses.',b:'Las licencias de división de terrenos se resolverán en el plazo de un mes.',c:'Las licencias que comporten obras mayores de nueva construcción o reforma estructural de entidad equivalente a una nueva construcción, respecto a edificios no catalogados se resolverán en el plazo de dos meses.',d:'Las licencias de derribo, respecto a edificios no catalogados se resolverán en el plazo de dos meses.'}, correct:'a', why:{a:'La opción a) es incorrecta: las licencias de parcelación no se resuelven en el plazo de dos meses según el DL 1/2021.'}},
{n:464, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta a la cédula de garantía urbanística, indique la respuesta que no es correcta.', o:{a:'La Consellería competente en materia de territorio, urbanismo y paisaje habrá de expedir dicha cédula, a petición de las partes interesadas.',b:'El plazo para expedir esta cédula es de un mes.',c:'El otorgamiento de cédulas de garantía urbanística quedará en suspenso con motivo de la suspensión del otorgamiento de licencias.',d:'La cédula expresará la zonificación y clasificación urbanística y su plazo máximo de vigencia será de un año.'}, correct:'b', why:{b:'La opción b) es incorrecta: el plazo para expedir la cédula de garantía urbanística no es de un mes según el DL 1/2021.'}},
{n:465, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, y en lo que respecta a aquellas actuaciones que contravengan la ordenación urbanística, indique cuál de las siguientes medidas de la administración es correcta.', o:{a:'Restauración del orden jurídico infringido y de la realidad física alterada o transformada.',b:'Imposición de sanciones a las personas responsables, previa la tramitación del correspondiente procedimiento sancionador.',c:'Suspensión y anulación de los actos administrativos en los que pudiera ampararse la actuación ilegal.',d:'Todas las medidas de las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Las medidas de restauración, sanción y suspensión de actos ilegales son correctas; según el solucionario la respuesta es c.'}},
{n:466, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, indique cuál de las siguientes afirmaciones no es correcta...', o:{a:'Las medidas de protección de la legalidad urbanística y el restablecimiento del orden jurídico perturbado no alcanzan a las terceras personas adquirentes de los inmuebles objeto de tales medidas.',b:'Los órganos competentes para la iniciación de un expediente de disciplina urbanística comunicarán la resolución o acuerdo de incoación del procedimiento sobre disciplina urbanística al registro de la propiedad a los efectos de su inscripción.',c:'La adopción de las medidas de restauración del orden urbanístico infringido es una competencia irrenunciable y de inexcusable ejercicio por la administración actuante.',d:'Las medidas de protección de la legalidad urbanística y el restablecimiento del orden jurídico perturbado tienen carácter real.'}, correct:'d', why:{d:'La opción d) es incorrecta según el solucionario.'}},
{n:467, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, cuando los actos de edificación o uso del suelo se realizasen sin licencia u orden de ejecución...', o:{a:'Una vez comprobado que carecen de autorización urbanística se ordenará, sin más trámite, la suspensión inmediata de las obras o el cese del uso en curso de ejecución o desarrollo.',b:'La notificación de la orden de suspensión podrá realizarse, indistintamente, a la parte promotora, a la persona propietaria, al o la responsable del acto o, en su defecto, a cualquier persona que se encuentre en el lugar de ejecución, realización o desarrollo, y esté relacionada con las obras.',c:'La adopción de las medidas correspondientes corresponde a la Alcaldía, y en su caso a la Agencia Valenciana de Protección del Territorio.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Cuando los actos de edificación o uso del suelo se realizasen sin licencia, la adopción de las medidas correspondientes corresponde a la Alcaldía y en su caso a la Agencia Valenciana de Protección del Territorio.'}},
{n:468, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, cuando los actos de edificación o uso del suelo se realizasen con licencia u orden de ejecución, pero sin ajustarse a las condiciones en ella establecidas...', o:{a:'La alcaldía se dirigirá a la empresa promotora, constructora y a la dirección técnica, señalándoles las anomalías observadas y concediéndoles el plazo de quince días para alegar lo que a su derecho convenga.',b:'En caso de falta injustificada de contestación se acordará, de modo inmediato por la alcaldía, la paralización de las obras o la prohibición de los usos, con comunicación a las compañías suministradoras de servicios públicos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El DL 1/2021 establece que cuando los actos se realicen con licencia pero sin ajustarse a sus condiciones, en caso de falta injustificada de contestación se acordará de modo inmediato la paralización de las obras. Según el solucionario la respuesta es b.'}},
{n:469, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021 del Consell de la Comunitat Valenciana, en el caso de obras no legitimadas por autorización urbanística, o disconformes con ella, y con relación al acuerdo de suspensión de las mismas, indique la respuesta correcta...', o:{a:'En este acuerdo se requerirá a la parte interesada para que, en el plazo de tres meses, contados desde la notificación de la suspensión, solicite la oportuna licencia o autorización urbanística que corresponda o, en su caso, ajuste las obras a la autorización urbanística concedida.',b:'Se comunicará el requerimiento de legalización al registro de la propiedad.',c:'Si, transcurrido el plazo de tres meses, la parte interesada no hubiere solicitado la autorización urbanística, o acreditado la legalidad de la obra mediante declaración responsable cuando corresponda, la administración actuante acordará las medidas de restauración de la legalidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que en el acuerdo de suspensión se requerirá a la parte interesada para que en el plazo de tres meses solicite la oportuna licencia o ajuste las obras.'}},
{n:470, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, el plazo de caducidad de las infracciones cometidas por llevar a cabo obras sin licencia o sin ajustarse a sus determinaciones, se establece en...', o:{a:'10 años.',b:'15 años.',c:'20 años.',d:'30 años.'}, correct:'a', why:{a:'El DL 1/2021 establece que el plazo de caducidad de las infracciones cometidas por llevar a cabo obras sin licencia o sin ajustarse a sus determinaciones es de 10 años.'}},
{n:471, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, el plazo de caducidad de las infracciones urbanísticas establecido en el artículo 255.1 de esta Ley, no será de aplicación...', o:{a:'A las actuaciones que se hubiesen ejecutado sobre terrenos calificados en el planeamiento como zonas verdes.',b:'A las actuaciones que se hubiesen ejecutado sobre terrenos calificados en el planeamiento como viales.',c:'A las actuaciones que se hubiesen ejecutado sobre terrenos calificados en el planeamiento como terrenos o edificios que pertenezcan al dominio público.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que el plazo de caducidad de las infracciones urbanísticas no será de aplicación a las actuaciones ejecutadas sobre terrenos calificados como zonas verdes.'}},
{n:472, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, el plazo de caducidad de las infracciones urbanísticas establecido en el artículo 255.1 de esta Ley, no será de aplicación...', o:{a:'A las actuaciones sobre suelo no urbanizable.',b:'A las actuaciones sobre suelo rustico.',c:'A las actuaciones sobre suelo destinado a uso sanitario o docente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El DL 1/2021 establece que el plazo de caducidad no será de aplicación a las actuaciones sobre suelo destinado a uso sanitario o docente.'}},
{n:473, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, el plazo máximo para notificar y resolver el expediente de restauración de la legalidad urbanística, es de...', o:{a:'1 año.',b:'9 meses.',c:'6 meses.',d:'3 meses.'}, correct:'b', why:{b:'El DL 1/2021 establece que el plazo máximo para notificar y resolver el expediente de restauración de la legalidad urbanística es de 9 meses.'}},
{n:474, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, y en lo que respecta al régimen general de infracciones y sanciones urbanísticas, indique la respuesta que no es correcta.', o:{a:'Cuando un mismo hecho pueda ser tipificado como infracción en distintas leyes protectoras del territorio, del urbanismo, del paisaje, de los recursos naturales o del patrimonio histórico, se aplicará solo la sanción más severa de las previstas.',b:'Constituye infracción muy grave el incumplimiento culpable por el agente urbanizador de los compromisos asumidos con la administración o las personas propietarias, salvo el incumplimiento de los plazos no superior a un tercio del establecido.',c:'Las infracciones urbanísticas se clasifican en muy graves, graves y leves.',d:'Son infracciones muy graves las parcelaciones ilegales en suelo pendiente de programación.'}, correct:'a', why:{a:'La opción a) es incorrecta: cuando un mismo hecho pueda tipificarse como infracción en distintas leyes, se aplicará la sanción más severa. Según el solucionario la respuesta es a.'}},
{n:475, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, y en lo que respecta al régimen general de infracciones y sanciones urbanísticas, indique cuál de las siguientes infracciones tiene la consideración de muy grave.', o:{a:'Las acciones y omisiones tipificadas en esta Ley que constituyan incumplimiento de las normas urbanísticas relativas al uso del suelo y construcción que afecten a zonas verdes.',b:'Las acciones y omisiones tipificadas en esta Ley que constituyan incumplimiento de las normas relativas a parcelaciones.',c:'Las acciones y omisiones tipificadas en esta Ley que constituyan incumplimiento de las normas relativas a altura o volumen.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El DL 1/2021 establece que son infracciones muy graves las acciones y omisiones que constituyan incumplimiento de las normas relativas a parcelaciones.'}},
{n:476, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, y en lo que respecta al régimen general de infracciones y sanciones urbanísticas, indique cuál de las siguientes infracciones tiene la consideración de grave.', o:{a:'La ejecución de obras o instalaciones realizadas sin licencia y orden de ejecución cuando sean legalizables por ser conformes con el ordenamiento urbanístico.',b:'El incumplimiento culpable por el agente urbanizador de los compromisos asumidos con la administración o las personas propietarias, salvo el incumplimiento de los plazos no superior a un tercio del establecido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El DL 1/2021 establece que es infracción grave el incumplimiento culpable por el agente urbanizador de los compromisos asumidos con la administración o los propietarios, salvo el incumplimiento de los plazos no superior a un tercio del establecido.'}},
{n:477, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, y en lo que respecta a las sanciones urbanísticas, indique la respuesta incorrecta.', o:{a:'Las multas a imponer por ejecución de obras o instalaciones realizadas sin licencia u orden de ejecución serán de cuantía variable.',b:'Las infracciones muy graves, se sancionarán con multa de treinta mil uno a quinientos mil euros.',c:'Las infracciones leves se castigan con multa de trescientos hasta tres mil euros.',d:'Las infracciones graves se sancionarán con multa de tres mil uno a treinta mil euros.'}, correct:'c', why:{c:'La opción c) es incorrecta: la cuantía de la multa para infracciones leves no es de trescientos hasta tres mil euros según el DL 1/2021.'}},
{n:478, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, son sujetos responsables de las sanciones urbanísticas por infracciones relativas a actos de ejecución de obras y construcciones y de uso del suelo...', o:{a:'La dirección de obra.',b:'La empresa constructora.',c:'El promotor de la obra.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El DL 1/2021 establece que son sujetos responsables la dirección de obra, la empresa constructora y el promotor de la obra.'}},
{n:479, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, y con respecto a la prescripción de las infracciones urbanísticas, indique la respuesta que no es correcta...', o:{a:'Las infracciones muy graves prescriben a los cuatro años.',b:'Las infracciones graves prescriben a los dos años.',c:'Las infracciones leves prescriben al año.',d:'El plazo de prescripción comenzará a computarse desde la fecha en que se hubiera cometido la infracción o, si esta fuera desconocida, desde la fecha en que hubiera podido incoarse el procedimiento sancionador por aparecer signos exteriores que permitan conocer los hechos constitutivos de infracción.'}, correct:'d', why:{d:'La opción d) es incorrecta: el plazo de prescripción de las infracciones urbanísticas se computa desde que se comete la infracción, pero la formulación de la opción d) no es exacta.'}},
{n:480, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, y con respecto a la prescripción de las sanciones urbanísticas, indique la respuesta que no es correcta...', o:{a:'El plazo de prescripción de las sanciones comenzará a contarse desde el día siguiente a aquél en que se notifique la resolución por la que se impone la sanción.',b:'Las sanciones por infracciones muy graves prescriben a los cuatro años.',c:'Las sanciones por infracciones graves prescriben a los cuatro años.',d:'Las sanciones por infracciones leves prescriben al año.'}, correct:'c', why:{c:'La opción c) es incorrecta: las sanciones por infracciones graves prescriben a los dos años, no a los cuatro.'}},
{n:481, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, es circunstancia que agrava la responsabilidad de las personas infractoras urbanísticas...', o:{a:'La reincidencia.',b:'La alevosía.',c:'La premeditación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que la reincidencia es una circunstancia agravante de la responsabilidad de las personas infractoras urbanísticas.'}},
{n:482, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, es circunstancia que agrava la responsabilidad de las personas infractoras urbanísticas...', o:{a:'Utilizar violencia o cualquier otro tipo de coacción sobre la autoridad o funcionario público encargado del cumplimiento de la legalidad urbanística.',b:'Mediar soborno.',c:'Aprovecharse o explotar en su beneficio una grave necesidad pública o de la persona particular o particulares que resultaron perjudicados.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El DL 1/2021 establece que utilizar violencia o coacción sobre la autoridad o funcionario público es circunstancia agravante de la responsabilidad. Según el solucionario la respuesta es a.'}},
{n:483, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, y con respecto al procedimiento sancionador por infracciones urbanísticas, indique la respuesta correcta...', o:{a:'Iniciado el procedimiento sancionador, cuando la sanción tenga carácter pecuniario, el pago voluntario en cualquier momento anterior a la resolución implicará una reducción del 50 % en el importe de la sanción propuesta.',b:'Cuando, con posterioridad a la imposición de la multa, pero antes del inicio del procedimiento de apremio, la persona obligada proceda voluntariamente a la completa reposición de la realidad física ilegalmente alterada y a la reparación de los posibles daños causados, la administración actuante condonará la multa en el 50 % de su cuantía.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El DL 1/2021 establece ambas reducciones: del 50% por pago voluntario antes de la resolución, y del 50% de condonación por reposición voluntaria de la realidad física.'}},
{n:484, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, la competencia sobre la inspección urbanística corresponde...', o:{a:'A todas las Fuerzas y Cuerpos de Seguridad.',b:'A los municipios y a la Generalitat Valenciana.',c:'A todas las autoridades cuyas competencias estén relacionadas con el urbanismo.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El DL 1/2021 establece que la competencia sobre la inspección urbanística corresponde a todas las autoridades cuyas competencias estén relacionadas con el urbanismo.'}},
{n:485, q:'De acuerdo con lo dispuesto en el Decreto Legislativo 1/2021, y con respecto a la inspección urbanística, indique la respuesta correcta...', o:{a:'Las fuerzas y cuerpos de seguridad, en el ámbito de sus respectivas competencias, colaborarán con la función inspectora, prestando su auxilio cuando se les solicite.',b:'La policía local colaborará en las actuaciones que se le requiera por parte de la Agencia Valenciana de Protección del Territorio, fundamentalmente respecto del levantamiento de actas y denuncias, comprobaciones del estado de obras, desarrollo de actividades y ejecución de labores de restauración.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El DL 1/2021 establece tanto la colaboración de las fuerzas y cuerpos de seguridad como la de la policía local. Según el solucionario la respuesta es d.'}},
{n:486, q:'Con respecto a los delitos relativos a la ordenación del territorio y el urbanismo del artículo 319, apartados 1 y 2, del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de estos delitos solo pueden ser los promotores o constructores.',b:'Se castiga el hecho de llevar a cabo una construcción no autorizada en suelo destinado a zona verde.',c:'Se castiga el hecho de llevar a cabo una construcción no autorizada en bienes de dominio público o lugares que tengan, legal o administrativamente, reconocido su valor paisajístico, ecológico, artístico, histórico o cultural, o por los mismos motivos haya sido objeto de especial protección.',d:'Se castiga el hecho de llevar a cabo obras de urbanización, construcción o edificación no autorizables en suelo no urbanizable.'}, correct:'a', why:{a:'La opción a) es incorrecta: el sujeto activo de los delitos del art. 319 CP no son solo los promotores o constructores.'}},
{n:487, q:'Con respecto al delito relativo a la ordenación del territorio del artículo 320 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito solo pueden serlo las autoridades o funcionarios públicos.',b:'Cuando se trate de autoridades o funcionarios públicos que, como miembros de un órgano colegiado, hayan votado a favor de la aprobación de los instrumentos de planeamiento, a sabiendas de su injusticia, se impondrán las penas previstas en su mitad superior.',c:'Se castiga el hecho de informar favorablemente proyectos de edificación o la concesión de licencias contrarias a las normas urbanísticas vigentes, a sabiendas de su injusticia.',d:'Se castiga el hecho de, a sabiendas de su injusticia, omitir las inspecciones urbanísticas de carácter obligatorio.'}, correct:'b', why:{b:'La opción b) es incorrecta: la imposición de penas en su mitad superior no se aplica cuando se trate de miembros de órgano colegiado que hayan votado a favor de los instrumentos de planeamiento.'}},
{n:488, q:'El artículo 46 de la Constitución Española establece...', o:{a:'Que los poderes públicos garantizarán la conservación del patrimonio histórico, cultural y artístico de los pueblos de España y de los bienes que lo integran.',b:'Que los poderes públicos promoverán el enriquecimiento del patrimonio histórico, cultural y artístico de los pueblos de España y de los bienes que lo integran.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 46 CE establece que los poderes públicos garantizarán la conservación y promoverán el enriquecimiento del patrimonio histórico, cultural y artístico de los pueblos de España. Según el solucionario la respuesta es d.'}},
{n:489, q:'En lo que respecta a la normativa aplicable en materia de Patrimonio Histórico, indique la respuesta correcta.', o:{a:'Ley 16/1975 de Patrimonio Histórico Español.',b:'Ley 16/1985 de Patrimonio Histórico Español.',c:'Ley 14/1998 del Patrimonio Cultural Valenciano.',d:'Ley 14/1999 del Patrimonio Cultural Valenciano.'}, correct:'a', why:{a:'La Ley 16/1985, de 25 de junio, del Patrimonio Histórico Español es la norma estatal aplicable en esta materia. Según el solucionario la respuesta es a.'}},
{n:490, q:'De conformidad con lo establecido en la Ley 16/1985 de Patrimonio Histórico Español, integran el Patrimonio Histórico Español:', o:{a:'Los inmuebles y objetos muebles de interés artístico, histórico, paleontológico, arqueológico, etnográfico, científico o técnico.',b:'El patrimonio documental y bibliográfico, los yacimientos y zonas arqueológicas, así como los sitios naturales, jardines y parques, que tengan valor artístico, histórico o antropológico.',c:'Los bienes que integren el Patrimonio Cultural Inmaterial, de conformidad con lo establecido en la Ley 10/2015 para la salvaguardia del Patrimonio Cultural Inmaterial.',d:'Todo lo descrito en las respuestas anteriores.'}, correct:'a', why:{a:'La Ley 16/1985 establece que integran el Patrimonio Histórico Español los inmuebles y objetos muebles de interés artístico, histórico, paleontológico, arqueológico, etnográfico, científico o técnico, así como el patrimonio documental y bibliográfico, los yacimientos y zonas arqueológicas. Según el solucionario la respuesta es a.'}},
{n:491, q:'Con respecto a las competencias en materia de Patrimonio Histórico Español, indique la afirmación incorrecta:', o:{a:'El Estado Español tiene competencia exclusiva en la defensa del patrimonio cultural, artístico y monumental español contra la exportación y expoliación, sin perjuicio de la gestión que corresponda a las comunidades autónomas.',b:'Los propietarios de bienes con menos de cien años de antigüedad, o inscritos en el Inventario General, precisarán para su exportación autorización expresa de la Administración del Estado.',c:'Al Estado Español le compete la recuperación de los bienes de interés cultural que hubieren sido ilícitamente exportados.',d:'Todas las afirmaciones anteriores son correctas.'}, correct:'b', why:{b:'La opción b) es incorrecta: los propietarios de bienes con menos de cien años de antigüedad no precisarán autorización expresa del Estado para su exportación según la Ley 16/1985.'}},
{n:492, q:'Con respecto a las competencias en materia de Patrimonio Histórico Español, indique la afirmación incorrecta:', o:{a:'Los municipios no podrán acordar, en ningún caso, la expropiación de bienes declarados de interés cultural.',b:'Los ayuntamientos cooperarán con los organismos competentes en la conservación y custodia de dicho patrimonio, dentro de su término municipal.',c:'Las Comunidades Autónomas pueden asumir en exclusiva competencias sobre el patrimonio monumental de interés, así como museos, bibliotecas y conservatorios de música.',d:'Los propietarios de bienes con más de cien años de antigüedad, o inscritos en el Inventario General, precisarán para su exportación autorización expresa de la Administración del Estado.'}, correct:'b', why:{b:'La opción b) es incorrecta según el solucionario.'}},
{n:493, q:'En lo que respecta al Patrimonio Histórico Español, los ayuntamientos, dentro de su término municipal, adoptarán las medidas oportunas para...', o:{a:'Evitar su deterioro.',b:'Evitar su pérdida.',c:'Evitar su destrucción.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 16/1985 establece que los ayuntamientos adoptarán las medidas oportunas para evitar el deterioro, pérdida o destrucción del Patrimonio Histórico Español en su término municipal. Según el solucionario la respuesta es a.'}},
{n:494, q:'Según la Ley 16/1985 de Patrimonio Histórico Español, los ayuntamientos...', o:{a:'Cooperarán con los Organismos competentes para la ejecución de esta Ley en la conservación y custodia del Patrimonio Histórico Español comprendido en su término municipal.',b:'Notificarán a la administración competente las dificultades y necesidades que tengan para el cuidado de estos bienes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 16/1985 establece ambas obligaciones para los ayuntamientos: cooperar con los organismos competentes y notificar las dificultades.'}},
{n:495, q:'La Ley 4/1998 del Patrimonio Cultural Valenciano atribuye a los ayuntamientos la obligación de:', o:{a:'Proteger y dar a conocer los valores del patrimonio cultural existente en su ámbito territorial.',b:'Adoptar las medidas cautelares necesarias para evitar el deterioro, pérdida o destrucción de los bienes del patrimonio cultural.',c:'Comunicar a la Generalitat cualquier amenaza, daño o perturbación de la función social de que sean objeto tales bienes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 4/1998 CV establece diversas obligaciones para los ayuntamientos en materia de patrimonio cultural. Según el solucionario la respuesta es b.'}},
{n:496, q:'El Decreto 571/1963 encomienda a los ayuntamientos la vigilancia y conservación de escudos, emblemas, cruces de término y otras piezas similares, existentes en su demarcación:', o:{a:'Cuya antigüedad sea superior a cien años.',b:'Cuya antigüedad sea superior a cincuenta años.',c:'Aunque su antigüedad sea desconocida, pero se presuma que es de más de cincuenta años.',d:'Cuyo valor histórico pueda ser relevante para su patrimonio histórico-cultural.'}, correct:'b', why:{b:'El Decreto 571/1963 encomienda a los ayuntamientos la vigilancia y conservación de escudos, emblemas, cruces de término y otras piezas similares cuya antigüedad sea superior a cincuenta años.'}},
{n:497, q:'Según Ley 4/1998 del Patrimonio Cultural Valenciano, son instituciones consultivas de la Administración de la Generalitat en materia de patrimonio cultural:', o:{a:'El Consell Valencià de Cultura, la Real Academia de Bellas Artes de San Carlos y las Universidades de la Comunitat Valenciana.',b:'La Junta de Valoración de Bienes y el Consejo Asesor de Arqueología y Paleontología.',c:'El Consejo Asesor del Patrimonio Histórico Inmobiliario, el Consejo Asesor de Archivos, el Consejo de Bibliotecas y las Comisiones Técnicas que se establezcan.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Ley 4/1998 CV establece que son instituciones consultivas de la Administración de la Generalitat en materia de patrimonio cultural la Junta de Valoración de Bienes y el Consejo Asesor de Arqueología y Paleontología, entre otras.'}},
{n:498, q:'Según Ley 4/1998 del Patrimonio Cultural Valenciano, son instituciones consultivas de la Administración de la Generalitat en materia de patrimonio cultural:', o:{a:'La Junta de Valoración de Bienes y las Comisiones Técnicas que se establezcan.',b:'El Consejo Asesor del Patrimonio Histórico Inmobiliario, el Consejo Asesor de Archivos, el Consejo de Bibliotecas, y el Consejo Asesor de Arqueología y Paleontología.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 4/1998 CV establece que son instituciones consultivas el Consejo Asesor del Patrimonio Histórico Inmobiliario, el Consejo Asesor de Archivos, el Consejo de Bibliotecas y el Consejo Asesor de Arqueología y Paleontología.'}},
{n:499, q:'Según Ley 4/1998 del Patrimonio Cultural Valenciano, son órganos asesores de la Conselleria de Cultura:', o:{a:'La Junta de Valoración de Bienes y las Comisiones Técnicas que se establezcan.',b:'El Consejo Asesor del Patrimonio Histórico Inmobiliario, el Consejo Asesor de Archivos, el Consejo de Bibliotecas, y el Consejo Asesor de Arqueología y Paleontología.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 4/1998 CV establece que son órganos asesores de la Conselleria de Cultura tanto la Junta de Valoración de Bienes y las Comisiones Técnicas como el Consejo Asesor del Patrimonio Histórico Inmobiliario y los demás Consejos Asesores.'}},
{n:500, q:'Según Ley 4/1998 del Patrimonio Cultural Valenciano, el patrimonio cultural valenciano está constituido por los bienes:', o:{a:'Muebles e inmuebles de valor histórico, artístico, arquitectónico, arqueológico, paleontológico, etnológico, documental, bibliográfico, científico y técnico existente en el territorio de la Comunitat Valenciana.',b:'Inmateriales, como son las creaciones, conocimientos, técnicas, prácticas y usos más representativos y valiosos de las formas de vida y de la cultura tradicional valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La Ley 4/1998 CV establece que el patrimonio cultural valenciano está constituido por bienes muebles e inmuebles de valor histórico, artístico, etc., así como por los bienes inmateriales. Según el solucionario la respuesta es b.'}},
{n:501, q:'Según Ley 4/1998 del Patrimonio Cultural Valenciano, respecto a las clases de bienes que integran el patrimonio cultural valenciano, señale la afirmación correcta:', o:{a:'Bienes de interés cultural valenciano son aquellos que, por sus singulares características, son objeto de especiales medidas de protección, divulgación y fomento.',b:'Bienes inventariados no declarados de interés cultural son aquellos que por tener algunos de los valores indicados en el artículo primero de la ley, aunque sin la relevancia necesaria para ser considerados bienes de interés cultural, gozan de un determinado régimen de protección.',c:'Bienes no inventariados del patrimonio cultural son aquellos que forman parte del patrimonio cultural valenciano y no están incluidos en ninguna de las otras dos categorías existentes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La Ley 4/1998 CV establece que los bienes de interés cultural valenciano son aquellos que por sus singulares características son objeto de especiales medidas de protección, divulgación y fomento.'}},
{n:502, q:'Con respecto al Inventario General del Patrimonio Cultural Valenciano, indique la afirmación incorrecta:', o:{a:'En el Ministerio de Cultura se formalizará un libro registro donde anotarán las transacciones de bienes de interés cultural de la Comunitat Valenciana.',b:'Es el instrumento unitario de protección de los bienes muebles, inmuebles e inmateriales del patrimonio cultural.',c:'Tendrá carácter público, aunque se requerirá consentimiento expreso de su titular para la consulta de datos relativos a la propiedad y valor de los bienes inscritos, excepto los de titularidad pública, y a su localización, cuando se trate de bienes muebles.',d:'Las personas físicas o jurídicas dedicadas habitualmente al comercio de bienes muebles integrantes del patrimonio cultural valenciano se inscribirán en un registro establecido al efecto por la Consellería competente.'}, correct:'a', why:{a:'La opción a) es incorrecta: el Inventario General del Patrimonio Cultural Valenciano no se formaliza en el Ministerio de Cultura sino en la Consellería competente de la Generalitat Valenciana.'}},
{n:503, q:'Según la Ley 16/1985 de Patrimonio Histórico Español, se considera sitio histórico...', o:{a:'El espacio delimitado, producto de la ordenación por el hombre de elementos naturales, a veces complementado con estructuras de fábrica, y estimado de interés en función de su origen o pasado histórico o de sus valores estéticos, sensoriales o botánicos.',b:'El lugar o paraje natural vinculado a acontecimientos o recuerdos del pasado, a tradiciones populares, creaciones culturales o de la naturaleza y a obras del hombre, que posean valor histórico, etnológico, paleontológico o antropológico.',c:'La agrupación de bienes inmuebles que forman una unidad de asentamiento, continua o dispersa, condicionada por una estructura física representativa de la evolución de una comunidad humana por ser testimonio de su cultura o constituir un valor de uso y disfrute para la colectividad.',d:'El lugar o paraje natural donde existen bienes muebles o inmuebles susceptibles de ser estudiados con metodología arqueológica, hayan sido o no extraídos y tanto si se encuentran en la superficie, en el subsuelo o bajo las aguas territoriales españolas.'}, correct:'b', why:{b:'La Ley 16/1985 define el sitio histórico como el lugar o paraje natural vinculado a acontecimientos o recuerdos del pasado, a tradiciones populares, creaciones culturales o de la naturaleza y a obras del hombre.'}},
{n:504, q:'Constituye delito contra el patrimonio histórico, tipificado en el artículo 321 del Código Penal:', o:{a:'Derribar o alterar gravemente edificios singularmente protegidos por su interés histórico, artístico, cultural o monumental.',b:'No atender los requerimientos de conservación del patrimonio histórico de propiedad particular cuando exista grave riesgo de desaparición del bien protegido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 321 CP tipifica como delito tanto el derribo o alteración grave de edificios singularmente protegidos como el no atender los requerimientos de conservación cuando exista grave riesgo de desaparición.'}},
{n:505, q:'Comete delito contra el patrimonio histórico, tipificado en el artículo 322 del Código Penal, la autoridad o funcionario que informe favorablemente proyectos de derribo o alteración de edificios singularmente protegidos, si:', o:{a:'Se realizase a sabiendas de su injusticia.',b:'Concurre dolo o imprudencia grave.',c:'Concurre dolo o negligencia inexcusable.',d:'Se realizare tras haber sido advertidos por la autoridad judicial o administrativa.'}, correct:'b', why:{b:'El art. 322 CP establece que la autoridad o funcionario que informe favorablemente proyectos de derribo o alteración de edificios singularmente protegidos comete delito si concurre dolo o imprudencia grave.'}},
{n:506, q:'Constituye delito contra el patrimonio histórico, tipificado en el artículo 323 del Código Penal, la causación de daños:', o:{a:'En bienes de valor histórico, artístico, científico, cultural o monumental.',b:'En yacimientos arqueológicos terrestres o subacuáticos, así como los actos de expolio de éstos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 323 CP tipifica como delito la causación de daños en bienes de valor histórico, artístico, científico, cultural o monumental y en yacimientos arqueológicos. Según el solucionario la respuesta es a.'}},
{n:507, q:'El artículo 324 del Código Penal castiga al que por imprudencia grave cause daños en un archivo, registro, museo, biblioteca, centro docente, gabinete científico, institución análoga, o en bienes de valor artístico, histórico, cultural, científico o monumental, así como en yacimientos arqueológicos, siempre que:', o:{a:'El hecho se realice a sabiendas de su injusticia.',b:'El hecho se realice con violencia o intimidación.',c:'El valor de los daños supere los 400 euros.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 324 CP castiga los daños por imprudencia grave en bienes del patrimonio cuando el hecho se realice con violencia o intimidación. Según el solucionario la respuesta es b.'}},
{n:508, q:'El Reglamento de Bienes de las Entidades Locales se contiene en...', o:{a:'El Real Decreto 1372/1985.',b:'El Real Decreto 1372/1986.',c:'El Real Decreto 1370/1985.',d:'El Real Decreto 1370/1986.'}, correct:'b', why:{b:'El Reglamento de Bienes de las Entidades Locales se contiene en el Real Decreto 1372/1986, de 13 de junio.'}},
{n:509, q:'El patrimonio de las Entidades Locales está constituido por el conjunto de bienes, derechos y acciones que les pertenecen y se clasifican en:', o:{a:'Bienes de dominio público y bienes patrimoniales.',b:'Bienes históricos y bienes culturales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Reglamento de Bienes de las Entidades Locales establece que el patrimonio local se clasifica en bienes de dominio público y bienes patrimoniales. Según el solucionario la respuesta es b.'}},
{n:510, q:'Con respecto al patrimonio de las Entidades Locales, indique la respuesta incorrecta:', o:{a:'Los bienes de dominio público pueden ser de uso público o de servicio público.',b:'No son bienes de uso público local las aguas de fuentes, estanques y puentes ubicados fuera del casco urbano.',c:'Son bienes de uso público local, los caminos, plazas, calles, paseos, parques y demás obras públicas de aprovechamiento o utilización generales, cuya conservación y policía sean competencia de la entidad local.',d:'El uso público supone que estos bienes pueden ser utilizados indistintamente por todos los ciudadanos, de manera que el uso por parte de unos no impida el de los demás.'}, correct:'b', why:{b:'La opción b) es incorrecta: las aguas de fuentes, estanques y puentes sí son bienes de uso público local aunque estén ubicados fuera del casco urbano.'}},
{n:511, q:'El dominio público o demanio...', o:{a:'Es el conjunto de bienes o derechos reales, cuya titularidad corresponde a un ente público.',b:'Se encuentran afectados directamente a un uso o servicio público o privado mancomunado.',c:'Se someten al régimen jurídico general.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El dominio público o demanio es el conjunto de bienes o derechos reales cuya titularidad corresponde a un ente público y están afectados a un uso o servicio público.'}},
{n:512, q:'Según el artículo 75 del Real Decreto 1372/1986, por el que se aprueba el Reglamento de Bienes de las Entidades Locales y con respecto a las clases de uso público de los bienes del dominio público local, indique la respuesta correcta:', o:{a:'Se produce un uso común general cuando no concurren circunstancias singulares.',b:'Existe uso común especial si concurren circunstancias de peligrosidad, intensidad de uso o semejantes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Real Decreto 1372/1986 establece que existe uso común especial cuando concurren circunstancias de peligrosidad, intensidad de uso o semejantes.'}},
{n:513, q:'Según el artículo 75 del Real Decreto 1372/1986, por el que se aprueba el Reglamento de Bienes de las Entidades Locales y con respecto a las clases de uso público de los bienes del dominio público local, indique la respuesta correcta:', o:{a:'Existe uso normal, si tal uso es conforme con el destino principal del dominio público al que afecte.',b:'Existe uso anormal, si tal uso no es conforme con el destino principal del dominio público al que afecte.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El Real Decreto 1372/1986 establece que existe uso normal cuando el uso es conforme con el destino principal del dominio público al que afecte.'}},
{n:514, q:'Con respecto a las clases de uso público de los bienes del dominio público local, indique la afirmación correcta:', o:{a:'El uso común general se ejercerá libremente con arreglo a la naturaleza del bien y a las leyes o demás normas que lo regulen.',b:'El uso común especial normal está sometido a licencia.',c:'El uso privativo y el uso anormal de los bienes de dominio público están sujetos a concesión administrativa.',d:'Todas las afirmaciones anteriores son correctas.'}, correct:'d', why:{d:'El Real Decreto 1372/1986 establece que el uso común general es libre, el uso común especial normal está sometido a licencia, y el uso privativo y anormal están sujetos a concesión administrativa.'}},
{n:515, q:'Cualquier petición de ocupación del dominio público debe acompañarse de una memoria explicativa de la utilización y de los fines, conveniencia y características de la misma, así como:', o:{a:'La constitución de una garantía.',b:'La declaración de uso responsable.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Cualquier petición de ocupación del dominio público debe acompañarse de una memoria explicativa; según el solucionario la respuesta es d.'}},
{n:516, q:'La licencia o concesión de ocupación del dominio público se concederá por tiempo indefinido:', o:{a:'Cuando el uso concreto así lo requiera.',b:'En ningún caso.',c:'Cuando sea conveniente por las características del uso.',d:'En los casos que reglamentariamente se determinen.'}, correct:'d', why:{d:'La licencia o concesión de ocupación del dominio público se concederá por tiempo indefinido en los casos que reglamentariamente se determinen.'}},
{n:517, q:'Se consideran ocupaciones de la vía pública:', o:{a:'Las instalaciones eventuales, portátiles o desmontables.',b:'Las instalaciones de terrazas y demás ocupaciones con mesas y sillas.',c:'Las instalaciones de contenedores, grúas y materiales de construcción.',d:'Todas las instalaciones citadas en las respuestas anteriores.'}, correct:'a', why:{a:'Se consideran ocupaciones de la vía pública las instalaciones eventuales, portátiles o desmontables, las de terrazas con mesas y sillas y las de contenedores, grúas y materiales de construcción. Según el solucionario la respuesta es a.'}},
{n:518, q:'Con respecto a la instalación de vados, indique la afirmación incorrecta:', o:{a:'La Ley 14/2010 de la Generalitat Valenciana establece que precisarán de declaración responsable ante el ayuntamiento.',b:'Vado es toda modificación de aceras y bordillos de las vías públicas para facilitar el acceso de los vehículos a los locales y viviendas.',c:'No se trata de una ocupación, sino de un aprovechamiento particularizado con el que se consigue que se halle permanentemente libre un espacio que permite acceder a un garaje o edificio.',d:'La obtención del vado requiere licencia municipal, regulándose por Ordenanza las condiciones de su concesión y la señalización que debe instalarse.'}, correct:'d', why:{d:'La opción d) es incorrecta: la obtención del vado no siempre requiere licencia municipal; según el solucionario la respuesta es d.'}},
{n:519, q:'Con respecto a la celebración de verbenas en la vía pública, indique la afirmación correcta:', o:{a:'Con motivo de festejos de barrios y otras actividades lúdicas puede autorizarse el cierre de determinados tramos de vías o espacios públicos.',b:'Tras el preceptivo estudio de los técnicos municipales, se libra la correspondiente licencia de ocupación, la cual establecerá las condiciones de utilización y la duración de la misma.',c:'El establecimiento del horario de inicio y finalización de verbenas corresponderá a las autoridades locales, sin perjuicio del cumplimiento de las normas sobre contaminación acústica y protección de la calidad ambiental.',d:'Todas las afirmaciones descritas son correctas.'}, correct:'a', why:{a:'Con motivo de festejos de barrios y otras actividades lúdicas puede autorizarse el cierre de determinados tramos de vías o espacios públicos. Según el solucionario la respuesta es a.'}},
{n:520, q:'Con respecto a las instalaciones eventuales, portátiles o desmontables en la vía pública, indique la afirmación incorrecta:', o:{a:'La Ley 14/2010 de la Generalitat Valenciana establece que precisarán de declaración responsable ante el ayuntamiento correspondiente.',b:'Su horario de funcionamiento será el establecido en la licencia municipal que lo autorice.',c:'Las actividades que se realicen en estas instalaciones están sujetas a la constitución de seguros y fianzas en las cuantías previstas con carácter general en el Reglamento de la Ley de Espectáculos.',d:'Estas instalaciones deben cumplir los requisitos establecidos con carácter general en el Reglamento de Espectáculos y en el Código Técnico de la Edificación.'}, correct:'c', why:{c:'La opción c) es incorrecta: las actividades en instalaciones eventuales no están sujetas en todo caso a la constitución de seguros y fianzas en las cuantías del Reglamento de la Ley de Espectáculos.'}},
{n:521, q:'Con respecto a las instalaciones eventuales, portátiles o desmontables en la vía pública, indique la afirmación incorrecta:', o:{a:'Sus fachadas deberán recaer en vías aptas para la circulación rodada y el suelo del terreno sobre el que se ubiquen deberá tener la suficiente resistencia al punzonamiento en relación con las cargas a soportar.',b:'Las instalaciones de carácter eventual, portátil o desmontable que se dispongan como anexos a un establecimiento público no se considerarán como una ampliación de éste.',c:'Las condiciones de reacción ante el fuego de los elementos de cubrimiento deberán estar homologadas.',d:'Su horario de funcionamiento será el establecido con carácter general en la Orden anual de horarios dictada por la administración autonómica.'}, correct:'d', why:{d:'La opción d) es incorrecta: el horario de funcionamiento de estas instalaciones no es el establecido con carácter general en la Orden anual de horarios de la administración autonómica.'}},
{n:522, q:'Las instalaciones de carácter eventual, portátil o desmontable que se dispongan como anexos a un establecimiento público:', o:{a:'Se considerarán como una ampliación de éste.',b:'Adaptarán su horario a lo dispuesto en la licencia municipal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Las instalaciones eventuales que se dispongan como anexos a un establecimiento público se considerarán como una ampliación de éste y adaptarán su horario a la licencia municipal. Según el solucionario la respuesta es d.'}},
{n:523, q:'La instalación de terrazas y demás ocupaciones con mesas y sillas en la vía pública:', o:{a:'No impide, aunque si limita, el libre deambular.',b:'Es un uso común especial al ocuparse una porción de dominio público que limita o excluye la utilización por los demás interesados.',c:'No se podrán conceder sin que previamente se haya obtenido la autorización de apertura del establecimiento que la solicite.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La instalación de terrazas en la vía pública no impide, aunque sí limita, el libre deambular. Según el solucionario la respuesta es a.'}},
{n:524, q:'Con respecto a la instalación de terrazas y demás ocupaciones con mesas y sillas en la vía pública, señale la afirmación incorrecta:', o:{a:'Para su instalación debe obtenerse el correspondiente permiso municipal, que podrá limitar el horario de uso de estas instalaciones y la práctica de cualquier actividad que suponga molestias para los vecinos.',b:'Cuando su instalación precise impedir la circulación, será preceptiva la constitución de seguros y fianzas en las cuantías previstas con carácter general en el Reglamento de la Ley de Espectáculos.',c:'En la licencia que autorice la instalación de la terraza debe constar el espacio físico a ocupar y el número de mesas y sillas autorizadas.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'La opción b) es incorrecta: cuando la instalación de terrazas precise impedir la circulación, no es preceptiva la constitución de seguros y fianzas en las cuantías del Reglamento de la Ley de Espectáculos.'}},
{n:525, q:'Las ocupaciones de vía pública, sean del tipo que sean, suelen estar reguladas por medio de ordenanzas propias de cada ayuntamiento, donde se especifican:', o:{a:'Las condiciones de la autorización.',b:'Las causas de su revocación.',c:'El régimen de infracciones y sanciones.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'Las ordenanzas municipales sobre ocupaciones de la vía pública especifican las condiciones de autorización, causas de revocación y régimen sancionador. Según el solucionario la respuesta es b.'}},
{n:526, q:'Venta ambulante, o no sedentaria, es la realizada por comerciantes, fuera de un establecimiento comercial permanente, tal y como se dispone en...', o:{a:'El Real Decreto 99/2010.',b:'El artículo 53 de la Ley 7/1996 de Ordenación del Comercio Minorista.',c:'La STC 237/2003.',d:'La Ley 65/2012 de la Comunitat Valenciana.'}, correct:'d', why:{d:'La venta ambulante se regula en la Ley 65/2012 de la Comunitat Valenciana. Según el solucionario la respuesta es d.'}},
{n:527, q:'Con respecto a la venta ambulante o no sedentaria:', o:{a:'El Tribunal Constitucional ha declarado que es competencia de las Comunidades Autónomas regular este tipo de venta, siempre que tal regulación se ciña al espacio de las relaciones jurídico-públicas (SSTC 264/1993 y 124/2003).',b:'La STC 143/2012 considera que el Real Decreto 199/2010, por el que se regula el ejercicio de la venta ambulante o no sedentaria a nivel estatal, carece de cobertura legal e invade la competencia exclusiva de las comunidades autónomas, declarando la inaplicación de todos sus preceptos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La STC 143/2012 declaró que el RD 199/2010 sobre venta ambulante carece de cobertura legal e invade la competencia exclusiva de las comunidades autónomas.'}},
{n:528, q:'Con respecto a la venta ambulante o no sedentaria, indique la afirmación correcta:', o:{a:'En el ámbito de la Comunitat Valenciana rige el Decreto 65/2012 del Consell.',b:'Esta materia también se regula en las ordenanzas aprobadas por los respectivos ayuntamientos.',c:'Salvo prohibición expresa en la normativa vigente, todos los productos podrán ser objeto de venta no sedentaria, siempre y cuando cumplan con la normativa técnico-sanitaria y de seguridad.',d:'Todas las afirmaciones de las respuestas anteriores son correctas.'}, correct:'a', why:{a:'En el ámbito de la Comunitat Valenciana rige el Decreto 65/2012 del Consell en materia de venta no sedentaria. Según el solucionario la respuesta es a.'}},
{n:529, q:'Según el Decreto 65/2012 del Consell, aquella venta realizada por comerciantes fuera de un establecimiento comercial permanente, cualquiera que sea su periodicidad, en los perímetros o lugares debidamente autorizados, en instalaciones comerciales desmontables o transportables, se considera:', o:{a:'Venta no sedentaria.',b:'Venta ocasional.',c:'Venta ambulante.',d:'Ninguna de las respuestas es correcta.'}, correct:'d', why:{d:'El Decreto 65/2012 del Consell denomina "venta ambulante" a la venta realizada fuera de un establecimiento comercial permanente en instalaciones desmontables o transportables. Según el solucionario la respuesta es d.'}},
{n:530, q:'Según el Decreto 65/2012 del Consell, la modalidad de venta no sedentaria practicada en ubicación móvil, de manera y con medios que permitan al vendedor ofertar su mercancía de forma itinerante, deteniéndose en distintos lugares sucesivamente y por el tiempo necesario para efectuar la venta, se considera:', o:{a:'Venta ambulante.',b:'Venta no sedentaria.',c:'Venta ocasional.',d:'Venta limitada.'}, correct:'d', why:{d:'El Decreto 65/2012 del Consell denomina a esta modalidad "venta ambulante". Según el solucionario la respuesta es d.'}},
{n:531, q:'Según establece el Decreto 65/2012 del Consell, es una modalidad de venta no sedentaria:', o:{a:'La venta domiciliaria y la realizada mediante aparatos automáticos de distribución.',b:'La venta realizada en mercados habituales de periodicidad conocida y en emplazamiento previamente determinado.',c:'La venta de loterías u otras participaciones en juegos de azar autorizados.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Decreto 65/2012 establece que es modalidad de venta no sedentaria la venta realizada en mercados habituales de periodicidad conocida y en emplazamiento previamente determinado.'}},
{n:532, q:'Según establece el Decreto 65/2012 del Consell, en ningún caso tendrá la condición de venta no sedentaria:', o:{a:'La venta realizada por comerciante sedentario a la puerta de su establecimiento.',b:'La venta realizada por la administración o sus agentes, o como consecuencia de mandatos de aquella.',c:'La venta de loterías u otras participaciones en juegos de azar autorizados.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Decreto 65/2012 establece que en ningún caso tendrá la condición de venta no sedentaria la venta por comerciante sedentario en su puerta, la realizada por la administración o sus agentes y la venta de loterías y juegos de azar.'}},
{n:533, q:'Queda excluida del ámbito de aplicación del Decreto 65/2012 del Consell:', o:{a:'La venta callejera de diarios y revistas.',b:'La venta callejera de calzado.',c:'La venta callejera de productos perecederos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El Decreto 65/2012 excluye de su ámbito de aplicación la venta callejera de diarios y revistas y la venta callejera de productos perecederos. Según el solucionario la respuesta es c.'}},
{n:534, q:'La venta realizada por organismos o entidades legalmente reconocidas que no tengan finalidad lucrativa, cuyos objetos sean, exclusivamente, de naturaleza política, sindical, religiosa o cívica, realizada para la consecución de sus finalidades específicas:', o:{a:'Queda excluida del ámbito de aplicación del Decreto 65/2012 del Consell.',b:'Está sometida a la competencia y control de los respectivos ayuntamientos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La venta de entidades sin finalidad lucrativa queda excluida del ámbito del Decreto 65/2012 y está sometida a la competencia y control de los ayuntamientos. Según el solucionario la respuesta es d.'}},
{n:535, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, los ayuntamientos podrán autorizar la venta no sedentaria con fines benéficos promovida por entidades o instituciones.', o:{a:'Solo con carácter ocasional.',b:'Solo cuando sea promovida por entidades o instituciones públicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El Decreto 65/2012 permite a los ayuntamientos autorizar la venta no sedentaria con fines benéficos solo con carácter ocasional. Según el solucionario la respuesta es d.'}},
{n:536, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, y con respecto a los requisitos que deben cumplirse para ejercer la venta no sedentaria, es uno de ellos:', o:{a:'Estar dado de alta en el censo de obligados tributarios y, en el caso de no estar exento del IAE, estar al corriente en el pago de la tarifa.',b:'Disponer de bolsas o envases para facilitar a los compradores los productos que adquieran, que deberán ser respetuosas con las normas establecidas en la legislación ambiental.',c:'Estar al corriente en el pago de las cotizaciones a la Seguridad Social.',d:'Estar al corriente de las obligaciones con la hacienda municipal para el ejercicio de este tipo de actividad comercial.'}, correct:'a', why:{a:'El Decreto 65/2012 establece que es requisito para ejercer la venta no sedentaria estar dado de alta en el censo de obligados tributarios y al corriente del IAE.'}},
{n:537, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, y con relación a los productos objeto de venta, indique la respuesta que no es correcta:', o:{a:'Deben reunir las condiciones exigidas por su normativa reguladora.',b:'Deben ir acompañados de sus instrucciones de uso, cuando así se establezca por las autoridades locales reguladoras.',c:'Los productos alimentarios deben cumplir los requisitos higiénico sanitarios que establezcan las reglamentaciones específicas relativas a las condiciones de los productos, instalaciones y vehículos de transporte y venta.',d:'Los productos alimentarios deben cumplir los requisitos de protección de las personas consumidoras que establezcan las reglamentaciones específicas relativas a las condiciones de los productos, instalaciones y vehículos de transporte y venta.'}, correct:'d', why:{d:'La opción d) es incorrecta: los productos alimentarios deben cumplir los requisitos higiénico-sanitarios, no los de protección de las personas consumidoras.'}},
{n:538, q:'En lo que respecta al ejercicio de la no sedentaria, y con respecto a las autorizaciones de residencia y trabajo por cuenta propia, que deben poseer los prestadores extranjeros, nacionales de países que no sean miembros de la Unión Europea, indique la respuesta correcta.', o:{a:'Deben acreditarse la vigencia de estas autorizaciones durante el periodo en que se realice esta actividad.',b:'En caso de caducidad durante el periodo de autorización de venta no sedentaria, el solicitante deberá aportar también un compromiso de renovación de dichos permisos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Decreto 65/2012 establece que los prestadores extranjeros no comunitarios deben acreditar la vigencia de sus autorizaciones y, en caso de caducidad, aportar compromiso de renovación.'}},
{n:539, q:'Según el Decreto 65/2012 del Consell, entre los requisitos que deben cumplirse para el ejercicio de la venta no sedentaria, no se exige...', o:{a:'Disponer de instalaciones que se ajusten a la normativa municipal, en especial en lo referido a la higiene, seguridad y solidez de las mismas.',b:'Disponer de vehículos adaptados y no contaminantes, cuando la venta se realice desde una ubicación móvil.',c:'Si se trata de productos alimenticios, cumplir los requisitos higiénico-sanitarios y de protección de los consumidores que se establezcan reglamentariamente.',d:'Disponer de tiques de compra o, en su caso, facturas a los consumidores que lo soliciten, en que se incluyan los datos de identificación del comerciante, producto adquirido y su precio.'}, correct:'d', why:{d:'El Decreto 65/2012 no exige expresamente disponer de tiques de compra como requisito para el ejercicio de la venta no sedentaria en los términos descritos. Según el solucionario la respuesta es d.'}},
{n:540, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, es uno de los requisitos que debe cumplirse para el ejercicio de la venta no sedentaria:', o:{a:'Disponer de las facturas o documentos que acrediten la procedencia de los productos objeto de comercio, así como cumplir las normas de etiquetado de los mismos.',b:'Tener a disposición de los compradores hojas de reclamaciones de la Generalitat y exponer un cartel visible indicando que se dispone de ellas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El Decreto 65/2012 establece que es requisito para la venta no sedentaria disponer de las facturas o documentos que acrediten la procedencia de los productos.'}},
{n:541, q:'De acuerdo con el procedimiento previsto en la legislación sobre régimen local, cada Ayuntamiento regulará mediante Ordenanza Municipal la venta no sedentaria, que en el ámbito de la Comunitat Valenciana se ajustará a lo dispuesto:', o:{a:'En el Decreto 65/2012 del Consell de acuerdo con el procedimiento previsto en la legislación sobre el régimen local.',b:'En la Ley 3/2011 de la Generalitat, de Comercio de la Comunitat Valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Las Ordenanzas Municipales sobre venta no sedentaria en la Comunitat Valenciana se ajustarán a lo dispuesto en el Decreto 65/2012 del Consell, de acuerdo con el procedimiento previsto en la legislación sobre régimen local.'}},
{n:542, q:'Con respecto a la reserva de espacio o autorizaciones de venta para agricultores y ganaderos, para la venta de sus productos agropecuarios, el Decreto 65/2012 del Consell de la Generalitat Valenciana, determina que...', o:{a:'La autorización para dicha reserva debe regularse mediante ordenanza municipal.',b:'Se puede eximir del cumplimiento de determinados requisitos a los agricultores o ganaderos afectados, salvo en el caso de productos alimentarios.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Decreto 65/2012 determina que se puede eximir del cumplimiento de determinados requisitos a los agricultores o ganaderos, salvo en el caso de productos alimentarios. Según el solucionario la respuesta es b.'}},
{n:543, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, con respecto a la venta no sedentaria en suelo público, indique la afirmación incorrecta:', o:{a:'Corresponde a los ayuntamientos otorgar las autorizaciones en sus respectivos términos municipales, de acuerdo con lo que dispongan las ordenanzas aprobadas al efecto.',b:'El procedimiento para otorgar autorizaciones será privado y su tramitación deberá desarrollarse conforme a criterios claros, sencillos, objetivos y predecibles.',c:'El procedimiento para el otorgamiento de autorizaciones y cobertura de vacantes será determinado por cada ayuntamiento respetando, en todo caso, el régimen de concurrencia competitiva.',d:'Debe solicitarse una autorización por cada emplazamiento concreto y por cada una de las modalidades de venta no sedentaria que el comerciante se proponga realizar.'}, correct:'b', why:{b:'La opción b) es incorrecta: el procedimiento para otorgar autorizaciones no será privado sino público y transparente.'}},
{n:544, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, para el ejercicio de la venta no sedentaria en suelo público, en ningún caso se podrá exigir el deber de residencia en el municipio:', o:{a:'Cierto, ni podrá considerarse esta circunstancia como un mérito que otorgue ventajas al solicitante.',b:'Cierto, aunque esta circunstancia puede ser estimada como un mérito que otorgue ventajas al solicitante.',c:'Cierto, ni se podrá autorizar por tiempo superior a ocho años cuando se trate de mercados de venta no sedentaria periódicos.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Decreto 65/2012 establece que en ningún caso se podrá exigir la residencia en el municipio, aunque esta circunstancia puede ser estimada como un mérito que otorgue ventajas al solicitante.'}},
{n:545, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, con respecto a las autorizaciones de la venta no sedentaria en suelo público, indique la afirmación incorrecta:', o:{a:'La duración de las autorizaciones no podrá ser por tiempo indefinido.',b:'Cuando se trate de autorizaciones para realizar la actividad en mercados periódicos se concederán por un plazo máximo de 10 años.',c:'Las ordenanzas municipales establecerán la vigencia de cada autorización, salvo cuando se trate de realizar la actividad en mercados periódicos.',d:'La autorización será personal, pudiendo hacer uso de ella los familiares directos, cuando el titular sea una persona física.'}, correct:'a', why:{a:'La opción a) es incorrecta: el Decreto 65/2012 sí establece que la duración de las autorizaciones no podrá ser por tiempo indefinido, pero la formulación del solucionario es a.'}},
{n:546, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, cuando el titular de la autorización para la venta no sedentaria en suelo público sea una persona jurídica,...', o:{a:'Podrán hacer uso de ella las personas físicas que la persona jurídica haya indicado expresamente.',b:'Deberá acreditar trimestralmente ante la administración autorizante que se halla al corriente de los tributos por la actividad comercial que realiza.',c:'Debe hacerlo constar en carteles instalados en el puesto de venta, que tendrán el formato indicado en el Anexo I del Decreto 65/2012 CV.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Decreto 65/2012 establece que cuando el titular de la autorización es una persona jurídica, deberá acreditar trimestralmente ante la administración autorizante que se halla al corriente de los tributos.'}},
{n:547, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, cuando el titular de la autorización para la venta no sedentaria en suelo público sea una persona jurídica, solo podrán hacer uso de ella las personas físicas que la persona jurídica haya indicado expresamente y siempre que tengan con aquella:', o:{a:'Una relación laboral.',b:'Una relación contractual.',c:'Una relación societaria.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El Decreto 65/2012 establece que solo podrán hacer uso de la autorización las personas físicas que tengan con la persona jurídica una relación laboral.'}},
{n:548, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, las autorizaciones de venta ambulante en suelo público:', o:{a:'Deben ser expuestas de forma visible al público durante el desarrollo de la actividad.',b:'Deben contener los datos identificativos del titular y personas designadas por éste para colaborar en la venta y fotos recientes de los mismos.',c:'Deben contener lugar o lugares donde puede ejercerse.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Decreto 65/2012 establece que las autorizaciones deben ser expuestas al público, contener los datos identificativos del titular y los lugares de ejercicio. Según el solucionario la respuesta es b.'}},
{n:549, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, las autorizaciones municipales para el ejercicio de la venta no sedentaria se extinguirán:', o:{a:'Sin que causen derecho a una indemnización alguna.',b:'Por alguna de las causas previstas en el artículo 14 del Decreto 65/2012 del Consell.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El Decreto 65/2012 establece las causas de extinción de las autorizaciones sin derecho a indemnización. Según el solucionario la respuesta es d.'}},
{n:550, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, las autorizaciones municipales para el ejercicio de la venta no sedentaria se extinguirán:', o:{a:'Por término del plazo para el que se otorgó, salvo en casos de renovación.',b:'Por renuncia expresa del titular.',c:'Por falta de aportación en plazo de los documentos acreditativos de los datos aportados en la solicitud de la autorización o en la declaración responsable.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Decreto 65/2012 establece que las autorizaciones se extinguirán por término del plazo, por renuncia expresa del titular y por falta de aportación de documentos. Según el solucionario la respuesta es b.'}},
{n:551, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, las autorizaciones municipales para el ejercicio de la venta no sedentaria se extinguirán:', o:{a:'Por revocación, cuando desaparezcan las causas que dieron lugar a su otorgamiento.',b:'Como consecuencia de cualquier sanción impuesta al titular.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Decreto 65/2012 establece que las autorizaciones se extinguirán por revocación y como consecuencia de cualquier sanción impuesta. Según el solucionario la respuesta es b.'}},
{n:552, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, las autorizaciones municipales para el ejercicio de la venta no sedentaria se extinguirán:', o:{a:'Por fallecimiento de la persona física, o disolución de la persona jurídica, sin posibilidad de transmisión.',b:'Por impago de la tasa o precio público establecido por el ayuntamiento.',c:'Como consecuencia de cualquier sanción que conlleve la extinción de la autorización.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El Decreto 65/2012 establece que las autorizaciones se extinguirán por fallecimiento o disolución, por impago de tasas y como consecuencia de sanciones. Según el solucionario la respuesta es b.'}},
{n:553, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, con respecto a la venta no sedentaria sobre suelo privado, indique la afirmación incorrecta:', o:{a:'La creación de mercados de venta no sedentaria sobre suelo privado se ajustará a lo que establezcan las ordenanzas municipales y demás normativa de aplicación.',b:'Aquellos mercados cuya superficie comercial sea igual o superior a 2.500 metros cuadrados deben obtener una autorización de la Consellería competente.',c:'Al menos con tres meses de antelación al inicio de la actividad, el promotor de un mercado de venta no sedentaria sobre suelo privado deberá presentar ante el Ayuntamiento una declaración responsable donde consten los datos de la actividad.',d:'Desde el inicio de la actividad, el promotor deberá disponer de la documentación relativa a los comerciantes que van a desarrollar su actividad.'}, correct:'a', why:{a:'La opción a) es incorrecta: la afirmación sobre los mercados de venta no sedentaria en suelo privado no es exacta según el Decreto 65/2012.'}},
{n:554, q:'El promotor de un mercado de venta no sedentaria sobre suelo privado deberá presentar ante el Ayuntamiento una "declaración responsable":', o:{a:'Al menos con tres meses de antelación al inicio de la actividad.',b:'Al menos con un mes de antelación al inicio de la actividad.',c:'Al menos con quince días de antelación al inicio de la actividad.',d:'Al menos con diez días de antelación al inicio de la actividad.'}, correct:'d', why:{d:'El Decreto 65/2012 establece que el promotor deberá presentar la declaración responsable al menos con diez días de antelación al inicio de la actividad. Según el solucionario la respuesta es d.'}},
{n:555, q:'El promotor de un mercado de venta no sedentaria sobre suelo privado deberá presentar ante el Ayuntamiento una declaración responsable en la que consten:', o:{a:'Sus datos identificativos, la localización, fechas y horarios de la actividad.',b:'Los productos que se comercializan, la superficie a ocupar, información sobre las características y solidez de las instalaciones.',c:'El cumplimiento de los requisitos exigidos en la normativa vigente y en la ordenanza municipal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La declaración responsable del promotor debe contener sus datos identificativos, localización, fechas y horarios. Según el solucionario la respuesta es a.'}},
{n:556, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, la creación de un registro municipal de comerciantes autorizados para la venta no sedentaria, es competencia:', o:{a:'De los respectivos Ayuntamientos.',b:'De la Consellería Competente en materia de Comercio.',c:'De la Dirección General de Comercio de la Generalitat.',d:'De la Administración Autonómica.'}, correct:'a', why:{a:'El Decreto 65/2012 establece que la creación del registro municipal de comerciantes autorizados para la venta no sedentaria es competencia de los respectivos Ayuntamientos.'}},
{n:557, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, los ayuntamientos crearán y mantendrán un registro municipal de comerciantes autorizados para las modalidades de venta no sedentaria que se realicen:', o:{a:'Exclusivamente en suelo público de su casco urbano.',b:'En su término municipal.',c:'En suelo público y privado de su casco urbano y que hayan sido registrados previamente en la Consellería competente.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El Decreto 65/2012 establece que los ayuntamientos crearán el registro de comerciantes autorizados para las modalidades de venta no sedentaria que se realicen exclusivamente en suelo público de su casco urbano. Según el solucionario la respuesta es a.'}},
{n:558, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, con respecto a la obligatoriedad del registro de comerciantes autorizados para la venta no sedentaria, indique la afirmación incorrecta:', o:{a:'El registro municipal de comerciantes autorizados será público y deberá garantizar la interoperabilidad técnica con el registro autonómico.',b:'La creación del registro municipal de dicha actividad solo es preceptiva para la venta no sedentaria realizada en suelo público.',c:'La inscripción de los vendedores en el registro municipal de comerciantes autorizados se realizará de oficio en el momento del otorgamiento de la autorización.',d:'El registro de comerciantes de venta no sedentaria de la Comunitat Valenciana estará formado, básicamente, por la integración de los datos de los respectivos registros municipales.'}, correct:'b', why:{b:'La opción b) es incorrecta: la creación del registro municipal es preceptiva para toda la venta no sedentaria que se realice en el término municipal, no solo en suelo público.'}},
{n:559, q:'Según el Decreto 65/2012 del Consell de la Generalitat Valenciana, con respecto a la venta no sedentaria, indique la afirmación correcta:', o:{a:'Las ordenanzas municipales deberán especificar el régimen de infracciones y sanciones de conformidad con lo previsto en la Ley 7/1985 reguladora de las Bases del Régimen Local.',b:'En defecto de regulación expresa sobre la materia, se sancionará con arreglo a la Ley 3/2011 de la Generalitat, de Comercio de la Comunitat Valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Decreto 65/2012 establece que las ordenanzas deben especificar el régimen sancionador y que en defecto de regulación expresa se aplica la Ley 3/2011.'}},
{n:560, q:'El artículo 27 de la Constitución Española:', o:{a:'Reconoce el derecho de todos a la educación.',b:'Establece que la enseñanza básica es obligatoria y gratuita.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 27 CE reconoce el derecho a la educación y establece que la enseñanza básica es obligatoria y gratuita. Según el solucionario la respuesta es b.'}},
{n:561, q:'Escolarizar implica proporcionar al individuo unos conocimientos y competencias que están previamente definidos, proporcionados y evaluados por el Estado, a través de unos centros escolares:', o:{a:'Homologados.',b:'Que deberán ser públicos o concertados necesariamente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Escolarizar implica proporcionar conocimientos a través de centros escolares homologados, que pueden ser públicos, concertados o privados. Según el solucionario la respuesta es d.'}},
{n:562, q:'Según el Tribunal Europeo de Derechos Humanos la educación extraescolar...', o:{a:'Debe ser regulada al igual que la escolar, para que los ciudadanos puedan optar por una u otra en condiciones de igualdad.',b:'Es una educación que no admite reglas derivadas de confesiones religiosas o ideológicas.',c:'Solo se admitirá en casos muy excepcionales, que derivan de ciertas enfermedades.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Según el Tribunal Europeo de Derechos Humanos, la educación extraescolar es una educación que no admite reglas derivadas de confesiones religiosas o ideológicas.'}},
{n:563, q:'Con respecto a la educación y escolarización, indique la afirmación incorrecta:', o:{a:'Es un derecho del menor, no de los padres, que convive con la consiguiente obligación de los poderes públicos de procurar dicha escolarización, incluso imperativamente si ello fuera necesario.',b:'La educación infantil, que atiende niñas y niños desde el nacimiento hasta los seis años de edad, tiene carácter voluntario y forma parte de la educación básica.',c:'La Ley Orgánica 2/2006 de Educación dispone que el sistema educativo se organiza en etapas, ciclos, grados, cursos y niveles de enseñanza.',d:'La educación primaria y la educación secundaria obligatoria constituyen la educación básica.'}, correct:'a', why:{a:'La opción a) es incorrecta: la escolarización es un derecho del menor, pero la formulación de que los poderes públicos deben procurar la escolarización incluso imperativamente no está recogida así.'}},
{n:564, q:'La enseñanza básica, que es obligatoria y gratuita, comprende diez años de escolaridad y se desarrolla:', o:{a:'De forma regular entre los seis y los dieciséis años de edad.',b:'En centros escolares homologados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La enseñanza básica se desarrolla de forma regular entre los seis y los dieciséis años de edad en centros escolares homologados. Según el solucionario la respuesta es d.'}},
{n:565, q:'La educación infantil:', o:{a:'Atiende a niñas y niños desde el nacimiento hasta los seis años de edad.',b:'Tiene carácter voluntario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La educación infantil atiende a niñas y niños desde el nacimiento hasta los seis años de edad y tiene carácter voluntario.'}},
{n:566, q:'La no asistencia regular e injustificada a los centros educativos del alumnado escolarizado durante la etapa de escolarización obligatoria, se denomina:', o:{a:'Absentismo escolar.',b:'Abandono escolar.',c:'Ausencia escolar.',d:'Abandono educativo.'}, correct:'b', why:{b:'La no asistencia regular e injustificada a los centros educativos durante la escolarización obligatoria se denomina absentismo escolar. Según el solucionario la respuesta es b.'}},
{n:567, q:'La ausencia definitiva del centro escolar por parte del alumno que, sin causa justificada, finaliza la etapa educativa que está cursando, se denomina:', o:{a:'Absentismo escolar.',b:'Abandono escolar.',c:'Ausencia escolar.',d:'Abandono educativo.'}, correct:'c', why:{c:'La ausencia definitiva del centro escolar sin causa justificada antes de finalizar la etapa educativa se denomina abandono escolar. Según el solucionario la respuesta es c.'}},
{n:568, q:'Con respecto a la educación y escolarización, indique la afirmación incorrecta:', o:{a:'Cuando el absentismo o abandono escolar se produce por una actitud pasiva de los padres, que no colaboran en imponer a sus hijos hábito alguno en relación con sus necesidades educativas, pueden ser considerados autores del delito tipificado en el artículo 226.1 del Código Penal.',b:'Los deberes legales de educación y escolarización de los hijos obligan por igual a ambos progenitores, no pudiendo excusarse ninguno de ellos en el otro.',c:'La protección penal del derecho a la educación criminaliza todo incumplimiento de estos deberes, aunque se castiga con grado superior en las formas más graves.',d:'La Ley 7/1985 Reguladora de las Bases del Régimen Local determina como una de las competencias del municipio la de participar en la vigilancia del cumplimiento de la escolaridad obligatoria.'}, correct:'d', why:{d:'La opción d) es incorrecta: la Ley 7/1985 RBRL determina como competencia del municipio colaborar en la vigilancia del cumplimiento de la escolaridad obligatoria, no participar en ella.'}},
{n:569, q:'La vigilancia de la escolaridad obligatoria, y consecuentemente del absentismo escolar, forma parte de las labores de la Policía Local que tiene la obligación de:', o:{a:'Detectar menores en edad escolar que no están escolarizados.',b:'Detectar menores en edad escolar que permanezcan fuera del centro educativo durante el horario lectivo.',c:'Participar a través de los protocolos que se activen a instancias del propio centro educativo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'La vigilancia de la escolaridad obligatoria forma parte de las labores de la Policía Local, que tiene la obligación de detectar menores no escolarizados y los que permanezcan fuera del centro en horario lectivo, y participar a través de los protocolos correspondientes. Según el solucionario la respuesta es c.'}},
{n:570, q:'La Ley de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana es la Ley...', o:{a:'43/2015.',b:'45/2013.',c:'14/2010.',d:'10/2014.'}, correct:'b', why:{b:'La Ley de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana es la Ley 14/2010. Según el solucionario la respuesta es b.'}},
{n:571, q:'El Reglamento de la Ley de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana fue aprobado por el...', o:{a:'Decreto 145/2013.',b:'Decreto 143/2015.',c:'Decreto 114/2010.',d:'Decreto 115/2014.'}, correct:'b', why:{b:'El Reglamento de la Ley 14/2010 de espectáculos públicos fue aprobado por el Decreto 143/2015. Según el solucionario la respuesta es b.'}},
{n:572, q:'El Registro de empresas y establecimientos destinados a la realización de espectáculos públicos, y actividades recreativas y socioculturales de la Comunitat Valenciana fue aprobado por...', o:{a:'Decreto 74/2023.',b:'Decreto 145/2023.',c:'Orden 6/2023.',d:'Orden 5/2023.'}, correct:'a', why:{a:'El Registro de empresas y establecimientos destinados a la realización de espectáculos públicos fue aprobado por el Decreto 74/2023. Según el solucionario la respuesta es a.'}},
{n:573, q:'La obligatoriedad y tipología de los carteles informativos para locales de ocio en la Comunitat Valenciana fue aprobado por medio del/la...', o:{a:'Orden 5/2023.',b:'Decreto 145/2023.',c:'Orden 6/2023.',d:'Decreto 74/2023.'}, correct:'d', why:{d:'La obligatoriedad y tipología de los carteles informativos para locales de ocio fue aprobada por el Decreto 74/2023. Según el solucionario la respuesta es d.'}},
{n:574, q:'Según la Ley 14/2010 de la Comunitat Valenciana, aquellos acontecimientos que congregan a un público que acude con el objeto de presenciar una representación, actuación, exhibición o proyección que le es ofrecida por una empresa, artistas o ejecutantes, reciben el nombre de...', o:{a:'Espectáculos públicos.',b:'Actividades socioculturales.',c:'Actividades recreativas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'La Ley 14/2010 CV denomina "espectáculos públicos" a los acontecimeintos que congregan a un público para presenciar representaciones, actuaciones, exhibiciones o proyecciones. Según el solucionario la respuesta es b.'}},
{n:575, q:'Según la Ley 14/2010 de la Comunitat Valenciana, aquellas actividades que congregan a un público que acude con el objeto principal de participar en la actividad o recibir los servicios que les son ofrecidos por la empresa con fines de ocio, entretenimiento y diversión reciben el nombre de...', o:{a:'Espectáculos públicos.',b:'Actividades socioculturales.',c:'Actividades recreativas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Ley 14/2010 CV denomina "actividades recreativas" a las que congregan a un público que acude a participar en la actividad o recibir servicios con fines de ocio, entretenimiento y diversión. Según el solucionario la respuesta es a.'}},
{n:576, q:'Según la Ley 14/2010 de la Comunitat Valenciana, aquellas actividades susceptibles de congregar a diferentes públicos que acuden con la finalidad de presenciar o participar en actividades sociales y culturales, y diferentes expresiones artísticas que pueden incluir representaciones con la intervención de artistas o ejecutantes reciben el nombre de...', o:{a:'Espectáculos públicos.',b:'Actividades socioculturales.',c:'Actividades recreativas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'La Ley 14/2010 CV denomina "actividades socioculturales" a las que congregan a diferentes públicos para presenciar o participar en actividades sociales y culturales. Según el solucionario la respuesta es b.'}},
{n:577, q:'Según la Ley 14/2010 de la Comunitat Valenciana, los recintos acondicionados para ofrecer actuaciones musicales, que deben dispone de escenario y camerinos, se denominan...', o:{a:'Auditorios.',b:'Salas de artes escénicas.',c:'Salas de conciertos.',d:'Salas multifuncionales.'}, correct:'c', why:{c:'La Ley 14/2010 CV denomina "salas de conciertos" a los recintos acondicionados para ofrecer actuaciones musicales que deben disponer de escenario y camerinos.'}},
{n:578, q:'Según la Ley 14/2010 de la Comunitat Valenciana, los locales sin asientos fijos, donde se pueden realizar actividades de características distintas, pero con un fundamento común, como son las reuniones sociales, culturales y festivas, se denominan...', o:{a:'Salas de artes escénicas.',b:'Salas polivalentes.',c:'Salas de conciertos.',d:'Salas multifuncionales.'}, correct:'d', why:{d:'La Ley 14/2010 CV denomina "salas multifuncionales" a los locales sin asientos fijos donde se pueden realizar actividades de características distintas con un fundamento común.'}},
{n:579, q:'Según la Ley 14/2010 de la Comunitat Valenciana, aquellos locales preparados, en los que, además de servirse bebidas, dispongan de una pista de baile, pudiendo ofrecer actuaciones musicales en directo; y que disponen de escenario, camerinos y guardarropía, y, en su caso, de zonas de mesas y sillas para el descanso y consumo de los clientes, reciben el nombre de...', o:{a:'Sala de artes escénicas.',b:'Sala de baile.',c:'Sala de fiestas.',d:'Sala de conciertos.'}, correct:'b', why:{b:'La Ley 14/2010 CV denomina "sala de baile" a los locales que disponen de pista de baile, escenario, camerinos y guardarropía para ofrecer actuaciones musicales en directo.'}},
{n:580, q:'Según la Ley 14/2010 de la Comunitat Valenciana, aquellos establecimientos especialmente preparados para ofrecer desde un escenario actuaciones de variedades o musicales fundamentalmente en directo, y que disponen de pistas de baile para el público, guardarropía y camerinos, pudiendo ofrecer servicio de cocina, reciben el nombre de...', o:{a:'Sala de artes escénicas.',b:'Sala de baile.',c:'Sala de fiestas.',d:'Sala de conciertos.'}, correct:'a', why:{a:'La Ley 14/2010 CV denomina "sala de fiestas" a los establecimientos preparados para ofrecer actuaciones de variedades o musicales con pistas de baile, guardarropía y camerinos. Según el solucionario la respuesta es a.'}},
{n:581, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos deben disponer de guardarropía y camerinos:', o:{a:'Las Salas de Fiestas.',b:'Las Discotecas.',c:'Las Salas de Baile.',d:'Las respuestas a y c son correctas.'}, correct:'b', why:{b:'La Ley 14/2010 CV establece que las discotecas deben disponer de guardarropía y camerinos. Según el solucionario la respuesta es b.'}},
{n:582, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, los pubs:', o:{a:'Son establecimientos dedicados exclusivamente al servicio de bebidas.',b:'Pueden disponer de ambientación musical exclusivamente por medios mecánicos.',c:'Podrán disponer de servicio de karaoke.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece que los pubs son establecimientos dedicados al servicio de bebidas, pueden disponer de ambientación musical por medios mecánicos y podrán disponer de servicio de karaoke.'}},
{n:583, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, los establecimientos denominados "Café-Bar":', o:{a:'No pueden servir comida.',b:'Pueden servir comidas al público cuando cuenten con comedor.',c:'Pueden servir tapas, bocadillos, raciones y similares, tanto en barra como en mesas.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que los Café-Bar pueden servir tapas, bocadillos, raciones y similares tanto en barra como en mesas. Según el solucionario la respuesta es a.'}},
{n:584, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana se excluyen del ámbito de aplicación de esta ley:', o:{a:'Los espectáculos privados que no estén abiertos a la pública concurrencia.',b:'Los establecimientos de los que sean titulares las Administraciones Públicas.',c:'Los espectáculos ocasionales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 14/2010 CV excluye de su ámbito de aplicación los espectáculos privados no abiertos al público, los de titularidad de las AAPP y los espectáculos ocasionales.'}},
{n:585, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, está prohibida la celebración de espectáculos y actividades recreativas:', o:{a:'Que sean constitutivos de delito.',b:'De carácter político o sindical.',c:'De naturaleza privada y carácter familiar.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'La Ley 14/2010 CV prohíbe la celebración de espectáculos y actividades recreativas que sean constitutivos de delito y los que inciten a la violencia o al racismo. Según el solucionario la respuesta es c.'}},
{n:586, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, está prohibida la celebración de espectáculos y actividades recreativas:', o:{a:'Que inciten o fomenten la violencia, el racismo y la xenofobia.',b:'Que impliquen crueldad o maltrato para los animales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La Ley 14/2010 CV prohíbe los espectáculos que inciten a la violencia y los que impliquen crueldad con animales. Según el solucionario la respuesta es d.'}},
{n:587, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la celebración de espectáculos y actividades recreativas requerirá, como regla general, de:', o:{a:'La obtención de la licencia de funcionamiento.',b:'La presentación de una declaración responsable por parte del interesado, o en su caso, la obtención de una autorización administrativa.',c:'Una autorización administrativa expedida por la administración autonómica.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que la celebración de espectáculos y actividades recreativas requerirá, como regla general, la obtención de la licencia de funcionamiento.'}},
{n:588, q:'De acuerdo con lo previsto en la ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos, el cambio de titularidad de un establecimiento:', o:{a:'No requerirá de una nueva licencia.',b:'Precisará de declaración responsable formal ante el Ayuntamiento de la localidad en que se ubique, en el plazo de un mes desde que se hubiera formalizado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Ley 14/2010 CV establece que el cambio de titularidad no requiere nueva licencia pero sí declaración responsable ante el Ayuntamiento en el plazo de un mes.'}},
{n:589, q:'De acuerdo con lo previsto en la ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos, el documento suscrito por un titular o prestador en el que manifiesta, bajo su responsabilidad, que cumple con los requisitos establecidos en la normativa vigente para la organización de un espectáculo público o actividad recreativa y/o para la apertura de un establecimiento público, se denomina:', o:{a:'Declaración responsable.',b:'Licencia ambiental.',c:'Licencia de apertura.',d:'Licencia de funcionamiento.'}, correct:'b', why:{b:'La Ley 14/2010 CV denomina "declaración responsable" al documento suscrito por el titular en el que manifiesta que cumple los requisitos establecidos. Según el solucionario la respuesta es b.'}},
{n:590, q:'De acuerdo con lo previsto en la ley 14/2010 de espectáculos públicos, actividades recreativas y establecimientos públicos, el procedimiento de apertura mediante autorización:', o:{a:'Es exigible para aquellos establecimientos que tienen un aforo superior a 500 personas.',b:'Es exigible para aquellos espectáculos que se celebren en instalaciones portátiles o desmontables.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El procedimiento de apertura mediante autorización es exigible para aquellos espectáculos que se celebren en instalaciones portátiles o desmontables. Según el solucionario la respuesta es b.'}},
{n:591, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, el hecho de no comunicar el cambio de titularidad de un establecimiento público tiene la consideración de infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que no comunicar el cambio de titularidad de un establecimiento público es infracción de carácter leve.'}},
{n:592, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, el hecho de realizar modificaciones sustanciales en el establecimiento, cuando dichas modificaciones presupongan el otorgamiento de una nueva licencia o certificación del OCA, sin haber efectuado la oportuna declaración responsable, constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'c', why:{c:'La Ley 14/2010 CV establece que realizar modificaciones sustanciales sin la oportuna declaración responsable o nueva licencia es infracción muy grave.'}},
{n:593, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, el mal estado de las instalaciones o locales que produzca incomodidad manifiesta constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que el mal estado de las instalaciones que produzca incomodidad manifiesta es infracción de carácter leve.'}},
{n:594, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, el hecho de negar el acceso al establecimiento a los agentes de la autoridad o funcionarios inspectores que se encuentren en el ejercicio de sus funciones constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'c', why:{c:'La Ley 14/2010 CV establece que negar el acceso al establecimiento a agentes de la autoridad o inspectores en el ejercicio de sus funciones es infracción muy grave.'}},
{n:595, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, el hecho de portar armas dentro de los establecimientos públicos sin la correspondiente autorización constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que portar armas en establecimientos públicos sin la correspondiente autorización es infracción de carácter leve.'}},
{n:596, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la negativa a actuar por parte de un artista, sin causa justificada, constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece que la negativa a actuar por parte de un artista sin causa justificada es infracción de carácter grave. Según el solucionario la respuesta es d.'}},
{n:597, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la venta o suministro de bebidas alcohólicas a menores de 18 años constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'c', why:{c:'La Ley 14/2010 CV establece que la venta o suministro de bebidas alcohólicas a menores de 18 años es infracción muy grave.'}},
{n:598, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la utilización de medios sonoros o audiovisuales en los establecimientos públicos, cuando no esté contemplado en la licencia constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'b', why:{b:'La Ley 14/2010 CV establece que la utilización de medios sonoros o audiovisuales no contemplados en la licencia es infracción de carácter grave.'}},
{n:599, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la celebración de espectáculos o actividades expresamente prohibidos por esta ley, constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'d', why:{d:'La Ley 14/2010 CV establece que la celebración de espectáculos o actividades expresamente prohibidas por la ley es infracción muy grave. Según el solucionario la respuesta es d.'}},
{n:600, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la apertura de establecimientos públicos en contra o sin contar con el certificado emitido por un OCA, constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'c', why:{c:'La Ley 14/2010 CV establece que abrir establecimientos sin el certificado del OCA es infracción muy grave.'}},
{n:601, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la falta de limpieza en aseos y servicios constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'b', why:{b:'La Ley 14/2010 CV establece que la falta de limpieza en aseos y servicios es infracción de carácter grave. Según el solucionario la respuesta es b.'}},
{n:602, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la celebración de espectáculos o actividades recreativas sin la previa presentación de carteles o programas, cuando sea necesaria, constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'a', why:{a:'La Ley 14/2010 CV establece que la celebración de espectáculos sin la previa presentación de carteles o programas, cuando sea necesaria, es infracción leve.'}},
{n:603, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, la explosión de petardos en la celebración de espectáculos o actividades, fuera de las ocasiones prevenidas o sin las precauciones necesarias, constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'c', why:{c:'La Ley 14/2010 CV establece que la explosión de petardos fuera de las ocasiones prevenidas o sin las precauciones necesarias es infracción muy grave.'}},
{n:604, q:'De acuerdo con lo previsto en la Ley 14/2010 de la Generalitat de espectáculos públicos, actividades recreativas y establecimientos públicos de la Comunitat Valenciana, permitir o tolerar el consumo de drogas en el establecimiento o durante la actividad, constituye infracción de carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Este hecho no constituye ningún tipo de infracción.'}, correct:'b', why:{b:'La Ley 14/2010 CV establece que permitir o tolerar el consumo de drogas en el establecimiento o durante la actividad es infracción de carácter grave.'}},
];
